window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["tech"] = window.COMMON_BANK["tech"] || {name:"科技常识", items:[]};
window.COMMON_BANK["tech"].items.push(
{"id": "tech-1", "q": "下列关于生活中数学现象的表述错误的是：", "options": ["用瓷砖铺地，只有用正三角、四角、六角、八角这四种正多角砖才能刚好将地铺满", "圆形的井盖是利用了直径相等原理，这样不论怎么移动井盖，盖子都不会掉下去", "每个平面地图都可以只用四种颜色来染色，而且没有两个邻接的区域颜色相同", "世界上只有五种正多面体，即正四、六、八、十二、二十面体"], "a": 0, "e": "A】本题考查科技常识。A项错误，正多角形瓷砖能刚好把地面铺满，则每个角应为的约数。根据多边形内角和公式可知，正八角形的瓷砖一个角的度数为，不能被整除。B项正确，圆的每一条直径均相等，井盖设计为圆形，无论如何转动其直径长度都不变，因此不会掉下去。C项正确，根据四色定理，只需要四种颜色就可以将平面地图都涂上颜色，且保证相邻两个区域颜色不同。D项正确，正多面体要求必须是多个全等的正多边形组成，满足此要求的只有正四面体、正六面体、正八面体、正十二面体和正二十面体五种类型。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-2", "q": "电影《流浪地球》反映了人类生存与太阳密不可分。下列现象与太阳辐射无关的是：", "options": ["火山的喷发", "风的形成", "煤炭的形成", "植物的生长"], "a": 0, "e": "A】本题考查科技常识。太阳辐射是指太阳以电磁波的形式向外传递能量，是指太阳向宇宙空间发射的电磁波和粒子流。A项错误，火山喷发，是一种奇特的地质现象，是地壳运动的一种表现形式，也是地球内部热能在地表的一种最强烈的显示。火山爆发属于地球内力作用，太阳辐射属于外力作用，二者没有直接的关系。B项正确，风就是水平运动的空气，空气产生运动，主要是由于地球上各纬度所接受的太阳辐射强度不同而形成的。C项正确，煤炭是化石能源，是通过远古的生物吸收太阳辐射的能量之后，将碳元素从大气中分离出来，存储在体内，然后在长时间的埋藏经过复杂的化学反应后形成的固体可燃性矿物。D项正确，可见光辐射又称光合有效辐射，是太阳辐射光谱中0.40～0.70微米波谱段的辐射，由紫、蓝、青、绿、黄、橙、红等7色光组成，是绿色植物进行光合作用所必须的和有效的太阳辐射能，对植物生长有重要作用和影响。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-3", "q": "中国的极地事业已经走过30 多个年头。下列属于我国北极科学考察站的是：", "options": ["长城站", "泰山站", "黄河站", "中山站"], "a": 2, "e": "C】本题考查科技常识。A项错误，长城站是中国在南极建立的第一个科学考察站。1984年12月31日开工，1985年2月20日竣工，位于南极察站。B项错误，泰山站是继长城站、中山站、昆仑站之后我国的第四个南极科学考察站。2014年2月8日，泰山站正式建成开站。D项错误，中山站是我国第二个南极考察站，建立于1989年2月26日，位于东南极大陆拉斯曼丘陵。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-4", "q": "最近一段时间，勒索病毒在全球集中爆发，我国的部分高校和政府机构受到攻击，暴露出我国网络安全防范意识和水平的不足。关于勒索病毒网络攻击，下列选项表述正确的是：", "options": ["勒索软件是一种简单的网络攻击", "加强内网自主操作系统建设是防范勒索病毒的重要途径", "只要采取了网络隔离技术就可以防止勒索病毒的攻击", "勒索病毒网络攻击不是以金钱为目的"], "a": 1, "e": "B】本题考查的是科技常识的相关知识。A项错误，一般勒索病毒，运行流程复杂，且针对关键数据以加密函数的方式进行隐藏，是一种复杂的网络攻击方式。B项正确，我们可以从安全技术和安全管理两方面入手，加强内网自主操作系统建设可以有效防范勒索病毒攻击。C项错误，勒索病毒，是一种新型电脑病毒，主要以邮件、程序木马、网页挂马的形式进行传播，当网络隔离后，移动储存设备也可能会使计算机感染勒索病毒。D项错误，勒索病毒通过对用户手机锁屏，勒索用户付费解锁，以金钱为目的，对用户财产和手机安全均造成严重威胁。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-5", "q": "在同一城市，不同片区的居民收到的天气预报往往不一样，且每隔数小时都会更新一次。这种天气预报法属于：", "options": ["定性预报法", "网格化预报法", "定点预报法", "描述性预报法"], "a": 1, "e": "B】本题考查科技常识。网格化预报法，就像地球上的经纬网一样，把中国以及每个城市所在的区域分解成许多个5公里5公里，甚至1公里", "tag": "科技常识"},
{"id": "tech-6", "q": "下列说法中，正确的一项是（）", "options": ["海昏侯墓与曾侯乙墓是在同一个省份发现的", "藻类植物可以用作监测空气污染程度的指示植物", "每天我国最先迎来黎明的地方是珍宝岛", "秋天有的树叶变红是因为树叶中的红色花青素超过叶绿素"], "a": 3, "e": "D】本题主要考查生物常识有关内容。A项错误，海昏侯墓位于江西省南昌市，是目前我国发现的面积最大、保存最好、内涵最丰富的汉代侯国聚落遗址。曾侯乙墓位于湖北省随州市，是战国早期曾侯乙的一座墓葬。两座墓葬并不是在同一个省份被发现的。B项错误，苔藓植物的叶只有一层细胞，二氧化硫等有毒气体可以从背腹两面侵入叶细胞，使苔藓植物的生存受到威胁。因此苔藓植物可以用作监测空气污染程度的指示植物，而藻类植物则不能。水质监测常用藻类植物。C项错误，珍宝岛位于黑龙江支流乌苏里江主航道中心左侧，东经133度，是一处名传中外的战争遗址。而我国最先迎来黎明的地方是黑龙江省黑瞎子岛，位于东经135度。D项正确，秋天来临时阳光依旧强烈，温度却慢慢降低，叶绿素因遭到破坏渐渐消失，而在强光、低温、干旱的条件下，树叶在凋落前会产生大量的红色花青素，红色花青素的含量超过叶绿素树叶进而变红。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-7", "q": "互联网上每一个网络或每一台主机所分配的逻辑地址称为IP 地址。目前，IP 地址主要有IPv4 地址和IPv6 地址两大类别。下列对应错误的是：", "options": ["192.168.0.57——IPv4 地址", "10.255.8.239——IPv4 地址", "0D-89-A5-9B-F3-61——IPv6 地址", "2016：DB8：0：2DE：A13——IPv6 地址"], "a": 2, "e": "C】本题考查计算机相关的常识。A、B两项正确，IPv4中规定IP地址长度为32位。一般的书写法为4个用小数点分开的十进制数。C项错误，IPv6的地址长度为128位，采用十六进制表示。IPv6有3种表示方法，分别为冒分十六进制表示法、0位压缩表示法、内嵌IPv4地址表示法。该项表示的是主机的物理地址，而不是IP地址。D项正确，该项是利用冒分十六进制法所表示的IPv6地址。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-8", "q": "钛和钛合金被誉为21 世纪最有前途的金属材料。它具有熔点高、抗腐蚀能力强等特点，尤其与人体器官具有很好的生物相容性。下列用途不切合实际的是：", "options": ["钛可以用来制造人造膝关节", "钛合金用于制造潜艇的壳体", "极细的钛粉是造火箭的材料", "钛往往被用来制作钢化玻璃"], "a": 3, "e": "D】本题考查科技常识，主要涉及钛用途方面的知识。A项正确，人造膝关节含金属和塑料两大部分，金属部分包括钛合金或钴铬合金所铸成的股骨、胫骨及髌骨关节，故钛可以用来制造人造膝关节。B项正确，钛合金有强度高、重量轻、耐腐蚀、非磁性等特点，非常适合在舰艇上使用，利用钛合金制造潜艇壳体，不仅没有磁性，而且减轻了重量，可以使潜艇的下潜深度超过1000m。C项正确，由于钛的高抗拉强度－密度比、优良的抗腐蚀性、抗疲乏性、抗裂痕性及能够在没有蠕变的情况下抵受适度高温的性质，钛合金被用于航空器、装甲敷板、海军舰只、航天器与导弹的制造中，故极细的钛粉可以用于制造火箭。D项错误，钢化玻璃原材料与普通平板玻璃相同，一般是用多种无机矿物(如石英砂、硼砂、硼酸、重晶石、碳酸钡、石灰石、长石、纯碱等)为主要原料，另外加入少量辅助原料制成的。它的主要成分为二氧化硅和其他氧化物，故钛通常不被用来制作钢化玻璃。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-9", "q": "沉管隧道就是将若干个预制段分别浮运到海面(河面)现场，并逐个沉放在已疏浚好的基槽内，以此修建的水下隧道。以下隧道采用了外海环境沉管隧道技术的是（）。", "options": ["广州珠江隧道", "深圳地铁隧道", "贵广高铁隧道", "港珠澳大桥隧道"], "a": 3, "e": "D】本题考查我国主要隧道的施工方法。A项错误，广州珠江隧道全长1238.5米，其中全长475米的河中段隧道是我国大陆首次采用沉管法设计施工的大型水下隧道，但是并非题干所描述的外海环境。B项错误，深圳地铁在深圳市内及近郊，不穿越大的江河湖海，无须大型水下隧道，不具备沉管施工条件。C项错误，贵广高铁地处西南复杂艰险山区，峡高谷深，施工难度极高。这条全长856公里的铁路，有二分之一穿行于地下，但无穿越漂河流湖泊的隧道，因此不具备沉管施工条件。D项正确，港珠澳大桥全程55公里，是世界上最长的跨海大桥，其中一条6.7公里的海底隧道，采用了沉管隧道技术，实现桥梁与隧道的转换，这也是我国第一次在外海环境下建沉管隧道。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-10", "q": "水力发电是直接利用水的动能作为原动力，驱动发电机工作的发电方式。以下属于其优点的是（）。①发电设施工程建设投资少、周期短、发电效率高。②发电过程中不会产生污染环境的大量废气和废渣。③水用作发电后，还可用于其他用途。", "options": ["①②③", "仅有①和②", "仅有②和③", "仅有③"], "a": 2, "e": "【C】本题考查科技常识，主要涉及水力发电的相关知识。①水力发电，需要人工修筑能集中水流落差和调节流量的水工建筑物，如大坝、引水管涵等。因此工程投资大、建设周期长，但水力发电效率高，机组启动快。②水力发电不使用燃料，因此不会产生污染环境的废气和废渣。③水力发电对水本身没有污染，因此发电的水也可以用于灌溉和水产养殖等其他用途。可知①表述错误，②③表述正确。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-11", "q": "由我国天文学家南仁东于1994 年提出构想，历时22 年建成，于2016 年9 月25 日落成启用的FAST 工程，是由中国科学院国家天文台主导建设，具有我国自主知识产权、世界最大单口径、最灵敏的射电望远镜，也被称为天眼工程。FAST意为：", "options": ["感光快", "建设快", "世界最大望远镜", "500 米口径球面射电望远镜"], "a": 3, "e": "【D】本题考查科技常识。FAST是Five-hundred-meterApertureSphericalradioTelescope的英文简称，其意思为500米口径球面射电望远镜。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-12", "q": "下列科学家中，其研究领域与美国“曼哈顿工程”所涉领域相同的是", "options": ["华罗庚", "邓稼先", "李四光", "竺可桢"], "a": 1, "e": "【B】本题主要考查科学家与其从事领域的对应。“曼哈顿工程”是指美国在1942年6月开始实施利用核裂变反应来研制原子弹的计划。A项错误，华罗庚，我国著名数学家，中国科学院院士，是中国解析数论、矩阵几何学、自守函数论与多元复变函数论等多方面研究的创始人和开拓者，其并不涉及核物理的研究。B项正确，邓稼先，我国著名核物理学家，中国科学院院士，是中国核武器研制工作的开拓者和奠基者，为中国核武器、原子武器的研发做出了重要贡献。其研究领域和美国的“曼哈顿工程”所涉及的内容相同。C项错误，李四光原名李仲揆，我国著名地质学家、教育家和社会活动家，是中国地质力学的创立者，中国现代地球科学和地质工作的主要领导人和奠基人之一，其并不涉及核物理的研究。D项错误，竺可桢，我国近代著名气象学家、地理学家、教育家。中国科学院院士，中国近代地理学和气象学的奠基者，其并不涉及核物理的研究。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-13", "q": "海绵城市，指城市能够像海绵一样，在适应环境变化和应对自然灾害等方面具有良好的“弹性”，下雨时吸水、蓄水、渗水、净水。需要时将蓄存的水“释放”并加以利用。下列属于“城市海绵体”的是：", "options": ["完善的地下排水管网，绿地、花园、大型写字楼等城市配套设施", "江河、湖、湿地等水系，绿地、花园、可渗透路面等城市配套设施", "完善的地下排水管网，绿地、花园、硬质柏油或水泥等城市配套设施", "江河、湖、湿地等水系，城市花园、硬质柏油或水泥等城市配套设施"], "a": 1, "e": "【B】海绵城市，是新一代城市雨洪管理概念，是指城市在适应环境变化和应对雨水带来的自然灾害等方面具有良好的“弹性”，也可称之为“水弹性城市”。建设海绵城市就要有“海绵体”。“城市海绵体”既包括河、湖、池塘等水系，也包括绿地、花园、可渗透路面这样的城市配套设施。雨水通过这些“海绵体”下渗、滞蓄、净化、回用，最后剩余部分径流通过管网、泵站外排，从而可有效提高城市排水系统的标准，缓减城市内涝的压力。《国务院办公厅关于推进海绵城市建设的指导意见》中指出：推进海绵型道路与广场建设，在非机动车道、人行道、停车场、广场等扩大使用透水铺装，推行道路与广场雨水的收集、净化和利用，减轻对市政排水系统的压力。B项符合城市海绵体的要求。A项错误：没有提到可渗透路面这一重要的城市配套设施，且大型写字楼也无法体现排水功能。C、D项中的硬质柏油和水泥路面透水率低，不利于排解城市洪涝。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-14", "q": "下列常见的心理现象与成语对应错误的是：", "options": ["晕轮效应——爱屋及乌", "首因效应——一鼓作气", "门槛效应——得寸进尺", "从众效应——人云亦云"], "a": 1, "e": "【B】晕轮效应又称“光环效应”，属于心理学范畴，是指当认知者对一个人的某种特征形成好或坏的印象后，他还倾向于据此推论该人其他方面的特征。本质上是一种以偏概全的认知上的偏误。晕轮效应愈来愈多地被应用在企业管理上，其对组织管理的负面影响主要是体现在各种组织决策上。爱屋及乌指的是因为爱一个人而连带爱他屋上的乌鸦。比喻爱一个人而连带地关心到与他有关的人或物。两者意思对等，因此A项正确。门槛效应又称得寸进尺效应，是指一个人一旦接受了他人的一个微不足道的要求，为了避免认知上的不协调，或想给他人以前后一致的印象，就有可能接受更大的要求。这种现象，犹如登门槛时要一级台阶一级台阶地登，这样能更容易更顺利地登上高处。因此C项正确。以和他人保持一致。也就是通常人们所说的“随大流”。人云亦云指的是人家怎么说，自己也跟着怎么说。指没有主见，只会随声附和。两者意思对等，因此D项正确。首因效应指交往双方形成的第一次印象对今后交往关系的影响，也就是“先入为主”带来的效果。虽然这些第一印象并非总是正确的，但却是最鲜明、最牢固的，并且决定着以后双方交往的进程。如果一个人在初次见面时给人留下良好的印象，那么人们就愿意和他接近，彼此也能较快地取得相互了解，并会影响人们对他以后一系列行为和表现的解释。一鼓作气出自《曹刿论战》，意思是第一次击鼓能够振作士兵的勇气，第二次击鼓士兵的勇气会衰弱，第三次击鼓士兵的勇气就竭尽了。后多喻趁锐气旺盛之时一举成事或鼓足干劲，一往直前。显然，首因效应和一鼓作气的意思不对应。因此B项错误。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-15", "q": "关于中药，下列归类正确的是：", "options": ["辛味药：连翘、杏仁", "甘味药：当归、人参", "酸味药：陈皮、黄连", "苦味药：黄柏、乌梅"], "a": 1, "e": "【B】A项错误，辛味药辛温芳香，杏仁是苦味药；B项正确，甘味药的主要成分有氨基酸、糖、维生素等，可提高人体的抗病能力，当归、人参都是甘味药；C项错误，黄连不是酸味药，是苦味药；D项错误，乌梅是酸味药，不是苦味药。故正确答案为B。本题相关知识点：中药五味理论最早见诸于《内经》《本经》中。所谓五味，是指药物有酸、苦、甘、辛、咸五种不同的味道，因而具有不同的治疗作用。有些还具有淡味或涩味，因而实际上不止五种，但五味是最基本的。辛：“能散、能行”，即具有发散、行气行血的作用。如苏叶、木香、川芎等。甘：“能补、能和、能缓”，即具有补益、和中、调和药性和缓急止痛的作用。如人参、熟地、饴糖、甘草等。酸：“能收、能涩”，即具有收敛、固涩的作用。如五味子、乌梅、五倍子、山茱萸等。苦：“能泄、能燥、能坚”，即具有清泄火热、泄降气逆、通泄大便、燥湿、坚阴（泻火存阴）等作用。如黄芩、桅子、杏仁、陈皮、大黄等。咸：“能下、能软”，即具有泻下通便、软坚散结的作用。如芒硝，海藻、牡蛎、鳖甲等。", "tag": "科技常识"},
{"id": "tech-16", "q": "下列关于医学知识的说法不正确的是：", "options": ["肝脏的主要功能之一是分解排除血液中的毒素", "放疗中要使用放射线进行照射", "砒霜在中医里可以入药", "针灸中的“灸”是指用针扎刺人体穴位"], "a": 3, "e": "【D】本题考查科技常识。A项正确，肝脏是人体最重要的代谢和解毒器官。人体代谢过程中所产生的一些有害废物及外来的毒物、毒素、药物的代谢和分解产物，均在肝脏解毒。B项正确，放射治疗是利用一种或多种电离辐射对恶性肿瘤及一些良性病进行的治疗，即利用放射线照射治疗。C项正确，砒霜在中医中常用于治疗痔疮，瘰疬，痈疽恶疮，走马牙疳，癣疮，寒痰哮喘，疟疾，休息痢等疾病。D项错误，针灸是针法和灸法的总称。针法是指用针扎刺人体穴位来预防和治疗疾病。灸法是以预制的灸炷或灸草在体表一定的穴位上烧灼、熏熨，利用热的刺激来预防和治疗疾病。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-17", "q": "下列关于武器装备的说法中错误的是：", "options": ["尼米兹级航母是美军装备的核动力航空母舰", "S300 导弹是俄罗斯生产的高空防空导弹", "枭龙是我国生产的性能优良的无人机", "F-22 是美军装备的先进的隐身战机"], "a": 2, "e": "【C】本题主要考查科技常识中的军事常识。A项正确，尼米兹级航母是美国综合作战能力最强的现役核动力航空母舰，也是目前世界上排水量最大、载机最多、现代化程度最高的一级核动力航空母舰。B项正确，S300导弹系统是俄罗斯研发生产的第三代地对空导弹系统的合称，共有三种基本型号S-300P、S-300V、S-", "tag": "科技常识"},
{"id": "tech-18", "q": "十八世纪一位德国数学家在写给著名数学家欧拉的一封信中，提出一个猜想。该猜想可以表述为：（一）任何不小于6的偶数，都是两个奇素数之和；（二）任何不小于9 的奇数，都是三个奇素数之和。我国著名数学家陈景润在证明这一猜想中作出了重大贡献，这个猜想是（）", "options": ["莫德尔猜想", "哥德巴赫猜想", "康威-诺顿猜想", "四色猜想"], "a": 1, "e": "【B】A项错误，莫德尔猜想是:若C的亏格大于1，则C只有有限多个k点(即坐标在k中的点)。该猜想已被法尔廷斯(Falt-ings,G.)于1984年证明；B项正确，在现代数学史上，陈景润的名字与哥德巴赫猜想紧紧联系在一起。被誉为光辉成就的“陈氏定理”将哥德巴赫猜想的证明推进了一大步，使中国在这一领域的研究上居世界领先地位；Moonshine）的论文里，约翰康威（JohnConway，现为普林斯顿大学数学教授）和西蒙诺顿（SimonD项错误，四色猜想的证明于1976年由美国数学家阿佩尔(KennethAppel)与哈肯借助计算机完成，遂称四色定理。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-19", "q": "下列说法错误的是：", "options": ["在太阳系中，太阳是中心天体，其他天体都在太阳的引力下，绕太阳公转。其它的主要成员是水星、金星、地球、火", "光年是天文学中常用的距离单位，光在真空中一年所走的距离叫光年", "生物具有遗传和变异，既能保持物种相对稳定，又能促使生物不断演化", "染色体是细胞核中载有遗传信息（基因）的物质，由核酸和蛋白质组成。哺乳动物雄性个体细胞的性染色体对为XX，"], "a": 3, "e": "【D】D项错误，哺乳动物雄性个体细胞的性染色体对为XY，雌性则为XX。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-20", "q": "关于计算机，下列说法不正确的是：", "options": ["平板电脑属于小型计算机", "计算机断电后内存中的信息会丢失", "计算机的性能并非完全依靠于CPU", "机器语言可以被计算机硬件直接执行"], "a": 0, "e": "【A】平板电脑、个人PC等属于微型计算机的范畴，而小型计算机是相对于大型计算机而言的一种概念，仍比微型计算机的硬件规模、计算能力等高出很多。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-21", "q": "关于科学家的成就，下列说法正确的是：", "options": ["阿基米德发现了杠杆原理", "道尔顿提出了分子说", "高斯创立了解析几何", "爱迪生发明了炸药"], "a": 0, "e": "【A】A项正确：杠杆原理亦称“杠杆平衡条件”，由阿基米德发现。要使杠杆平衡，作用在杠杆上的两个力矩（力与力臂的乘积）大小必须相等，即：。B项错误：阿伏加德罗提出了分子学说。C项错误：解析几何是借助笛卡儿坐标系由笛卡儿、费马等数学家创立并发展的。D项错误：炸药由诺贝尔发明。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-22", "q": "现代火炮按弹道特征可分为榴弹炮、迫击炮和加农炮，其中迫击炮弹道的特征是：", "options": ["初速小，弹道比较弯曲", "初速小，弹道比较平直", "初速大，弹道比较平直", "初速大，弹道比较弯曲"], "a": 0, "e": "【A】迫击炮弹道弯曲，炮身短，初速小，射角为45°—85°，变装药号数较多，适于对遮蔽物后的目标射击。迫击炮问世以来，被广泛运用于战争，尤其是山地战和堑壕战，配合步兵小单位（连、排、班）作战，为步兵之制式火力支援武器。A项符合。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-23", "q": "下列有关国防基础知识的表述中，不正确的是：", "options": ["我国的第一任国防部长是彭德怀", "我国的领海宽度为12 海里", "我国的现役部队由海军、陆军、空军三个军种组成", "我国义务兵服现役的期限为2 年"], "a": 2, "e": "【C】C项错误，中国人民解放军现役部队由陆军、海军、空军、火箭军、战略支援部队、联勤保障部队组织而成。它们是中华人民共和国武装力量的主体。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-24", "q": "物联网中物体通过信息传感设备，与互联网相连接，进行信息交换和通信。下列不具备信息传感功能的设备是：", "options": ["激光扫描器", "红外感应器", "普通数码相机", "射频标签"], "a": 2, "e": "【C】A选项，激光扫描器通过扫描二维码或者条形码，可以读取相关信息，具备信息传感功能；B选项，红外感应器可以发射红外信号，控制电器或者其他设备的开关，因此具备信息传感功能；C选项，普通数码相机拍摄的图像不能直接导出，需要将存储卡取出用电脑读取信息，不能直接传导信息，因此不具备信息传感功能；D选项，射频标签又叫电子标签，通过近距离感应可以读取其中的信息，如小区门禁卡、地铁卡等，因此具备信息传感功能。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-25", "q": "防火墙是一项确保网络信息安全的设备，下列关于防火墙的描述错误的是：", "options": ["可保护内部网免受非法用户的侵入", "能有效地记录互联网上的活动", "是一个安全策略的检查站，所有进出信息都必须经过防火墙", "是一种能有效查杀病毒，保护电脑安全的杀毒软件"], "a": 3, "e": "【D】防火墙指的是一个由软件和硬件设备组合而成，将内部网和公众访问网分开的保护屏障，是一种隔离技术，最大限度地阻止网络中的黑客来访问你的网络。所有进出信息都必须通过防火墙，使可疑的网站被拒绝于门外，保护内部网不受非法用户的侵入，但不能查杀病毒。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-26", "q": "下列说法错误的一项是：", "options": ["绿色食品是指安全无污染且富有营养的蔬菜水果", "人们空腹喝牛奶不利于营养成分的吸收", "香蕉是热带水果，不适宜放在冰箱中冷藏", "摄入过多食品添加剂会危害人体健康"], "a": 0, "e": "【A】A选项，绿色食品不仅包括蔬菜水果，还包括畜禽及水产品等，A项错误；B选项，空腹喝牛奶，蛋白质会在缺少糖和脂肪的情况下被迫转为能量消耗，而不能起到它更大的营养作用，B项正确；C选项，香蕉是热带水果，最适宜储存温度是11-13摄氏度，不宜放在冰箱中冷藏，C项正确；D选项，食品添加剂，特别是化学合成的食品添加剂大都有一定的毒性，所以使用时要严格控制使用量，摄入过多会危害人体健康，D项正确。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-27", "q": "下列说法正确的一项是：", "options": ["大气中二氧化碳浓度的增加导致全球变暖，也不利于植物的光合作用", "树桩上年轮较稀疏的一边是南方，年轮较紧的一边是北方", "在寒冷的冬季用手直接触摸金属门把手会感觉很冷，这是因为门把手将寒气传递给了手掌", "日环食的出现是由于月球在太阳和地球之间时距地球较近，不能完全遮住太阳形成的"], "a": 1, "e": "【B】A选项，大气中二氧化碳等气体能对地球反射出来的长波辐射具有高度的吸收性，能强烈吸收地面辐射中的红外线，也就是常说的“温室效应”，二氧化碳浓度增加会导致全球变暖；同时，植物的光合作用是将二氧化碳转化为有机物并释放出氧气，二氧化碳浓度的增加在一定程度上会促进光合作用。A项错误；B选项，在北半球（从应试角度看题干默认的是北半球）在树木生长过程中，树干朝南一面受阳光照射较多，形成层原始细胞分裂也较迅速，径向生长加快，结果茎干南面的年轮也较宽（稀疏）。而在茎干背阴朝北的一面，年轮则明显狭窄（紧密）。B项正确；C选项，在寒冷的冬季，用手触摸门把手会感觉冷是因为手与门把的温差较大，C项错误；D选项，日环食的出现是因为月球在太阳和地球之间，但是距离地球较远，不能完全遮住太阳而形成的，D项错误。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-28", "q": "下列关于电池的说法错误的是：", "options": ["干电池利用液态电解液产生电流", "自行放电是蓄电池不可避免的渐生故障", "锂电池不会产生铅、汞等有害重金属物质", "太阳能电池产生的电是直流电​"], "a": 0, "e": "【A】本题考查科技常识。A项错误，干电池是一种以糊状电解液来产生直流电的化学电池，湿电池为使用液态电解液的化学电池。B项正确，蓄电池的自行放电和极板逐渐硫化是铅酸蓄电池不可避免的“渐生故障”，会使蓄电池的技术状态变差，工作能力逐渐削弱以至报废，因此需定期对蓄电池的技术状态进行检测。C项正确，锂金属电池一般是使用二氧化锰为正极材料、金属锂或其合金金属为负极材料、使用非水电解质溶液的电池。锂离子电池一般是使用锂合金金属氧化物为正极材料、石墨为负极材料、使用非水电解质的电池。在上述两种锂电池的工作过程中，均不会产生铅、汞等有害重金属物质。D项正确，太阳能电池是通过光电效应或者光化学效应直接把光能转化成电能的装置，产生的电是直流电。若需提供电力给家电用品或各式电器则需加装直/交流转换器，换成交流电，才能供电至家庭用电或工业用电。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-29", "q": "钢是主要由铁元素和碳元素组成的①合金，钢的含碳量②大于生铁。在钢中加入其它元素能够继续改善钢的性质，例如，加入锰元素主要增加钢的③强度。在钢的锻造中，淬火可以实现其④快速冷却。这段文字中画线部分错误的是：", "options": ["①", "②", "③", "④"], "a": 1, "e": "【B】本题考查科技常识。A项正确，钢是用量最大、用途最广的合金，以铁为主要元素、以铁为主要成份，含碳量一般在以下，并含有少量的锰、硅、硫、磷等元素。B项错误，生铁是铁碳合金，一般把含碳量在的铁碳合金叫做生铁。而钢的含碳量一般在以下，所以钢的含碳量小于生铁。C项正确，在钢铁生产上加入锰元素（锰铁合金的形式）可作为去硫剂和去氧剂，提高钢铁的纯度，进而提高钢铁的强度和硬度。D项正确，淬火是将金属工件加热到某一适当温度并保持一段时间，随即浸入淬冷介质（冷却剂）中快速冷却的金属热处理工艺。因此，在钢的锻造中，淬火可以让钢快速冷却。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-30", "q": "下列矿物与其用途对应错误的是：", "options": ["燧石—取火", "石灰岩—生产水泥", "石棉—促进燃烧", "石英—制作半导体"], "a": 2, "e": "【C】C项错误：石棉指具有高抗张强度、高挠性、耐化学和热侵蚀、电绝缘和具有可纺性的硅酸盐类矿物产品。石棉是重要的防火、绝缘和保温材料。因此石棉不仅不会促进燃烧，反而会遏制燃烧，当选；A项正确：燧石俗称“火石”，是常见的硅质岩石。燧石和铁器击打会产生火花，因此在古代常被用作取火工具，排除；B项正确：石灰岩简称灰岩，是以方解石为主要成分的碳酸盐岩。石灰岩是生产水泥的主要材料，排除；D项正确：石英主要成分为二氧化硅，是制造半导体单晶硅的原料，因此石英可以用于制作半导体，排除。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-31", "q": "关于农业生产中使用的草木灰，下列说法错误的是：", "options": ["在种有大白菜的地里撒上草木灰可防病虫害", "花卉移栽时，可以用草木灰做底料增加养分", "育苗时，草木灰和氮肥同时施用效果更好", "往鱼塘撒草木灰能够降低鱼类的发病率"], "a": 2, "e": "【C】A项正确，草木灰是一种碱性肥料，富含钾，并含有大量的磷、钙、镁、硫及各种微量元素，不仅是一种很好的农家肥料，而且是一种治病虫的良药。施用草木灰，可防止锈病、白粉病等病虫害的发生，排除。B项正确，草木灰在花卉上一般使用撒、埋、叶面施肥或溶水进行浇施，可以促进花卉生长，排除。C项错误，草木灰是植物（草本和木本植物）燃烧后的残余物，呈碱性，含有植物所需的大部分矿质元素，主要成分是碳酸钾（），是很好的钾肥补充剂。但草木灰中的碳酸钾和氮肥会发生化学反应形成氨气，造成氮损失，因此不能混合使用，当选。D项正确，鱼类正常生长所需水体环境为PH值为7.5~8.5的碱性环境。草木灰呈碱性，可以调节鱼塘酸碱度。另一方面，草木灰具有杀菌作用，能有效杀灭鱼体上的各种病原体，常施草木灰既可对鱼塘水体进行消毒，又能净化水质，排除。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-32", "q": "氢气是重要的工业燃料，下列关于氢气的说法正确的是：", "options": ["氢气在氧气中燃烧发出明亮的红色火焰", "电解水生成氢气的过程是一个吸热过程", "人工降雨过程中通常使用氢气作催化剂", "氢气在自然界中含量很少，故为稀有气体"], "a": 1, "e": "【B】B项正确：水被直流电电解生成氢气和氧气的过程被称为电解水。电解水生成氢气的过程是吸热的，但在实验过程中，水温会升高，其原因在于水充当了导体，电流做功发热。当选；A项错误：氢气在氧气中燃烧产生淡蓝色火焰，排除；C项错误：人工降雨过程中使用的催化剂通常分为三类，第一类是可以大量产生凝结核或凝华核的碘化银等成核剂；第二类是可以使云中的水分形成大量冰晶的干冰等制冷剂；第三类是可以吸附云中水分变成较大水滴的盐粒等吸湿剂。氢气并不用作人工降雨的催化剂，排除；D项错误：稀有气体不是指自然界中含量很少的气体，而是指元素周期表上的18族元素。在常温常压下，它们是无色无味的单原子气体，很难进行化学反应。天然存在的稀有气体有六种，即氦（He）、氖（Ne）、氩（Ar）、氪（Kr）、氙（Xe）和具放射性的氡（Rn）。氢气不属于稀有气体，排除。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-33", "q": "图中a 表示地壳中含量最多的三种元素氧、硅、铝，b 表示人体内含量最多的三种元素。关于阴影部分代表的元素，下列说法错误的是：", "options": ["在冶金工业中有广泛用途", "其单质可以燃烧", "是碱类物质必不可少的元素", "是大气中的一种重要元素"], "a": 1, "e": "【B】由人体中元素含量较多的前五位元素分别是氧、碳、氢、氮、钙可知，含量占前三位的元素依次是氧、碳、氢。所以阴影部分是氧。A项氧不但是动物维持生命过程和燃烧过程中不可缺少的物质，而且在现代工业生产中也十分重要，说法正确。B项氧气在常温常压下，为无色、无味的气体，支持燃烧，但单质不可燃烧，说法错误。C项碱是指电离时生成的阴离子全部是氢氧根离子的化合物，碱溶液中的阴离子都是氢氧根离子。所以碱的组成中一定含有氢、氧两种元素，说法正确。D项地球上的大气有氮、氧、氩等气体成分，所以氧是大气中重要的元素之一，说法正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-34", "q": "对下列诗词蕴含的化学原理解释错误的是：", "options": ["蜡炬成灰泪始干——烃类的不完全燃烧", "爆竹声中一岁除——爆炸产生二氧化硫", "日照香炉生紫烟——多环芳香烃的升华", "洪炉照破夜沉沉——燃烧释放二氧化碳"], "a": 2, "e": "【C】“日照香炉生紫烟”意思是庐山的香炉峰，在日光的照耀下，水汽蒸腾，呈现出紫色的烟霞，而多环芳香烃是煤、油类、煤气、木头、垃圾或其他有机物在不完全燃烧时形成的一类化学物质。两者之间没有联系，C项错误。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-35", "q": "煤燃烧后的产物主要是，也含有一定量的，还可能含有。某市环保部门监测发现，该市郊区的火力发电厂（以煤为燃料）周围的树木枯萎情况比上一年严重。造成树木枯萎的最主要原因可能是（）。", "options": ["", "", "排放", "排放"], "a": 2, "e": "【C】本题考查科技常识。A项错误，一氧化碳（），一种碳氧化合物，标准状况下为无色、无臭、无刺激性的气体。一氧化碳超标排放到大气中，在血液中极易与血红蛋白结合，形成碳氧血红蛋白，使血红蛋白丧失携氧的能力和作用，造成组织窒息，严重时死亡。B项错误，二氧化碳（），常温常压下是一种无色无味或无色无嗅而略有酸味的气体，也是一种常见的温室气体。二氧化碳排放过多容易引起温室效应，加剧气候变暖。C项正确，D项错误，二氧化硫排放到大气中，经过“云内成雨过程”，即水汽凝结在硫酸根凝结核上，发生液相氧化反应，形成硫酸雨滴；又经过“云下冲刷过程”，即含酸雨滴在下降过程中不断合并吸附、冲刷其他含酸雨滴和含酸气体，形成较大雨滴，最后降落在地面上，形成了酸雨。酸雨可导致土壤酸化、植被枯萎等危害。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-36", "q": "下列关于洗涤用品的说法正确的是：", "options": ["使用加酶洗衣粉，水温越高效果越好", "使用酸性的洗发液可以有效去除头发上的油脂", "推广使用无磷洗衣粉是为了减少对皮肤和衣物的伤害", "洗洁精借助表面活性剂，以水为介质对污物进行溶解"], "a": 3, "e": "【D】本题考查科技常识。A项错误，加酶洗衣粉的pH值一般不大于10，在水温时，能充分发挥洗涤作用；温度过高会使酶变性，从而失去活性。B项错误，油脂可以溶于碱性溶液中，人的头皮会分泌一些油脂，所以用碱性洗发水能够有效去除头发上的油脂，用酸性不易除掉油污。C项错误，推广无磷洗衣粉的使用，主要目的是防止水体污染。含磷洗衣粉的应用容易造成水体富营养化，是因为水中植物吸收了磷元素而大量繁殖，从而使水中鱼类缺氧死亡，并使得水质变坏。D项正确，在洗涤过程中加入洗洁精(主要是表面活性剂)，可以减弱污垢与固体表面的黏附作用，再施以外力搅动，借助于水的冲力将污垢与固体表面分离而悬浮于水中，最后达到将污垢冲洗干净的目的。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-37", "q": "明代名臣于谦曾写下《石灰吟》：“千锤万凿出深山，烈火焚烧若等闲。粉骨碎身浑不怕，要留清白在人间”。诗中“烈火焚烧若等闲”描写的是：", "options": ["生石灰变成熟石灰的过程", "利用石灰石生产生石灰的过程", "石灰浆固化的过程", "熟石灰改良酸性土壤的过程"], "a": 1, "e": "【B】本题考查科技常识。首句“千锤万凿出深山”描写的是石灰石的开采，石灰石的主要成分为碳酸钙，碳酸钙经过高温煅烧，会生成氧化钙和二氧化碳，反应式：。生成的氧化钙就是我们通常所讲的生石灰。A项错误，生石灰的主要成分为氧化钙，熟石灰的主要成分为氢氧化钙。生石灰与水反应变成熟石灰，反应式：。该反应会放出大量的热，不需要烈火焚烧。B项正确，“烈火焚烧若等闲”描写的就是石灰石（碳酸钙）经过烈火焚烧（高温煅烧）生成生石灰（氧化钙）和二氧化碳这个反应过程，即利用石灰石生产生石灰的过程。C项错误，石灰浆的固化是在干燥、结晶、碳酸化等几个作用下共同进行的，不需要烈火焚烧。D项错误，熟石灰呈弱碱性，可以与土壤中的酸性物质发生中和反应，从而改良酸性土壤，不需要进行烈火焚烧。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-38", "q": "宋朝科学家沈括的《梦溪笔谈》中描述了一种化石燃料，“颇似淳漆，燃之如麻，但烟甚浓，所沾帷幕皆黑”，并预言“此物必大行于世”。关于该化石燃料，下列说法正确的是：", "options": ["是全球使用量最高的化石燃料", "是由有机物和无机物组成的混合物", "其主要成分是结构最简单的有机物", "在我国化石能源利用中占主导地位"], "a": 0, "e": "【A】本题考查科技常识。“颇似淳漆，然之如麻（然通燃），但烟甚浓，所沾帷幕皆黑”描述的化石燃料是石油。A项正确，石油是一种全球使用量最高的化石燃料，耗尽的时间比其他化石燃料长。B项错误，石油主要是由碳、氢元素组成的多种有机物的混合物。C项错误，结构最简单的有机物是甲烷。天然气的主要成分是甲烷。D项错误，煤炭在我国化石能源利用中占主导地位。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-39", "q": "下列关于钢的表述错误的是：", "options": ["碳是其最重要的硬化元素，所有钢材中都含有碳元素", "钢按照成分的不同可分为低碳钢、中碳钢和高碳钢", "钢是含碳量在一定区间的铁碳合金", "生铁经过高温煅烧可成为钢"], "a": 1, "e": "【B】本题考查科技常识中的化学常识，主要分析钢材的成分，与碳元素的关系及钢材的生成等。AC项正确、B项错误，钢是含碳量在的铁合金。钢按照成分一般分为碳素钢与合金钢。碳素钢是普通钢，主要含铁，还有碳以及很少量的硅、锰、硫、磷等杂质。合金钢又叫特种钢。除铁、碳以外，还含有一种或多种一定量的合金元素的钢。合金元素有硅、锰、钼、镍、铬、钒、钛、铌、硼，钨和稀土元素等。故无论何种钢材都有碳；其中碳素钢根据含碳量不同，碳素钢可分为高碳钢、中碳钢、低碳钢。高碳钢硬度大，可用于制造模具、刀具等；低碳钢和中碳钢硬度适中，韧性较好，用于制造机器和用具。故B表述错误。D项表述不严谨，生铁炼钢需三步：一是高温煅烧，为降低含碳量、去除有害杂质；二是脱氧，加入脱氧剂(硅铁、锰铁或铝)，使钢水中少量的氧化铁还原成铁单质；三是去除硫和磷。加入氧化钙，与磷、硫元素反应，生成炉渣排出。仅仅是高温煅烧得不到钢，但是得到钢必须经过高温煅烧。因此D表述不十分严谨，而B明显错误，单选择优选B。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-40", "q": "若庄稼出现成片歪斜、匍倒的倒伏现象，据此，最有可能需要施用的肥料是：", "options": ["磷酸钙", "氢氧化钾", "硝酸钾", "尿素"], "a": 2, "e": "【C】本题考查科技常识。农业生产中植物需要施肥，常用的肥料主要是氮肥、磷肥、钾肥，这些肥料主要是含氮、磷、钾的无机盐。A项错误，磷酸钙属于磷肥，可以促使植物根系发达，增强抗寒抗旱能力，后期还可能促使作物子粒饱满，提早成熟。缺乏磷肥会使农作物生长迟缓、产量降低。B项错误，氢氧化钾属于强碱，腐蚀性极强，不可用作植物肥料。C项正确，硝酸钾属于氮和钾的复合肥，其中钾可以促使植物茎秆健壮，具有抗倒伏作用。因此，庄稼出现歪斜、倒伏时可施用硝酸钾。D项错误，尿素属于氮肥，氮肥可以促进植物枝繁叶茂、叶色浓绿、果实硕大。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-41", "q": "高粱、玉米等植物的种子经发酵、蒸馏就可以得到一种“绿色能源”物质。这种物质是", "options": ["氢气", "甲烷", "酒精", "乙炔"], "a": 2, "e": "【C】本题考查科技常识。A项错误，氢气是一种极易燃烧，无色透明、无臭无味的气体，液态氢可用做火箭或导弹的高能燃料。氢气是气体，且难溶于水，不能通过蒸馏的形式得到，实验室中可采用电解水、氨分解等方式制备氢气。B项错误，甲烷是结构最简单的碳氢化合物，其主要是作为燃料，广泛应用于民用和工业中。由于甲烷是气体，不能通过蒸馏的形式得到，实验室中主要是用无水的醋酸钠和氢氧化钠加热在氧化钙（催化剂）的条件下发生脱羧反应生成碳酸钠和甲烷。C项正确，高粱、玉米等植物的种子主要成分是淀粉，淀粉属于多糖，其经发酵、蒸馏后可以得到酒精。酒精燃烧生成二氧化碳和水，对环境无影响，所以被称为“绿色能源”。D项错误，乙炔是最简单的炔烃，主要用于焊接金属、合成高分子化合物。乙炔不能通过植物发酵等形式得到，主要制备方法有电石法、天然气制乙炔法。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-42", "q": "开瓶放置的葡萄酒，数天后会变酸。这是由于发生了", "options": ["水解反应", "氧化反应", "酯化反应", "加成反应"], "a": 1, "e": "【B】本题考查科技常识。A项错误，水解反应包括盐水解和有机化合物水解两类，通常指水中的氢和羟基分别加到化合物的某一部分，因而得到两种或两种以上新化合物的反应过程。葡萄酒变酸未涉及到水解反应。B项正确，有机物的氧化反应是指失电子或电子偏离化合价升高的反应过程。葡萄酒开瓶后很容易被空气氧化，酒精（乙醇）在氧化作用下先生成乙醛，乙醛后被氧化为乙酸，使酒变成醋，因此会有酸味。C项错误，酯化反应一般指醇和酸（无机酸或有机酸）作用生成酯（无机酸酯或有机酸酯）和水的反应。葡萄酒变酸未生成酯，不涉及酯化反应。D项错误，加成反应是一种有机化学反应，指两个或多个分子互相作用，生成一个加成产物，其发生在有双键或叁键(不饱和键)的物质中。葡萄酒变酸未涉及到加成反应。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-43", "q": "长春市轨道交通2 号线已投入运营，在工程建设中用量最大的硅酸盐材料是", "options": ["石灰", "陶瓷", "水泥", "大理石"], "a": 2, "e": "【C】A项错误，石灰以氧化钙为主要成分的气硬性无机胶凝材料，不含硅酸盐。B项错误，陶瓷是陶器和瓷器的统称，其中用黏土或陶土为原料烧制的器皿叫陶器，用瓷土、瓷石等为原料烧制的器皿叫瓷器。轨道交通的工程建设中一般不使用陶瓷。C项正确，水泥是一种能把砂、石等材料牢固地胶结在一起形成水硬性无机胶凝材料。水泥种类很多，最常用的是硅酸盐水泥，广泛应用于各类建筑工程中。因此轨道交通工程建设中用量最大的硅酸盐材料是水泥。D项错误，大理石主要成分为碳酸钙，是一种装饰性很强的装饰材料，常用于大型公共建筑的门厅、大厅等比较重要的场所。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-44", "q": "下列关于粉尘爆炸的说法错误的是：", "options": ["颗粒越小越易燃烧，爆炸也越剧烈", "越易氧化的物质，其粉尘越易爆炸", "越易带电的物质，其粉尘越易爆炸", "含卤素和钾、钠的粉尘，爆炸趋势增强"], "a": 3, "e": "【D】本题考查科技常识。呈细粉状的固体物质被称为粉尘，能燃烧和爆炸的粉尘叫做可燃粉尘。工厂内一些金属粉尘，如镁粉、铝粉，生活中常见的淀粉、木粉等都是可燃粉尘。粉尘在爆炸极限范围内，遇到热源(明火或高温)，火焰瞬间传播于整个混合粉尘空间，化学反应速度极快，同时释放大量的热，形成高温高压。由于这一过程中不断有升高的压力会产生冲击波，因此，爆炸会造成很大的破坏力。A项正确，粉尘的表面能够吸附空气中的氧，颗粒越细小，粉尘总的表面积就越大，从而表面吸附的氧就越多，越容易发生爆炸。B、C项正确，粉尘爆炸的难易程度与粉尘的物理化学性质和环境条件等有关。一般认为氧化速度快的物质容易爆炸，如镁粉、铝粉等。容易带电的粉尘也很容易引起爆炸，如合成树脂粉末、纤维类粉尘等。D项错误，根据实践分析，一般含有卤素和钾、钠的粉尘，爆炸趋势减弱。本题为选非题，故正确答案选择D。", "tag": "科技常识"},
{"id": "tech-45", "q": "下列气体既会造成酸雨，又可用作防腐剂的是：", "options": ["二氧化碳", "二氧化氮", "二氧化硫", "氮气"], "a": 2, "e": "【C】本题考查科技常识。酸雨通常指pH值小于5.6的酸性降水。酸雨中含有多种无机酸和有机酸，绝大部分是硫酸和硝酸，由人为排放的大气污染物二氧化硫和氮氧化物转化而成。A项错误，二氧化碳溶于水后虽然会使雨水呈弱酸性，但不会导致酸雨。B项错误，二氧化氮会与大气中水反应生成硝酸，形成硝酸型酸雨；二氧化氮有剧毒，不可以作防腐剂。C项正确，二氧化硫与大气中的水反应生成亚硫酸，亚硫酸又与大气中的氧气反应，生成硫酸，形成硫酸型酸雨；二氧化硫有还原性，易被氧化，因此常用作葡萄酒的防腐剂。D项错误，氮气化学性质不活泼，常温下很难跟其他物质发生反应,所以常被用作薯片等食品的防腐剂；氮气难溶于水，不会造成酸雨。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-46", "q": "下列说法错误的是：", "options": ["雷雨可使土壤的氮肥增加", "18K 黄金制品的含金量为70", "聚四氟乙烯可用于制作不粘锅的涂层", "在金属表面喷漆可以防止金属被氧化腐蚀"], "a": 1, "e": "【B】本题考查科技常识。A项正确，含氮元素的化合物能提供作物生长所需的氮元素,而被称为氮肥。雷雨时雷电作用下，氮气与氢气化合成氨气，氨气、二氧化碳与雨水相互作用可形成碳铵随雨水落入土壤，碳铵能提供作物生成所需要的氮元素，属于氮肥。B项错误，K金是指黄金和其它金属混合在一起的合金。根据在首饰中的黄金含量可分为不同的K金，其中24K是指纯金，18K黄金制品的含黄金量就是18/24=75，因此选项中的70表述错误。C项正确，聚四氟乙烯俗称“塑料王”，是由四氟乙烯经聚合而成的高分子化合物，具有优良的化学稳定性、耐腐蚀性、密封性、高润滑不粘性，可用于制作不粘锅的涂层。D项正确，金属被氧化腐蚀是指各类材料在环境作用下发生损坏、性能下降或状态的劣化。良好的喷漆涂装保护层能够成为抑制腐蚀介质侵入的屏障，使得金属保持连续完整，因此在金属表面喷漆是一种很重要的金属防腐蚀手段。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-47", "q": "下列词语隐含化学变化的是", "options": ["春风化雨", "腐草为萤", "积沙成塔", "滴水成冰"], "a": 1, "e": "【B】本题考查科技常识。物理变化和化学变化的根本区别在于是否有新物质生成，如果有新物质生成，则属于化学变化；反之，则是物理变化。A项错误，春风化雨指适宜于草木生长的风雨。春风吹拂，化云为雨，这过程主要是空气中水汽凝结成小水滴，没有新物质生成，属于物理变化。B项正确，古代有腐草化为萤火虫的说法。萤火虫在夏季多就水草产卵，幼虫入土化蛹，次年春变成虫，古人误以为萤火虫是由腐草本身变化而成。草木腐烂（腐草）会被分解生成养料等其他物质，属于化学变化。C项错误，积沙成塔意思是把细沙积聚成宝塔，比喻聚少成多，仅指物质量的积累，不涉及化学变化。D项错误，滴水成冰是指天气十分寒冷，滴下的水马上就冻成了冰，没有新物质生成，属于物理变化。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-48", "q": "下列关于酒精的说法不正确的是：", "options": ["小麦的秸秆可以制取酒精", "酒精失火时应立刻用水扑灭", "酒精是很好的有机溶剂，可用于去除油污", "酒精消毒无法达到杀死细菌芽孢的灭菌标准"], "a": 1, "e": "【B】本题考查科技常识。A项正确，小麦等农作物秸秆主要是由木质素粘合包裹着纤维素、半纤维素组成的结构化的整体。小麦的秸秆制取酒精的原理就是将聚合体纤维素、半纤维素与结构复杂的木质素分离，然后将其分解成可发酵性糖,再将混合的戊糖和己糖转化为酒精。B项错误，酒精在水中可以以任意比例互溶，形成不同浓度的酒精溶液，然而酒精溶液仍然可以燃烧，且用水灭火还会使酒精流动甚至飞溅，扩大着火范围。酒精失火宜用覆盖法或干粉灭火器灭火。C项正确，当溶质在溶解时，极性分子易溶于极性溶剂，非极性分子易溶于非极性溶剂，这便是相似相溶原理。油、酒精等有机溶剂多是非极性的，所以可以用酒精溶解油污达到去污的目的。D项正确，酒精是一种常用的消毒剂，但它只具备中效消毒能力，研究表明，酒精不能杀死细菌芽孢，也不能杀死某些病毒（如：乙肝病毒）。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-49", "q": "药店出售的某复合维生素成分表中标识：“每片含铁60mg”，其中“铁”指的是", "options": ["原子", "离子", "元素", "单质"], "a": 2, "e": "【C】本题考查科技常识。铁元素是人体所需的微量元素之一，在人体中参与血蛋白、细胞色素及各种酶的合成等。根据《保健食品管理办法》第二十一条规定：“保健食品标签和说明书必须符合国家有关标准和要求，并标明下列内容：（四）功效成分的名称及含量。因在现有技术条件下，不能明确功效成分的，则须标明与保健功能有关的原料名称；”题干中所标示的就是功效成分铁元素的含量。A项错误，原子是化学变化中的最小微粒。题干中所指的是铁元素而不是铁原子。B项错误，离子是原子或原子团由于得失电子而形成的带电微粒。离子存在于离子化合物和电解质溶液中，题干中所指是铁元素而不是铁离子。C项正确，元素是化学元素的简称，是具有相同核电荷数的一类原子的总称。食品、药品中铁、钙、锌等微量元素不是以单质、分子、原子等形式存在，而是以无机盐、有机盐两种化合物形式存在的。故食品、保健品、药品标识中的“含铁（钙、锌等）量”是指所含的元素量。故题干标示的含铁60mg，指的是含有铁元素60mg。D项错误，单质是由同种元素组成的纯净物。题干中所指是铁元素而不是铁单质。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-50", "q": "关于物质组成及其变化，下列说法正确的是：", "options": ["汽油挥发和形成水垢均是化学变化", "地壳中含量最多的非金属元素是氮", "构成物质的三种微粒是分子、原子和电子", "组成化合物种类最多的元素是碳"], "a": 3, "e": "【D】本题考查科技常识。A项错误，物理变化指物质的状态虽然发生了变化，但物质本身的组成成分却没有改变。化学变化是有新物质形成的变化过程。汽油挥发只是汽油由液态变为气态，并没有新物质生成，因此属于物理变化。水垢是指含有钙镁盐类等矿物质的水蒸发后，溶于水的钙离子和镁离子形成了碳酸钙和氢氧化镁两种沉淀，因此属于化学变化；B项错误，地壳是由沙、黏土、岩石等组成的，地壳中所含元素的含量从高到低的排序是氧、硅、铝、铁、钙，因此地壳中含量最多的金属元素是铝，非金属元素是氧，而不是氮；C项错误，物质是无限可分的，其中构成物质的三种基本微粒是分子、原子和离子，而非电子；D项正确，凡除了极少数含碳化合物为无机物以外，其余含碳化合物称为有机物，自然界中物质多数是有机物，因此，组成化合物种类最多的元素是碳。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-51", "q": "牵牛花早晨为蓝色，下午会变为红色，这主要是因为牵牛花逐渐吸收了大量的：", "options": ["酸性气体", "惰性气体", "中性气体", "碱性气体"], "a": 0, "e": "【A】本题考查化学常识。牵牛花内有特殊的色素，随着酸碱度变化而变化，吸收二氧化碳越多，越偏酸性。吸收二氧化碳是一个随时间持续的过程，白天光合作用强，因此随着吸收二氧化碳量的增加，逐渐变为红色；夜晚之后，光合作用停止，吸收二氧化碳减少，逐渐变回蓝色。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-52", "q": "下列关于铁矿的说法正确的是：", "options": ["赤铁矿与铁锈的主要成分相同", "磁铁矿一般呈黄褐色", "“千锤百炼”是指铁矿石的开采过程", "我国的铁矿开采始于西汉时期"], "a": 0, "e": "【A】本题考查化学常识，主要涉及铁矿石的相关内容。A项正确，赤铁矿的主要化学成分为三氧化二铁，颜色呈红褐、钢灰至铁黑等色，是自然界分布极广的铁矿物，是重要的炼铁原料，也可用作红色颜料。铁锈，又名铁衣，是铁置于空气中氧化后生成的红褐色锈衣，主要化学成分也是三氧化二铁。故该选项正确。B项错误，磁铁矿，是指氧化物类矿物磁铁矿的矿石，多为粒块状集合体，主要成分为，多呈现铁黑色，具强磁性。C项错误，“锤”一般用来矿物质的开采，除此以外“凿”也会用来形容开采矿石，但“炼”多用于铁矿石的冶炼过程，C项说法片面。D项错误，中国是世界上利用铁最早的国家之一，最早可以上溯到西周晚期，春秋的时候铁制农具出现，战国时期铁制农具的使用范围进一步扩大，因此我国铁矿的开采远远早于西汉时期。故正确答案是A。", "tag": "科技常识"},
{"id": "tech-53", "q": "下列最可能涉及对物质化学性质的描写的是：", "options": ["白蜡的燃点低", "水的比热容高", "橡胶耐磨性佳", "茶叶除脂效果好"], "a": 3, "e": "【D】A项错误，白蜡的燃点低体现的是物质的物理性质，燃点是指可燃物质在空气充足的条件下，达到某一温度时与火源接触即可着火，并在移去火源后继续燃烧的最低温度。B项错误，水的比热容高体现的是物质的物理性质，比热容是热力学中常用的一个物理量，表示物体吸热或散热能力。C项错误，橡胶耐磨性佳体现的是物质的物理性质，耐磨性是指抵抗某种机械作用的能力。D项正确，茶叶除脂效果好体现的是物质的化学性质，茶叶中富含氨基酸及纤维素、脂肪酶等，能对脂肪产生分解作用。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-54", "q": "最近几年，无需火电的即热型快餐备受人们欢迎。这种即热型快餐一般由两层铝箔（锡箔）纸包装构成，内层用于盛放需加热的食物，外层用于盛放加热材料。据此，下列最可能成为这种快餐加热材料的是：", "options": ["浓硫酸和水", "食盐和水", "石灰石和水", "生石灰和水"], "a": 3, "e": "【D】本题考查即热型快餐的加热材料，即分析哪一项的物质能通过化学反应放热。A项，浓硫酸溶于水会有热量放出，但是浓硫酸有强腐蚀性，所以不能作为快餐加热材料，排除。B项，食盐，主要成分是氯化钠，其溶于水没有明显的热量放出，所以不能作为快餐加热材料，排除。C项，石灰石，主要成分是碳酸钙，其不溶于水，所以与水混合不会有明显的热量放出，故不能作为快餐加热材料，排除。D项，生石灰，主要成分是氧化钙，生石灰与水反应生成氢氧化钙，并放出热量，可以作为快餐加热材料，正确。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-55", "q": "许多食物在超过的温度下烘焙煎炸烤时，食物中的碳水化合物和蛋白质在高温烹制过程中，很容易产生丙烯酰胺，这种物质对人类健康有潜在危害。为避免摄入过多丙烯酰胺，以下食物最应减少食用的是（）。", "options": ["热茶", "馒头", "炒白菜", "炸鸡"], "a": 3, "e": "【D】本题考查化学常识。丙烯酰胺本身是一种有毒的化合物，主要是损伤细胞内遗传物质，并具有一定的致癌性，国际癌症机构将其列为2A级致癌物，从而引起食品行业的广泛关注。通过对食品的调查发现，淀粉类食物在经过烘烤、煎炸等高温烹调才会产生丙烯酰胺。根据目前各国提供的数据，富含丙烯酰胺的食品主要有炸薯条、炸薯片、爆玉米花、蛋糕、炸鸡等等。A项错误，茶叶中含有较多的有机酸、茶多酚等碳水化合物及少量蛋白质，但热茶的温度一般不超过，故饮用热茶不会摄入过多丙烯酰胺。B项错误，馒头主要成分是淀粉等糖类，属碳水化合物，但在标准大气压下制蒸馒头时水蒸汽温度为左右，故食用馒头不会摄入过多丙烯酰胺。C项错误，白菜主要成分是碳水化合物和蛋白质，炒白菜时用低温油（一般为-）快炒即可，故食用炒白菜不会摄入过多丙烯酰胺。D项正确，鸡肉中含有大量蛋白质，且炸鸡时要用高温油（-）炸制5分钟左右，易产生丙烯酰胺，食用过多可能造成丙烯酰胺摄入过量，因此应当减少食用。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-56", "q": "某厂发生粉尘爆炸事故，造成人员伤亡和财产的严重损失。下列条件的组合会引起粉尘爆炸的是：①粉尘有可燃性且达到一定浓度②天气持续高温③存在火源和助燃物④空间受限", "options": ["②③", "③④", "①③④", "①②③"], "a": 2, "e": "【C】粉尘爆炸指可燃性粉尘在爆炸极限范围内，遇到热源（明火或高温），发生的火焰瞬间传播于整个混合粉尘空间的化学反应，该化学反应速度极快，同时释放大量的热，具有很强的破坏力。一般粉尘爆炸的必要条件：可燃性粉尘要悬浮在空气中达到一定浓度，存在充足的氧气等助燃物，有火源或剧烈震动摩擦；此外，空间受限也是加剧粉尘爆炸的危险条件，粉尘处于相对封闭的空间，会导致温度和压力增加，从而容易发生爆炸。故①③④的条件组合会引发粉尘爆炸，C项正确。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-57", "q": "关于石油污染，下列说法错误的是：", "options": ["石油污染的主要污染物是各种烃类化合物", "石油污染会致使海洋缺氧", "蒸发作用是海洋油污染自然消失的重要因素", "沉入海底的石油或石油氧化物不再会上浮到海面"], "a": 3, "e": "【D】A项正确：石油污染的主要污染物是各种烃类化合物，主要有烷烃、环烷烃和芳烃等。B项正确：大量石油涌入海洋后会造成海水中严重缺氧,会使海洋中的生物很快窒息死亡。C项不严谨：石油在扩散和漂移过程中，轻组分通过蒸发逸入大气，其速率随分子量、沸点、油膜表面积、厚度和海况而不同。含碳原子数小于12的烃在入海几小时内便大部分蒸发逸走，碳原子数在的烃的蒸发要经过若干星期，碳原子数大于20的烃不易蒸发。但是轻烃在石油成分中占比较小，故蒸发消失的石油只是少部分，大部分还是被微生物、海藻等降解的。故“重要因素”表述不严谨。D项错误：在海流和海浪的作用下，沉入海底的石油或石油氧化产物，还可再上浮到海面，造成二次污染。本题C不严谨，D错误明显。二者虽都不对，但可优选D。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-58", "q": "近年来，粉尘爆炸事件屡见不鲜。下列粉尘中不容易引起爆炸的是：", "options": ["肥皂粉", "水泥粉", "面粉", "奶粉"], "a": 1, "e": "【B】粉尘爆炸，指可燃性粉尘在爆炸极限范围内，遇到热源，瞬间剧烈燃烧，释放巨大压力和热量。具有爆炸性的主要可燃性粉尘有：金属（如镁粉、铝粉）；煤炭；粮食（如小麦粉、淀粉）；饲料（如血粉、鱼粉）；农副产品（如棉花、烟草）；林产品（如纸粉、木粉）；合成材料（如塑料、染料）。A项：错误，肥皂粉主要由油脂混合海藻灰或桦木灰等制成，易燃，易爆；B项：正确，水泥粉主要成分是硅酸盐，不具有可燃性，不易爆；C项：错误，面粉是粮食类易爆粉尘；D项：错误，奶粉是粮食类易爆粉尘。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-59", "q": "近期，中科院的一个研究课题组发现：用高能电子束辐射医疗废弃物，可以直接将其中抗生素残留降解为无机或有机小分子。其应用的主要原理是：电子束辐射在水体中产生的活性自由基具有某种作用能够降解抗生素。活性自由基与抗生素发生了：", "options": ["基因突变", "链式反应", "聚合反应", "氧化还原反应"], "a": 3, "e": "【D】D项正确：高能电子束辐照可以直接将医疗废弃物中抗生素残留降解为无机或有机小分子，其主要机理为电子束辐照在水体中产生的活性自由基与抗生素发生了氧化还原反应；A项错误：基因突变是基因组DNA分子发生的突然的、可遗传的变异现象。题干课题不涉及DNA，故不可能是基因突变；B项错误：链式反应指核物理中，核反应产物之一又引起同类核反应继续发生、并逐代延续进行下去的过程。题干课题不涉及核反应，故不可能是链式反应；C项错误：聚合反应是由单体合成聚合物的反应过程。题干课题涉及的是将抗生素残留降解为小分子，不可能是聚合反应。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-60", "q": "下列关于工业酒精、医用酒精和食用酒精的表述，错误的是：", "options": ["工业酒精不可作燃料", "医用酒精的乙醇含量应为", "食用酒精应以薯类、谷类或废糖蜜等为原料", "医用酒精是植物原料产品，可接触人体使用"], "a": 0, "e": "【A】A项错误：工业酒精即工业上使用的酒精。工业酒精的主要成分是乙醇，属于可燃物，是实验室常用燃料，也可为工业生产提供能源，如作为汽车的燃料或与汽油组成混合燃料。B项正确：浓度不同的医用酒精有不同的用途，用于消毒的医用酒精的乙醇含量应为75%。C项正确：食用酒精又称发酵性蒸馏酒，主要是利用薯类、谷物类、糖类作为原料经过蒸煮、糖化、发酵等处理而得的供食品工业使用的含水酒精。D项正确：医用酒精是植物原料产品，含酒精以外的醚、醛成分比食用酒精多，不能饮用，但可接触人体医用。本题为选非题，故正确答案为A。【注：本题为争议题，B项表述不够严谨。浓度不同的医用酒精有不同的用途，医用酒精的常用浓度有两种，浓度为", "tag": "科技常识"},
{"id": "tech-61", "q": "能源按转换传递过程可分为“一次能源”和“二次能源”，下列属于“二次能源”的一组是：", "options": ["沼气、焦炭、核电", "煤、石油、天然气", "煤、核能、海洋能", "水能、风能、核能"], "a": 0, "e": "【A】“一次能源”是指直接取自自然界没有经过加工转换的各种能量和资源，如原煤、原油、天然气、油页岩、核能、太阳能、水能、风能、波浪能、潮汐能、地热、生物质能和海洋温差能等。“二次能源”指由一次能源经过加工转换以后得到的能源产品，如沼气、焦炭、汽油、柴油、电力、蒸汽、核电等。A项正确：沼气、焦炭、核电均由一次能源加工而得，属于二次能源；B项错误：煤、石油、天然气属于一次能源；C项错误：煤、核能、海洋能属于一次能源；D项错误：水能、风能、核能属于一次能源。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-62", "q": "下列各项中，不属于化学变化的是：", "options": ["焰色反应", "铁锅生锈", "粮食酿酒", "卤水点豆腐"], "a": 0, "e": "【A】A选项错误，焰色反应是指某些金属或它们的化合物在无色火焰中灼烧时使火焰呈现特征的颜色的反应，是物理反应，它并未生成新物质，是物质原子内部电子能级的改变，通俗的说，是原子能中的电子能量的变化。B选项正确，铁锅生锈是铁和空气中的水和氧气发生化学反应，所以B选项是化学变化。C选项正确，粮食中原本没有酒精，是其中的淀粉，经过发酵，也就是无氧呼吸，生成酒精，产生了新的物质，所以C选项表述正确。D项错误，人教版高中化学必修一：卤水点豆腐属于胶体聚沉现象，此现象为物理变化。向胶体（豆浆）中加入电解质溶液（卤水）时，由于加入的阳离子（或阴离子）中和了胶体粒子所带的电荷，使胶体粒子聚集成较大的颗粒，从而形成沉淀从分散剂里析出，这个过程叫做聚沉。豆腐、肉冻、果冻是常见的聚沉凝胶态物质。本题为选非题，故正确答案为A或D。注：此题为真题，正确答案有两个，但真题设置为单选题，学员不必纠结，掌握知识点就可以。", "tag": "科技常识"},
{"id": "tech-63", "q": "下列关于食物的说法不正确的是：", "options": ["储存一段时间的红薯比刚挖出来时更甜，是因为淀粉水解生成了单糖", "未成熟的香蕉与成熟的苹果一起保存，后者释放的乙烯能促进前者成熟", "食品包装上的“胀袋勿食”是因为微生物进行乳酸发酵产气导致食物变质", "生鸡蛋泡在石灰水中，水里的碳酸钙能堵塞鸡蛋表面微孔，延长保存时间"], "a": 2, "e": "【C】A选项正确，红薯在储藏一段时间后淀粉会转化成各种单糖；B选项正确，熟苹果会放出乙烯，乙烯有促进果实成熟的作用，当然也能用于香蕉；C项说法片面，根据食品包装胀袋的外观表象(包装内部的气体明显增多)分析，引发该问题的原因主要分为两大类：一类是外部环境中的大量气体进入包装内部；另一类是包装中的微生物生长繁殖而产生了较多的气体。乳酸发酵绝大多数情况下产生乳酸，不一定产生气体；D选项正确，鸡蛋是有生命的，也能够呼出二氧化碳。石灰水中的氢氧化钙和二氧化碳结合成碳酸钙，封闭了鸡蛋壳上的气孔，防止了细菌的侵入，所以鸡蛋就能够延长保鲜期，所以D选项正确。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-64", "q": "关于溶液与溶解，下列说法不正确的是：", "options": ["酒精与水能够以任意比例互溶", "汽油溶解食用油属于物理变化", "酸碱中和后的溶液不一定呈中性", "加入蔗糖可以增加溶液的导电性"], "a": 3, "e": "【D】相同结构的溶液可以相互溶解。乙醇的官能团是羟基（-OH），水的分子式，其中也含有一个羟基（-OH），所以酒精和水可以任意混合，A选项正确；B项是物理变化，因为相似相溶的原理，油污不能溶解在水里，可是汽油能与它相溶，而且汽油具有挥发性，所以一般衣服上有油污的时候就用汽油洗衣服，B选项正确；酸碱中和反应后的溶液不一定是中性，如果是强酸强碱反应是中性，如果是强酸弱碱反应后呈酸性，如果是弱酸强碱反应呈碱性，C选项正确；蔗糖不是电离子化合物，溶解于水后，不能电离出离子，无法增加溶液的导电性，D选项错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-65", "q": "物质在发生能量转化时通常都存在一系列的物理或化学反应，下列能量转化的过程存在化学反应的是（）。", "options": ["风力发电", "烧煤取暖", "冰雪融化", "酒精挥发"], "a": 1, "e": "【B】物理变化是指没有生成其他物质的变化，例如风力发电，酒精挥发，冰雪融化，灯泡发光等。化学变化是变化时生成其他物质的变化，例如木条燃烧，铁生锈，食物腐烂等，化学变化不但生成其他物质，而且伴随能量变化，常表现为吸热，放热，发光等。A、C、D均属于物理变化。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-66", "q": "现代化工业社会过多燃烧煤炭、石油和天然气等化石资源，使自然界更多（更强）地产生灾害性天气（气候）现象，包括有（）。①雾霾②极光③温室效应④龙卷风⑤酸雨⑥冰雹", "options": ["②③④", "①④⑥", "①④⑤", "①③⑤"], "a": 3, "e": "【D】极光、冰雹、龙卷风都属于自然现象。极光的产生是自然现象，往往出现于星球的高磁纬地区上空，是一种绚丽多彩的发光现象。而地球的极光，来自地球磁层或太阳的高能带电粒子流（太阳风）使高层大气分子或原子激发（或电离）而产生。龙卷风是一种相当猛烈的天气现象，由快速旋转并造成直立中空管状的气流形成。冰雹，水蒸气凝结成冰或雪，就是下雪了，如果温度急剧下降，就会结成较大的冰团，也就是冰雹。雾霾、温室效应和酸雨是由于大气污染，煤炭燃烧后会产生、和等有害气体，其中是温室气体，微小颗粒物也是雾霾的因素之一，石油等石化材料过度使用会污染大气环境，产生致癌物和温室效应，破坏臭氧层等。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-67", "q": "春耕前，农民向田里施用草木灰主要是为了给农作物补充（）元素。", "options": ["钾", "氮", "磷", "碳"], "a": 0, "e": "【A】草木灰的主要成分是碳酸钾()。草木灰肥料因草木灰为植物燃烧后的灰烬，所以凡是植物所含的矿质元素，草木灰中几乎都含有。其中含量最多的是钾元素，一般含钾6—12%，其中90%以上是水溶性，以碳酸盐形式存在；其次是磷，一般含1.5—3%；还含有钙、镁、硅、硫和铁、锰、铜、锌、硼、钼等微量营养元素。A项正确。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-68", "q": "以下适合于建设防火林带的树种是（）。", "options": ["木荷", "松树", "樟树", "杉木"], "a": 0, "e": "【A】通过对可燃物的易燃性分析得出，杉木难燃可燃物占总量的比例明显低于8年生以上木荷，而杉木较易燃和较难燃可燃物占有比例明显高于木荷。木荷着火温度高，含水量大，不易燃烧，是营造生物防火林带的理想树种，故A项当选，D项排除。樟树本身也是不易燃的，但是就其枯叶持水能力而言是易燃的，故排除C项。松树属于有油脂的树木，有油脂的树木都是易燃树种，故排除B项。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-69", "q": "关于液体燃料，下列说法错误的是：", "options": ["煤油易挥发，且挥发后与空气混合，会形成爆炸性的混合气", "生物柴油具有“老化”倾向，宜避光、避免与空气接触保存", "柴油能量密度高，燃油消耗率低，但废气中所含有害成分较多", "汽油具有一定的腐蚀性，在贮运过程中容易出现早期氧化变质"], "a": 3, "e": "【D】A项：煤油是轻质石油产品的一类，由天然石油或人造石油经分馏或裂化而得。纯品为无色透明液体，易挥发、易燃。挥发后与空气混合形成爆炸性的混合气。A项表述正确。B项：生物柴油是生物质能的一种，其在物理性质上与石化柴油接近，但化学组成不同。生物柴油具有“老化”倾向，加热不宜超过80℃，宜避光、避免与空气接触保存。B项表述正确。C项：比起汽油来，柴油含更多的杂质，它燃烧时也更容易产生烟尘，造成空气污染。但柴油不像汽油般会产生有毒气体，因此，比汽油更环保和健康，但相对来讲这种有害气体依然较多。D项：汽油的成分非常复杂，由于汽油在提炼过程中不能完全清除含有硫化物等腐蚀性物质，会在存储、运输、使用过程中对储罐、管线、阀门、汽化器、气缸等设备产生一定腐蚀，但理论上讲如果汽油能提纯到不含任何硫化物等腐蚀性物质的时候就不会有腐蚀作用，且有一定的稳定性，早期不易氧化而变质。C、D两项表述均不是很严谨，但相比之下D项更符合题意。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-70", "q": "下列哪组气体对环境的负面影响最大？", "options": ["一氧化氮、二氧化硫", "二氧化碳、水蒸气", "氢气、稀有气体", "甲烷、氮气"], "a": 0, "e": "【A】A项，一氧化氮是一种无色无味，难溶于水的有毒气体，在空气中易被氧化成二氧化氮，而后者有强烈腐蚀性和毒性。一氧化氮对环境有危害，对水体、土壤和大气可造成污染。二氧化硫是最常见、最简单的硫氧化物，是大气主要污染物之一。在大气中，二氧化硫会氧化而形成硫酸雾或硫酸盐气溶胶，是环境酸化的重要前驱物。二者对环境均有较大危害。B项，二氧化碳是空气中常见的温室气体，是一种气态化合物，常温下是一种无色无味、不助燃、不可燃的气体，密度比空气大。二氧化碳对环境的负面影响主要是因为它具有保温的作用，会逐渐使地球表面温度升高，被认为是加剧温室效应的主要来源。水蒸气是水的气体形式，其对环境的负面影响在于水蒸气是一种温室气体，可能会造成温室效应。C项，氢气在常温常压下是一种极易燃烧、无色透明、无臭无味的气体，是世界上已知的密度最小的气体，没有毒性。医学上用氢气来治疗部分疾病。其危险在于易燃易爆性，对环境没有明显负面影响。稀有气体或惰性气体是指元素周期表上的18族元素。天然存在的稀有气体有六种，即氦（He）、氖（Ne）、氩（Ar）、氪（Kr）、氙（Xe）和具放射性的氡（Rn）。一般无毒，只有在浓度比较高时对人体产生不良影响，对环境的负面影响较小。D项，甲烷是最简单的有机物，在自然界的分布很广，是天然气、沼气、坑气等的主要成分。甲烷对环境的负面影响主要体现在它是一种温室气体，可能会造成温室效应。氮气通常状况下是一种无色无味的气体，而且一般氮气比空气密度小。氮气的化学性质不活泼，常温下很难跟其他物质发生反应，但在高温、高能量条件下可与某些物质发生化学变化，用来制取对人类有用的新物质。氮气对环境没有明显负面影响。综上比较，一氧化氮和二氧化硫对环境的负面影响最大。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-71", "q": "稀土有“工业维生素”的美称，广泛应用于军事、石化、轻纺、农业等多个领域。下列关于稀土的说法不正确的是：", "options": ["稀土可大幅度提高用于制造飞机、坦克、导弹的钢材和铝合金的性能", "稀土可促进种子萌发、提高种子发芽率、促进幼苗生长", "轻纺工业中，稀土可用于染色、降低织物的白度等方面", "复合稀土氧化物可以用作内燃机尾气净化催化剂"], "a": 2, "e": "【C】A项正确，稀土有工业“黄金”之称，由于其具有优良的光、电、磁等物理特性，能与其他材料组成性能各异、品种繁多的新型材料，其最显著的功能就是大幅度提高其他产品的质量和性能。比如大幅度提高用于制造坦克、飞机、导弹的钢材、铝合金、镁合金、钛合金的战术性能。B项正确，稀土元素可以提高植物的叶绿素含量，增强光合作用，促进根系发育，增加根系对养分吸收。还能促进种子萌发，提高种子发芽率，促进幼苗生长。C项错误，稀土元素在织物上的处理效果表现在织物的白度增加、毛效提高和强力提高等方面，并非降低织物的白度。D项正确，用稀土制成的分子筛催化剂，具有活性高、选择性好、抗重金属中毒能力强的优点，因而取代了硅酸铝催化剂用于石油催化裂化过程，复合稀土氧化物还可以用作内燃机尾气净化催化剂。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-72", "q": "关于灭火器的原理和使用方法，下列说法不正确的是：", "options": ["泡沫灭火器使用时会产生大量的二氧化碳，将燃烧物与空气隔绝", "使用干粉灭火器时需要将灭火器倒立，使两种物质混合产生干粉", "在使用二氧化碳灭火器时，要将手放在钢瓶的木柄上以防冻伤", "电路失火在没切断电源之前不能使用泡沫灭火器灭火"], "a": 1, "e": "【B】B项说法不正确，在使用干粉灭火器时，将灭火器倒立，是为了使其中预先储存的干粉松动，不是为了产生干粉。化学泡沫灭火器使用时需要倒立，才是为了使灭火器中的两种化学物品混合发生化学反应，产生灭火的泡沫。A、C、D三项说法均正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-73", "q": "2011 年3 月，日本强地震造成核泄漏。为降低和防止核泄漏造成的危害，发生核泄漏时，下列做法中不正确的是：", "options": ["离开核泄漏地区后，要换衣服和鞋子并将其放在塑料袋中", "食品不暴露在空气中，而是放在密闭的容器内或冰箱里保存", "进入被放射物质污染的地区时，使用手帕、毛巾等捂住口鼻", "将从核泄露国家回来的人员隔离，避免他人受到放射性元素的伤害"], "a": 3, "e": "【D】A、B、C三项都是正确的做法；D项说法有误，核辐射并非传染病，不会影响别人，只是受辐射个体会受到影响。本题为选非题，故正确答案为D。本题相关知识点：放射性物质以波或微粒形式发射出的一种能量就叫核辐射，核爆炸和核事故都有核辐射。体外辐射源对人体的照射称外照射。外照射的防护方法主要有：①受照射时间的控制；②增大与辐射源间的距离；③采用屏蔽物屏蔽。进入人体内的放射性核素作为辐射源对人体的照射称内照射。控制内照射主要依据以下原则：①防止或减少放射性物质进入体内；②对于放射性核素可能进入体内的途径要予以防范；③通过药物或其他手段使已经进入人体的放射性物质排出体外。", "tag": "科技常识"},
{"id": "tech-74", "q": "下列表述不正确的是：", "options": ["自然界中的金属在常温下一般呈固态", "惰性气体不与其他物质发生化学反应", "天然气是一种无色无味无毒的气体燃料", "钢是铁和碳按照一定比例加工而成的合金"], "a": 1, "e": "【B】A项正确，A项只说的是“一般”情况，说法正确；B项错误，惰性气体只是化学性质很不活泼，但并不是绝对不与其他物质发生化学反应；C项正确，天然气是一种无色无味无毒的气体燃料，其主要成分是甲烷；D项正确，钢是铁和碳的合金，含碳量小于2%，并含有少量其他元素。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-75", "q": "下列有关能源的表述正确的是：", "options": ["目前核电站对核能的利用方式分为核聚变和核裂变两种", "氢气是一种可实现二氧化碳零排放的能源", "太阳能电池的工作原理是光化学转换", "可燃冰是一种稀缺的能源资源"], "a": 1, "e": "【B】本题考查能源方面的知识。A项错误，核能的利用方式分为核聚变和核裂变两种，但到目前为止，达到工业应用规模的核能只有核裂变能，而核聚变能只实现了军用，即制造氢弹。因此，目前核电站对核能的利用方式只有核裂变一种。B项正确，氢气是最洁净的燃料。氢气的燃烧产物是水，对环境不产生任何污染。因而可以实现二氧化碳的零排放。C项错误，太阳能电池是通过光电效应或者光化学效应直接把光能转化成电能的装置。以光电效应工作的晶硅太阳能电池为主流，而以光化学效应工作的薄膜电池实施太阳能电池则还处于萌芽阶段。D项错误，天然气水合物又称“可燃冰”，是分布于深海沉积物或陆域的永久冻土中，由天然气与水在高压低温条件下形成的类冰状的结晶物质。其资源密度高，全球分布广泛。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-76", "q": "食用含碘食盐可满足人体对碘的摄取，人们平时使用的食盐一般是含碘食盐。我们对含碘食盐要密封保存，因为碘具有。", "options": ["易潮性", "挥发性", "吸味性", "还原性"], "a": 1, "e": "【B】本题考查科技常识。A项错误，易潮性是指物体吸收水蒸气而引起自身理化性质发生改变的特性。B项正确，碘盐中的碘化物是一种很不稳定的化学物质，一经氧化，碘分子就会从碘盐中逸脱。由于碘元素本身的化学性质非常活泼，很容易在风吹、日晒、潮湿、受热等外界因素的影响下而挥发。因此，碘盐要密封保存，以防碘分子挥发。C项错误，吸味性是指物体存放在有异味的环境中时，有吸收异味的特性。D项错误，还原性是指在化学反应中原子、分子或离子失去电子的能力。物质含有的粒子失电子能力越强，物质本身的还原性就越强；反之越弱，而其还原性就越弱。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-77", "q": "从化学组成来看，现在太阳质量大约四分之三是（）。", "options": ["氢", "氧", "碳", "氖"], "a": 0, "e": "【A】本题主要考查科技常识。从化学组成来看，现在太阳质量的大约四分之三是氢，剩下的几乎都是氦，而氧、碳、氖、铁和其他的重元素质量少于，采用核聚变的方式向太空释放光和热。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-78", "q": "食品添加剂被誉为现代食品工业的灵魂。下列食品工业中所应用的食品添加剂与其所属类型，对应错误的是：", "options": ["制作罐头时使用的山梨酸钾——防腐剂", "制作香肠时使用的谷氨酸钠——增味剂", "制作老豆腐时使用的盐卤——凝固剂", "制作面包时使用的碳酸氢钠——酸度调节剂"], "a": 3, "e": "【D】本题考查化学常识，主要涉及食品添加剂方面的知识。A项正确，山梨酸钾是一种常见的食品防腐剂，它能有效地抑制霉菌、酵母菌和好氧性细菌的活性，从而有效地延长食品的保存时间，保持食品原有风味。B项正确，谷氨酸钠是生活中常用的调味料味精的主要成分，是常用的增味剂，具有强烈的肉类鲜味，制作香肠时加入，可以让香肠品尝起来变得更加鲜美，味道更丰富。C项正确，盐卤的主要成分有氯化钠、氯化钾、氯化镁和氯化钙及硫酸镁等，能使蛋白质溶液凝结成凝胶，是制豆腐常用的凝固剂。用盐卤作凝固剂制成的豆腐，硬度、弹性和韧性较强，称为老豆腐。D项错误，碳酸氢钠，俗称小苏打，是一种常见的膨松剂，它加热后会分解成碳酸钠、二氧化碳和水，二氧化碳和水蒸气逸出，可使食品更加蓬松，所以碳酸氢钠并不是酸度调节剂。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-79", "q": "相比普通的中性笔，使用碳素墨水钢笔书写的字迹能长期保存而不褪色，这是因为（）。", "options": ["墨水中的碳还原成稳定的物质", "墨水中的碳跟纸发生反应生成活泼的物质", "墨水中的碳被氧化成活泼的物质", "墨水中的碳的化学性质比较稳定"], "a": 3, "e": "【D】本题考查化学常识。A项错误，碳是一种常见的元素，它的单质可以作为还原剂去还原氧化物，而墨水中的碳作为单质碳，是不需要还原的。因此该表述错误。B项错误，墨水中的碳单质不与纸发生反应。因此该表述错误。C项错误，墨水中的碳在常温下化学性质稳定，不易被氧化，只有在特殊情况下，在高温中可以被氧化。因此该表述错误。D项正确，墨水的主要成分是碳，碳在常温下化学性质很稳定，不容易与其他物质发生反应，受日光照射和空气水分接触不起变化。因此用碳素墨水书写的文字便于保存，不易褪色。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-80", "q": "用水稀释浓硫酸时，应当选择的方式是：", "options": ["将水慢慢倒入浓硫酸中", "将浓硫酸慢慢倒入水中", "浓硫酸和水分层注入", "浓硫酸和水同时注入"], "a": 1, "e": "【B】B项正确，A、C、D三项错误，由于浓硫酸具有强腐蚀性，溶于水时又释放大量的热，易使水沸腾而引起浓硫酸飞溅至皮肤和衣物上导致严重的后果，所以使用和稀释浓硫酸必须严格按要求进行：常将浓硫酸沿器壁慢慢注入水中（烧瓶用玻璃棒引流），并不断搅拌，使稀释产生的热量及时散出。若将水倒入浓硫酸中，一方面由于水的密度远比浓硫酸的小，水将浮在浓硫酸上面而形成两个液层，浓硫酸只在两个液层接触处混溶并放出大量热，从而影响两种液体的混合；另一方面又由于硫酸的质量热容较水的低，当两者混溶时，硫酸的温度会比水的温度升高得快，因而造成强烈的局部高温，使水汽化而造成喷溅。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-81", "q": "下列关于生活常识的做法正确的是：", "options": ["生病时，可用茶水送服西药", "可用聚氯乙烯塑料包装食品", "二氧化硫可作为食品的防腐剂和保鲜剂", "可加过量的亚硝酸钠来保持食品的鲜美"], "a": 2, "e": "【C】C项正确：二氧化硫具有杀菌作用，能抑制腐败、腐烂，可以用作食品的防腐与保鲜。按照标准规定合理使用二氧化硫不会对人体健康造成危害。A项错误：茶水不能用来送服西药，尤其是硫酸亚铁、碳酸亚铁、铁胺等含铁剂和氢氧化铝等含铝剂的西药，遇到茶水中的茶多酚类物质与金属离子结合而沉淀，会降低或失去药效。此外，茶叶含有咖啡因，具有兴奋作用，因此服用镇静、催眠、镇咳类药物时，也不宜用茶水送服，避免药性冲突降低药效。B项错误：聚氯乙烯塑料不能用来包装食品。聚氯乙烯塑料中的增塑剂，含有对苯二甲酸二丁酯、邻苯二甲酸二辛酯等，这些化学品都有毒性。另外，聚氯乙烯塑料制品在较高温度下，如50℃左右就会慢慢地分解出氯化氢气体，这种气体对人体有害。D项错误：过量的亚硝酸钠会致癌。亚硝酸钠在烹调和消化过程中会和食物中的胺反应，产生致癌物质亚硝胺类化合物，因此不能用过量的亚硝酸钠来保持食物鲜美。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-82", "q": "在催化剂中，能够使化学反应加快速度的称为正催化剂，使化学反应速度减慢的称为负催化剂，下列属于负催化剂的是：", "options": ["为防止食用油脂酸化而加入的没食子酸正丙酯", "在分解氯酸钾制备氧气实验时加入的二氧化锰", "在用锌和稀硫酸反应制备氢气时加入的硫酸铜", "在大雪后为促使积雪融化而在马路上撒下的盐"], "a": 0, "e": "【A】本题考查化学常识，主要考查催化剂相关知识。题干给出了负催化剂的定义，即导致化学反应速度减慢的催化剂。可将此概念代入各选项进行一一比对。A项正确，没食子酸正丙酯的作用是减慢食用油脂酸化的速度，属于负催化剂。B项错误，二氧化锰能加快氯酸钾的分解速度，属于正催化剂，故排除。C项错误，硫酸铜能加快锌和稀硫酸的反应，属于正催化剂，故排除。D项错误，促使积雪融化，在马路上撒盐属于物理现象，不是化学反应。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-83", "q": "我国古代创造了灿烂的青铜文明，司母戊鼎和四羊方尊是青铜器的代表。以下关于青铜的说法，不正确的是（）。", "options": ["青铜属于纯净物", "青铜属于金属材料", "青铜的硬度比铜大", "青铜耐腐蚀，易铸造成形"], "a": 0, "e": "【A】青铜是金属冶铸史上最早的合金，在纯铜（红铜）中加入锡或铅的合金，因此青铜是混合物而非纯净物，所以A选项错误，B选项表述正确。青铜具有熔点低、硬度大、可塑性强、耐磨、耐腐蚀、色泽光亮等特点，适用于铸造各种器具、机械零件、轴承、齿轮等，所以C、D项表述正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-84", "q": "爱国诗人于谦的《石灰吟》中，只含有化学变化的诗句是：", "options": ["千锤万凿出深山", "烈火焚烧若等闲", "粉身碎骨浑不怕", "要留清白在人间"], "a": 1, "e": "【B】分析诗句，A项“千锤万凿出深山”指开采石灰石，“千锤万凿”说明形状发生变化，但没有新物质产生，属于物理变化；B项“烈火焚烧若等闲”指高温煅烧石灰石，碳酸钙在高温条件下分解成氧化钙和二氧化碳，发生了化学变化；C项“粉身碎骨浑不怕”是指氧化钙与水反应生成氢氧化钙，发生了化学变化，同时“粉身碎骨”也是物质形状发生变化，属于物理变化；D项“要留清白在人间”指氢氧化钙与二氧化碳反应生成碳酸钙沉淀和水，发生了化学变化，同时“清白”是对物体颜色状态的表述，涉及到物理变化。因此，四个选项中，只含有化学变化的是B项。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-85", "q": "结合化学知识和生活经验，下列说法不能减少环境污染的是：", "options": ["将废弃的塑料袋、一次性塑料餐具等塑料制品集中堆放焚烧", "将汽车发动机产生的尾气通过放有氧化钯催化剂的排气管后排放", "在燃烧前对煤进行净化，去除原煤中的硫成分和灰成分", "城市公交车和出租车采用液化天然气(LNG)代替普通汽油"], "a": 0, "e": "【A】A项将废弃塑料集中焚烧，会造成各种有毒气体，造成更严重的大气污染。B、C、D三项都属于节能减排的措施。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-86", "q": "酒精灯燃烧的火焰分为外焰、内焰和焰心，下列说法不正确的是：", "options": ["外焰燃烧最充分", "内焰最明亮", "外焰一般呈蓝色", "焰心的温度最高"], "a": 3, "e": "【D】酒精灯是以酒精为燃料的加热工具，广泛用于实验室、工厂、医疗、科研等。由于其燃烧过程中不会产生烟雾，因此也可以通过对器械的灼烧达到灭菌的目的。又因酒精灯在燃烧过程中会产生热量，可以对其他实验材料加热。它的加热温度一般能达到400～1000，且安全可靠。酒精灯可分为挂式酒精喷灯、坐式酒精喷灯以及常规酒精灯，实验室等一般以玻璃材质最多，其主要由灯体、棉灯绳（棉灯芯）、瓷灯芯、灯帽和酒精构成。酒精灯的火焰分为外焰、内焰和焰心三部分，外焰的温度最高且一般呈蓝色，焰心的温度最低。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-87", "q": "小辉想除去卫生间瓷砖上的铁锈痕迹。在用清水洗涤之前，她从家中选择了一种最合适的物质对铁锈进行处理，这种物质是：", "options": ["食盐水", "汽油", "米酒", "白醋"], "a": 3, "e": "【D】三氧化二铁是铁锈的主要成分。铁锈的主要成因是铁金属在杂质碳的存在下，与环境中的水分和氧气反应，铁金属便会生锈。其难溶于水，不与水反应。溶于酸，与酸反应。不与碱性物质反应。所以可以选择白醋溶解。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-88", "q": "下列塑料制品中，能够作为食物容器放入微波炉中加热的是：", "options": ["聚氯乙烯（PVC）", "聚乙烯（PE）", "聚丙烯（PP）", "聚苯乙烯（PS）"], "a": 2, "e": "【C】聚丙烯（PP），由丙烯聚合而成，透明度也较聚乙烯好，比聚乙烯硬，饭店里打包用的盒子大多是用它做的，做成的塑料盒也可以放进微波炉加热。其他三种均不可在微波炉中加热。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-89", "q": "下列关于石灰的说法错误的是：", "options": ["生石灰通常可以作为食品干燥剂", "澄清石灰水放置在空气中易变浑浊", "汉白玉与石灰石的主要成分相同", "“烈火焚烧若等闲”指熟石灰的高温煅烧"], "a": 3, "e": "【D】A项正确，食品干燥剂一般无毒、无味、无接触腐蚀性、无环境污染。食品干燥剂是为了降低食品袋中的湿度，防止食品变质腐败；食品中常用的干燥剂是氧化钙（俗称生石灰，化学式是CaO）和硅胶，蒙脱石干燥剂，氯化钙干燥剂，纤维干燥剂。B项正确，二氧化碳通入澄清石灰水中变浑浊，是因为二氧化碳和澄清石灰水反应生成碳酸钙沉淀，化学方程式为：+=↓+。C项正确，汉白玉主要成分是碳酸钙，它是一种化合物，化学式是，基本不溶于水。石灰石主要成分是碳酸钙。石灰和石灰石大量用做建筑材料，也是许多工业的重要原料。D项错误，“烈火焚烧若等闲”指烧炼石灰石，石灰石的主要成分是碳酸钙，而熟石灰的主要成分是氢氧化钙，二者主要成分不同。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-90", "q": "下列关于铅的说法错误的是：", "options": ["铅笔芯的主要成分是铅", "香烟中是含铅的", "铅在人体内日积月累，不会分解", "汽油中添加铅元素可以起到防爆的作用"], "a": 0, "e": "【A】A项错误，铅笔的笔芯是用石墨和黏土按一定比例混合制成的，其主要成分是石墨；B项正确，烟草燃烧时释放的烟雾中含有3800多种已知的化学物质，绝大多数对人体有害，其主要有：尼古丁、烟焦油、苯并芘强致癌物、放射性物质、刺激性化合物、有害金属，烟草中含砷、汞、镉、镍、铅等有害金属；C项正确，铅进入人体除部分通过粪便、汗液排泄外其余则溶入血液阻碍血液合成导致人体贫血出现头痛、眩晕、乏力、困倦、便秘和肢体酸痛等；D项正确，汽车多年来一直使用含铅汽油(含有四乙基铅添加剂)，使用四乙基铅的目的是作为抗爆剂加入汽油的，是用来消除汽油燃烧时产生的爆震。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-91", "q": "下列元素，空气中含量最多的是：", "options": ["氧", "氖", "氦", "氮"], "a": 3, "e": "【D】空气中含量最多的气体是氮气，约占空气体积的78%。氧气占21%，稀有气体占0.94%，二氧化碳占0.03%，水和杂质占0.03%。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-92", "q": "食物过敏是在摄入食物时由于食物中的某些成分引起免疫应答，导致消化系统内或全身性的变态反应。以下食物成分容易引起过敏的是：", "options": ["纤维素", "蛋白质", "维生素", "脂肪"], "a": 1, "e": "【B】B项正确：蛋白质是组成人体一切细胞、组织的重要成分。机体所有重要的组成部分都需要有蛋白质的参与。过敏反应实际上是一种抗体-抗原的免疫应答，大分子容易引发机体的免疫应答，造成过敏现象。蛋白质种类非常多，且蛋白质可分解为多肽，一方面分解后种类再次增加，另一方面多肽可和其他物质反应生成新的物质。以上物质都是大分子，所以蛋白质容易造成过敏现象。A项错误：纤维素是由葡萄糖组成的大分子多糖，不溶于水及一般有机溶剂，是自然界分布最广、含量最多的一种多糖，也是一种重要的膳食纤维。所以纤维素不会引起食物的过敏反应。C项错误：维生素是维持身体健康所必需的一类有机化合物。维生素既不参与构成人体细胞，也不为人体提供能量，而是一类调节物质，在物质代谢中起重要作用。所以维生素不会引起食物的过敏反应。D项错误：脂肪是甘油和三分子脂肪酸合成的甘油三酯，存在于人体和动物的皮下组织及植物体中，是生物体的组成部分和储能物质。脂肪可溶于多数有机溶剂，但不溶解于水。脂肪是生物体的能量提供者。所以脂肪不会引起食物的过敏反应。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-93", "q": "海洋动力资源是一类零耗竭，可再生的能源。下列不属于海洋动力资源的是：", "options": ["海底天然气", "潮汐能", "海洋温差能", "海流能"], "a": 0, "e": "【A】海洋动力资源主要指海水运动过程中产生的潮汐能、波浪能、海流能及海水因温差和盐度差而引起的温差能与盐差能等。A项错误，不是；B、C、D三项正确，都属于海洋动力资源。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-94", "q": "由同一种元素所构成的不同单质被称为同素异形体，下列哪组物质不属于同素异形体：", "options": ["钢和铁", "金刚石和石墨", "红磷和白磷", "氧气和臭氧"], "a": 0, "e": "【A】A项表述错误：钢是混合物，不是单质，当选。B项表述正确：金刚石和石墨都由碳元素组成，只是碳原子的排列不同，排除。C项表述正确：红磷和白磷均为由磷元素构成的单质，是磷元素的两种重要的同素异形体，排除。D项表述正确：臭氧和氧气组成分子的原子数不同，是一对同素异形体，排除。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-95", "q": "浴室的玻璃门在使用一段时间之后，淋水的一面总会结下一些白色的物质，难以清洗。以下清洗方法能较好去除这些物质的是：", "options": ["将食用碱洒在微湿抹布上擦洗", "将酒精浇在抹布上擦洗", "用钢丝球擦洗", "在白醋中加入食盐用抹布擦洗"], "a": 3, "e": "【D】浴室玻璃门上的白色物质是水垢，属碱性，用白醋擦洗可除去。故正确答案为D。相关知识点：食用碱加水浸泡水垢才能将其去除，A项撒在微湿抹布上擦洗水垢的效果并不好。", "tag": "科技常识"},
{"id": "tech-96", "q": "废旧电池是一种常见的污染物，是破坏生态环境的“杀手”。下列关于废旧电池的说法错误的是：", "options": ["废旧电池含有大量的重金属", "废旧电池无法回收再利用，应集中处理", "有害物质会从废旧电池中溢出，污染水和土壤", "废旧电池如果随意丢弃，其中的有害物质会通过各种媒介进入人体"], "a": 1, "e": "【B】A选项，电池主要含铁、锌、锰等重金属元素，A项正确；B选项，从节约资源的角度来看，废旧电池中铁、锌、锰等重金属元素可回收利用。国际上通行的废旧电池处理方式大致有三种：固化深埋、存放于废矿井、回收利用。其中回收利用分为热处理、湿处理和真空热处理。B项错误；C选项，废旧电池含有微量的汞，汞是有毒的物质，可从电池中溢出，污染水和土壤，C项正确；D选项，废旧电池如果随意丢弃，其中的有害物质如汞元素会溢出，通过各种媒介如水等进入人体中，D项正确。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-97", "q": "化学是一门以实验为基础的科学。下列实验操作中，正确的是（）。", "options": ["", "", "", ""], "a": 3, "e": "【D】本题考查科技常识。A项错误，绝对禁止用燃着的酒精灯去引燃另一只酒精灯，因为酒精灯不是封闭的，倾斜的话酒精会流出来。酒精易燃，容易引起火灾。B项错误，读取量筒中的液体体积时，视线要与量筒内凹液面的最低处保持水平，再读出液体体积的数值。仰视或俯视液体凹液面读数，都会偏离实际值。C项错误，在用托盘天平称量物品时，应该是称量物放在左盘，砝码放在右盘。另外要在天平两边各放一张相同的纸，防止物品潮解。D项正确，加热试管中的液体时，要将试管夹夹在离试管口的三分之一处，使试管倾斜。另外试管内液体的量不可超过试管容积的三分之一。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-98", "q": "烟花又称烟火、焰火，烟花的最大特色是能够绽放出五彩缤纷的颜色。制作烟花的过程中加入一些发光剂和发色剂能够使烟花放出五彩缤纷的颜色。氯化钠和硫酸钠都属于钠的化合物①，他们在燃烧时会发出黄色②火焰。硝酸钙和碳酸钙在燃烧时会发出砖红色③火焰。根据色光加成原理，绿光和红光按适当比例混合能产生紫光④效果。这段文字中画线部分错误的是（）。", "options": ["①", "②", "③", "④"], "a": 3, "e": "【D】本题考查科技常识。A项正确，化合物是由两种或两种以上的元素组成的纯净物。氯化钠和硫酸钠均属于化合物。B、C项正确，焰色反应，也称作焰色测试及焰色试验，是某些金属或它们的化合物在无色火焰中灼烧时使火焰呈现特殊颜色的反应。在化学上，常用来测试某种金属是否存在化合物，同时利用焰色反应，人们在烟花中有意识地加入特定金属元素，使焰火更加绚丽多彩。钠的焰色反应为黄色，钙的焰色反应为砖红色。D项错误，色光三原色（加法三原色）为：红、绿、蓝。根据光色加成原理，适当的红光和绿光能合成黄光；适当的绿光和蓝光能合成青光；适当的蓝光和红光能合成品红色的光。所以，绿光和红光按适当比例混合会产生黄光的效果。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-99", "q": "化学与人们的生活紧密相关，下列关于生活中的化学常识，说法正确的一项是（）。", "options": ["正常情况下雨水偏碱性", "煤炭燃烧时若空气不足会产生大量的二氧化碳等有毒气体", "为了保护环境应当推广使用无铅汽油", "在江河、湖泊中水体富营养化的典型代表是“赤潮”"], "a": 2, "e": "【C】本题考查科技常识。A项错误，正常雨水偏酸性，PH值约为5.6，这是因为大气中二氧化碳溶于水的缘故。B项错误，煤等燃料燃烧时，若空气不足，燃烧就不完全，会产生大量的一氧化碳等气体，而非二氧化碳。C项正确，曾经人们为了改善汽油机中汽油的燃烧，减轻爆震现象，人们往汽油中添加四乙基铅等抗爆震剂，但同时这种做法也带来了严重的铅污染，而铅会对人体的许多系统都造成损害，特别是神经系统，目前世界上许多国家都已经限制汽油中铅的加入量，我国也开始部署，在全国范围内将逐渐实现汽油无铅化。D项错误，含氮和磷的物质在分解过程中，大量消耗水中的氧气并且释放出养分，使得藻类和其他浮游生物大量繁殖，这种现象在江河、湖泊中出现我们称之为“水华”，在海湾出现称之为“赤潮”。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-100", "q": "下列描述的金属中，属于有色金属的是（）。①常见的金属元素，人体必需微量元素，参与人体内氧气运输②化学性质极活泼的金属元素，常用于制造化肥③密度最小的金属，用于原子反应堆、制轻合金及电池④地壳含量最高的金属元素，广泛应用于航空汽车建筑领域", "options": ["①②③", "①②④", "①③④", "②③④"], "a": 3, "e": ".【D】本题考查科技常识。有色金属是黑色金属（铁、铬、锰）以外的所有金属的统称。为铁。铁在生活中分布较广，占地壳含量的，仅次于氧、硅、铝，位居地壳含量第四。纯铁是柔韧而延展性较好的银白色金属，用于制发电机和电动机的铁芯，铁及其化合物还用于制磁铁、药物、墨水、颜料、磨料等。铁是人体必需的微量元素，人体内铁的总量约4～5克，是血红蛋白的重要部分，参与氧的运输和储存。铁属于黑色金属。②为钾。钾是一种银白色的软质金属，蜡状，可用小刀切割，熔沸点低，密度比水小，化学性质极度活泼（比钠还活泼），属于碱金属。钾肥是一种常见肥料，钾能促进植株茎秆健壮，改善果实品质，增强植株抗寒能力，提高果实的糖分和维生素C的含量。钾属于有色金属。③为锂。锂是一种银白色的金属元素，质软，是密度最小，最轻的金属。常用于原子反应堆、制轻合金及电池等。锂属于有色金属。④为铝。铝是一种银白色轻金属。在潮湿空气中能形成一层防止金属腐蚀的氧化膜。铝元素在地壳中的含量仅次于氧和硅，居第三位，是地壳中含量最丰富的金属元素。铝合金在航空、建筑、汽车三大重要工业的发展中起到非常重要的作用。铝属于有色金属。因此属于有色金属的是②③④。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-101", "q": "食盐是我们的生活必备品，下列关于食盐的说法正确的是（）。", "options": ["加碘食盐中主要含碘物质是碘酸钠", "炖肉时加入食盐，可以使肉中的蛋白质变性", "炒菜时多放醋会影响加碘食盐中碘的吸收", "亚铁氰化钾有剧毒，不能用作食盐添加剂"], "a": 2, "e": ".【C】本题主要考查科技常识。A项错误，加碘食盐中主要含碘物质是碘酸钾。碘酸钠是一种有毒化合物，对眼睛、上呼吸道、粘膜和皮肤等有刺激性。B项错误，蛋白质变性是指其的空间结构遭到破坏，而使生物活性丧失。常见的能使蛋白质变性的化学方法有加强酸、强碱、重金属盐等。食盐是轻金属盐，不能使蛋白质变性，在蛋白质水溶液中加入食盐，会发生盐析反应，可使蛋白质从溶液中析出，再次加水后蛋白质还会溶解。C项正确，酸性条件下，碘酸钾易被维生素C等还原性物质还原而影响吸收，因此多加醋会降低碘的利用率。D项错误，亚铁氰化钾性质稳定，毒性极低，它具有抗结性能，可用于防止细粉、结晶性食品板结，是一种合法的食盐抗结剂。有剧毒的是氰化钾，而亚铁氰化钾稳定性很高，只有在400℃高温下才会分解产生氰化钾，但日常烹调温度通常低于340℃，因此烹调温度下亚铁氰化钾分解可能性极小，所以食盐中很多都会添加亚铁氰化钾。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-102", "q": "生活中难免遇到各种意外，出现下列情形时的急救措施，不当的是（）。", "options": ["氨气进入眼睛，先后用水和稀醋酸冲洗", "皮肤接触稀硫酸，先后用水和苏打水冲洗", "化肥厂金属钠粉末失火，用二氧化碳灭火器救火", "皮肤粘附生石灰，拿干布擦净后用水冲洗"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，氨气（）极易溶于水，溶于水后跟水结合成氨水，氨水发生部分水解，电离出铵根离子和氢氧根离子，故氨水显弱碱性。氨气进入眼睛后遇水生成弱碱性氨水，对眼睛有一定的刺激性，这时需用水冲洗眼睛，以稀释碱的浓度，之后用稀醋酸或稀硼酸（弱酸）等冲洗，以中和碱性。然后就医。B项正确，硫酸为强酸，稀硫酸仍具有较强的酸性，皮肤接触稀硫酸后会受到较强的刺激，这时需用水冲洗，以稀释酸的浓度，之后用显弱碱性的苏打水冲洗，以中和酸性。苏打水为碳酸氢钠溶液，碳酸氢钠在水溶液中完全电离，生成钠离子和碳酸氢根离子，碳酸氢根离子水解生成氢氧根，故溶液显弱碱性。C项错误，钠属于碱金属，碱金属是指在元素周期表中IA族除氢外的六个金属元素，即锂、钠、钾、铷、铯、钫。碱金属燃烧时生成氧化物,如锂、钠、钾燃烧生成氧化锂、过氧化钠、超氧化钾，其中过氧化钠、超氧化钾等会与二氧化碳反应而释放氧气，起到助燃作用，故钠失火后不可使用二氧化碳灭火器，同时也不可使用泡沫灭火剂，钠与泡沫中的水分反应生成氢气，过氧化钠也会与水反应而释放氧气，故只可使用沙土覆盖灭火。D项正确，氧化钙（）为碱性氧化物，对湿敏感，易从空气中吸收二氧化碳及水分，与水反应生成氢氧化钙，并产生大量热，有腐蚀性。皮肤粘附氧化钙后，氧化钙会与汗液反应，放出热量，会灼伤皮肤，这时需用干布将氧化钙擦拭干净，之后用水冲洗，将残留的微量氧化钙清除，同时起到降温作用，切不可直接用水冲洗，以免二者反应放出大量热，加剧皮肤灼伤。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-103", "q": "下列关于化学材料的表述，有误的是（）。", "options": ["镍钛合金也称记忆合金，它能用于牙齿矫形", "聚乙烯对人体有毒，但可制作电线包皮", "玻璃钢耐腐蚀、强度高，可用于生产飞机、船舶等", "高吸水性树脂可以用于制作婴儿尿布"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，镍钛合金也称记忆合金，它在外力作用下会发生变形，当把外力去掉后，在一定的温度条件下，能恢复原来的形状。这种合金具有百万次以上的恢复功能。在做牙齿矫形时，人们就是利用记忆合金在一定温度下做成矫形弓丝，矫形弓丝为了恢复原来的形状，便对牙齿施力，于是牙齿在记忆合金的作用下变得整齐好看。B项错误，聚乙烯（PE）无毒，电绝缘性能好，耐化学腐蚀、耐热、无毒，可制作食品袋、药物包装材料、日常用品、管道、绝缘材料等。C项正确，玻璃钢是将玻璃纤维和高分子化合物（如聚酯类树脂、环氧树脂等）复合而成的。它具有强度高、质量轻、耐腐蚀、抗冲击、绝缘性好等优良性能，可广泛地用于飞机、汽车、船舶、建筑和家具等的生产。D项正确，吸水性物质与生活、生产和工作的关系十分密切。高吸水性树脂的研究是从淀粉改性开始的，在20世纪80年代实现了工业化生产。高吸水性树脂具有奇特的吸水和保水能力，对纯水的吸附量可达自身质量的几十倍乃至几千倍。高吸水性树脂在生活中用于婴儿尿布、卫生巾等，在工农业生产中用作干燥剂、保鲜剂等。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-104", "q": "金属资源是人类社会的宝贵财富，是人类发展必不可少的物质基础。下列金属与其别称对应错误的是（）。", "options": ["铝——“会飞的金属”", "镭——“白色石油”", "稀土——“工业维生素”", "钛——“太空金属”"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，铝是一种银白色的轻金属，是地壳中含量最丰富的金属元素。由于其重量轻，可制成各种铝合金，如硬铝、超硬铝。由于硬铝既保持了密度小的特性，又克服了纯铝软的特点，因此成为了飞机等航天器的重要性能材料，使它得天独厚地能随飞机一起腾云驾雾，遨游高空，因此被誉为“会飞的金属”。B项错误，“白色石油”指的是锂。锂是一种银白色的金属元素，是密度最小的金属，锂在高能电池，电动汽车，导弹卫星，战舰潜艇，核能等方面具有重要应用，广泛应用在航空航天、潜艇、装甲车辆等多个军事领域。因此，锂又被称为21世纪改变世界格局的“绿色能源金属”、“白色石油”。镭是一种银白色金属，具有很强的放射性，该金属元素由居里夫人发现。镭能放射出和两种射线，能够破坏、杀死细胞和细菌，常用来治疗癌症等。C项正确，稀土是镧系元素和钪、钇共十七种金属元素的总称，广泛应用于石油、化工、冶金、纺织、陶瓷以及永磁材料等行业，被称为“工业维生素”。D项正确，钛是一种银白色的过渡金属，其特征为重量轻、强度高、具金属光泽，耐湿氯气腐蚀。由于其稳定的化学性质，良好的耐高温、耐低温、抗强酸、抗强碱，以及高强度、低密度，被美誉为“太空金属”，广泛应用于航天、航空器材制造等。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-105", "q": "在日常生活中，我们经常根据不同的需求去增大或减小压强，下列哪种做法对于压强的改变与其他三项不同？", "options": ["挖掘机上装有履带", "沙发被设计得很柔软", "破窗锤锤头被设计成锥形", "滑雪板比较宽大"], "a": 2, "e": ".【C】本题考查科技常识。压强指物体所受的压力与受力面积之比，其计算公式是：。据此公式可知，在所受压力F不变的情况下，压强与受力面积成反比。A项，挖掘机上装上履带后，相比于之前的轮子，增大的与地面的接触面积（即受力面积）。在压力一定时，增大受力面积，可减小压强。B项，沙发设计的很柔软，人们坐到沙发上时会“陷”下去，身体与沙发充分接触，即增大了受力面积，减小了压强，所以人体会很舒服。C项，用破窗锤锥形尖头破窗时，锤头与玻璃的接触面积仅为锥形的尖部，与普通锤头相比，减小了受力面积，增大了压强，因此很容易破窗。D项，用滑雪板滑雪，由于滑雪板宽大，增大了受力面积，减小了压强，避免在滑雪时陷入雪中。综上，可知A、B、D三项原理相同，均是减小了压强，C项是增大了压强。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-106", "q": "在铁饼比赛中，运动员会首先手握铁饼高速旋转几圈后再将其掷出。这样做，主要是为了让铁饼：", "options": ["获得更大的角加速度", "获得更大的角速度", "获得更大的加速度", "受到更大的力"], "a": 1, "e": ".【B】本题主要考查物理常识。A项错误，角加速度，是描述物体角速度的大小和方向对时间变化率的物理量。B项正确，角速度，是以弧度为单位的圆（一个圆周为,即：)，在单位时间内所走的弧度。人体在旋转几圈后，会加大角速度，从而加大铁饼投掷的初速度，这样铁饼会投掷得更远。C项错误，加速度，是速度变化量与发生这一变化所用时间的比值，是描述物体速度变化快慢的物理量。D项错误，铁饼在脱离手后，只受重力和空气阻力，运动员高速旋转几圈后再将铁饼掷出，是加大铁饼的角速度。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-107", "q": "下列关于生活现象的说法错误的是：", "options": ["无风时落叶各处受空气作用力不均，因此呈曲线翻转落下", "衣服湿后对光线的反射能力减弱，因此颜色比干的时候深", "挂钟电池耗尽后，秒针因受到重力矩的作用，会停在30 秒的位置", "自来水中含有少量次氯酸，因此不宜直接用自来水养鱼​"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，由于落叶各处凸凹不同，形状各异，因而在下落过程中，其表面各处的气流速度不同，根据流体力学原理，流速大，压强小，致使落叶上各处受空气作用力不均匀，且随落叶运动情况的变化而变化，所以落叶不断翻滚，曲折下落。B项正确，物体反射的光线如果很多，那么我们看到它的颜色也就浅；它反射的光线很少，那么它的颜色就会很深。衣物的潮湿程度和光反射率呈负相关，所以衣服湿后对光线的反射能力减弱，因此颜色看起来比干的时候深。C项错误，挂在壁墙上的石英钟，当电池的电能耗尽而停止走动时，其秒针往往停在刻度盘上“9”的位置。这是由于秒针在“9”的位置处受到重力矩的阻碍作用最大。所以秒针停的位置是45秒处，而不是30秒处。D项正确，自来水常使用氯气消毒，氯气与水发生反应，会生成次氯酸，而次氯酸是一种强氧化剂，对鱼的健康有很大伤害。它使鱼体分泌的粘液失去了对鱼的保护作用，导致其体内电解质代谢严重失调，并在缺氧的状态下窒息死亡，所以，不宜直接用自来水养鱼。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-108", "q": "近年来，3D 电影由于具有非常逼真的视觉效果，而受到人们的广泛喜爱。根据其光学原理，在拍摄和播放3D 电影的过程中所必需的设备组合是：", "options": ["2 台摄影机、2 台放映机、2 个平行偏振片", "3 台摄影机、3 台放映机、2 个平行偏振片", "2 台摄影机、2 台放映机、2 个正交偏振片", "3 台摄影机、3 台放映机、2 个正交偏振片"], "a": 2, "e": ".【C】本题考查科技常识。", "tag": "科技常识"},
{"id": "tech-109", "q": "下列对各种现象（行为）原理解释错误的是：", "options": ["百炼成钢——经高温，铁中的碳和氧气反应生成二氧化碳，其含碳量降低", "雨后彩虹——阳光射到空中接近球形的水滴，造成散射及干涉", "热胀冷缩——分子空隙随温度升高而变大，随温度降低而缩小", "煽风点火——扇动扇子使空气流通，为火焰燃烧补充氧气"], "a": 1, "e": ".【B】A项正确，百炼成钢的主要反应原理是利用氧化还原反应，在高温下，铁中的碳和氧气反应生成二氧化碳，即用氧化剂把生铁里过多的碳和其它杂质氧化成气体或炉渣除去。炼钢时常用的氧化剂是空气、纯氧气或氧化铁，通过氧化反应降低碳含量。B项错误，雨后彩虹是太阳光沿着一定角度射入空气中的水滴所引起的比较复杂的由折射和反射造成的一种色散现象。阳光射入水滴时会同时以不同角度入射，在水滴内亦以不同的角度反射。当中以40至42度的反射最为强烈，造成我们所见到的彩虹。阳光进入水滴，先折射一次，然后在水滴的背面反射，最后离开水滴时再折射一次，总共经过一次反射两次折射。因为水对光有色散的作用，不同波长的光的折射率有所不同。C项正确，热胀冷缩是指物体受热时会膨胀，遇冷时会收缩的特性。而物体热胀冷缩的实质是物质的分子间隙受温度影响而变化。由于分子是不断运动的，温度越高，运动越快，分子之间有间隔，温度越高，间隔越大，反之，则间隔变小。D项正确，燃烧是可燃物和氧发生激烈的氧化反应，无论固体、液体都是从表面开始燃烧，即在游离状态物质元素与氧混合，在达到适宜浓度的时候燃烧最为激烈，风吹过来会带来更多的氧气，从而起到助燃的作用。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-110", "q": "下列关于激光的表述错误的是：", "options": ["条码扫描器可以利用红外线或者激光进行扫描", "CD 唱片利用激光束扫描，通过光电转换重现语言和音乐", "眼科医生常使用激光技术进行近视矫正手术", "激光武器可全天候作战，不受大雾、大雪等天气的影响"], "a": 3, "e": ".【D】本题考查科学常识。A项正确，条码扫描器可以利用红外线或者激光进行扫描。其中，红外线条码扫描的原理是利用扫描器发射红外线光源，然后根据反射的结果，利用芯片来译码，最后再返回条形码所代表的正确字符；而激光条码扫描的原理是通过一个激光二极管发出一束光线，照射到一个旋转的棱镜或来回摆动的镜子上，反射后的光线穿过阅读窗照射到条码表面，光线经过条或空的反射后返回阅读器，由一个镜子进行采集、聚焦，通过光电转换器转换成电信号，该信号将通过扫描器或终端上的译码软件进行译码。B项正确，激光唱片简称“CD”，利用激光束扫描，通过光电转换，重现语言和音乐的唱片。其片基为透明的聚氯乙烯或透明的聚碳酸酯，信号面上刻有很多存储信号的凹坑，并涂有铝质反射层和保护漆。当放唱时，激光束对信号面进行扫描，遇到凹点，光线就发生散射，遇到高出凹点的表面，光线就被反射回来，这样就产生了时断时续的反射。放音部分接收到这种反射信号，重新把它们变成原来形式的电脉冲，再把电脉冲变成声音重放出来。C项正确，激光作用于生物机体时，它能被吸收转化成热能，几秒钟内温度可高达数百至上千度，同时可产生很强的光压。这种机械作用与热效应一起，能使激光成为一把锐利的“光刀”，采用激光刀进行手术，切口出血少，不易感染；切割骨骼速度快，切口平滑，在近视矫正、肿瘤切除等手术有着广泛应用。D项错误，激光武器是用高能的激光对远距离的目标进行精确射击或用于防御导弹等的武器，具有快速、灵活、精确和抗电磁干扰等优异性能，在光电对抗、防空和战略防御中可发挥独特作用。激光武器的缺点是不能全天候作战，受限于大雾、大雪、大雨，且激光发射系统属精密光学系统，也受大气影响严重，如大气对能量的吸收、大气扰动引起的能量衰减、热晕效应、湍流以及光束抖动引起的衰减等。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-111", "q": "下列与汽车有关的说法错误的是：", "options": ["测距倒车雷达主要利用的是红外线", "新能源汽车的动力来源包括电能、氢能等", "汽车转弯时，前轮的转弯半径比同一侧的后轮大", "汽车行驶时能通过发动机水箱中循环流动的水帮助散热"], "a": 0, "e": ".【A】本题考查科技常识。A项错误，测距倒车雷达在倒车时，利用超声波原理，由装置在车尾保险杠上的探头发送超声波撞击障碍物后反射此声波，计算出车体与障碍物间的实际距离，然后提示给司机，使停车或倒车更容易、更安全。B项正确，新能源汽车是指采用非常规的车用燃料作为动力来源(或使用常规的车用燃料，但采用新型车载动力装置)，综合车辆的动力控制和驱动方面的先进技术，形成的技术原理先进、具有新技术、新结构的汽车。新能源汽车包括纯电动汽车、增程式电动汽车、混合动力汽车、燃料电池电动汽车、氢发动机汽车、其他新能源汽车等。其动力来源主要有电能、氢能、燃气、乙醇等。C项正确，车辆转弯时，前、后车轮的运动轨迹不重合，前轮作为主控轮，它的转弯半径比同一侧的后轮大，从而形成内轮差。D项正确，汽车发动机常用循环流动的水帮助散热，主要原因是水的比热容比较大，在温度升高的同时，能够吸收的热量较多，所以用水来做冷却剂。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-112", "q": "关于能量与做功，下列说法正确的是：", "options": ["雨点从高空中匀速下落时只有重力做功", "匀速圆周运动的物体动能始终发生变化", "自由落体过程中物体的机械能保持不变", "向上飞的石子重力做负功导致势能减小​"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，牛顿第一运动定律，又称惯性定律、惰性定律，定义为：一切物体在没有受到外力的作用时，总保持静止状态或匀速直线运动状态。雨点从高空中匀速下落，说明雨点受到的合外力为零。雨点此时受到向上的空气阻力和向下的重力。如果一个物体受到力的作用，并在力的方向上发生了一段位移，我们就说这个力对物体做了功。显然，雨点受到的空气阻力和重力都在力的方向上发生了位移，即空气阻力和重力对雨点都做了功。B项错误，匀速圆周运动，亦称“匀速率圆周运动”，因为物体作圆周运动时速率不变，但速度方向随时发生变化。动能是指物体由于运动而具有的能量，它的大小定义为物体质量与速度平方乘积的二分之一，即。对于匀速圆周运动的物体，质量m和速率v不变，动能也不变。C项正确，在只有重力或弹力做功的物体系统内(或者不受其他外力的作用下），物体系统的动能和势能（包括重力势能和弹性势能）发生相互转化，但机械能的总能量保持不变。这个规律叫做机械能守恒定律。物体在只受重力作用下从相对静止开始下落的运动叫做自由落体运动。对于自由落体过程中的物体，符合机械能守恒定律，在下落过程中，重力势能转化为动能，但机械能总量保持不变。D项错误，势能是指物体（或系统）由于位置或位形而具有的能。功等于力与物体在力的方向上通过距离的乘积。功的正负表示是动力对物体做功还是阻力对物体做功，或者说是表示力对物体做了功还是物体克服这个力做了功。对于向上飞的石子，受到向下的重力，需要克服重力，即重力做负功。同时，石子的动能转化为重力势能，动能减小，势能增加。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-113", "q": "可再生能源是指不会随它本身的转化或人类的利用而越来越少的能源。下列属于可再生能源的是（）。①风能②天然气③潮汐能④太阳能⑤核燃料", "options": ["①②③", "①③④", "②④⑤", "③④⑤"], "a": 1, "e": ".【B】本题考查科技常识。可再生能源是指不会随它本身的转化或人类的利用而越来越少的能源。不可再生能源是指在自然界经过亿万年形成，短期内无法恢复，且随着大规模开发利用，储量越来越少，最终会枯竭的能源。①风能，是指地球表面大量空气流动所产生的动能。由于地面各处受太阳辐照后气温变化不同和空气中水蒸气的含量不同，因而引起各地气压的差异，在水平方向高压空气向低压地区流动，即形成风。风能不会因为人们的利用而越来越少，因此属于可再生能源。②天然气，是指天然蕴藏于地层中的烃类和非烃类气体的混合物。天然气主要存在于油田以及天然气田，也有少量出于煤层，它释放能量时自身会转化成二氧化碳和水，会随着人们的使用越来越少，因此属于不可再生能源。③潮汐能，是从海水面昼夜间的涨落中获得的能量。它与天体引力有关，地球－月亮－太阳系统的吸引力和热能是形成潮汐能的来源。这种能量是永恒的、无污染，因此属于可再生能源。④太阳能，一般指太阳光的辐射能量。在太阳内部进行的由“氢”聚变成“氦”的原子核反应，不停地释放出巨大的能量，并不断向宇宙空间辐射能量，这种能量就是太阳能。太阳内部的这种核聚变反应，可以维持几十亿至上百亿年的时间，不会因为人们的使用而减少，因此属于可再生能源。⑤核燃料，是指可在核反应堆中通过核裂变或核聚变产生实用核能的材料。当前核燃料主要为铀钍矿，本质是矿产资源，储量有限，而且会随着人们的使用越来越少，故核燃料属于不可再生能源。因此①③④属于可再生能源。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-114", "q": "关于物体的运动，下列说法正确的是：", "options": ["物体从高空中下落其速度变得越来越快是因其具有惯性", "跳伞运动员在匀速下降的过程中其机械能逐渐减小", "当物体受到力的作用后其运动速度必然发生改变", "足球在空中飞行时受到的空气阻力保持不变"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，物体受到地球引力从高空下落，在加速度的作用下，做加速运动。当物体运动方向与加速度方向一致时，运动速度会变得越来越快。物体从空中下落速度越来越快不是因为惯性。B项正确，机械能是动能与势能的总和。物体的质量与速度决定动能，跳伞运动员在匀速下降的过程中，质量不变，速度不变，故动能不变；物体的质量和高度决定重力势能，跳伞运动员在匀速下降的过程中，质量不变，高度下降，故重力势能逐渐减小。动能不变，重力势能逐渐减小，因此机械能逐渐减小。C项错误，当物体受到的合外力为零时，将保持静止或匀速运动状态。因此当物体受到力的作用后，其运动速度不一定发生改变。D项错误，足球在空中飞行时，受到的空气阻力与运动速度成正比，速度越快，空气阻力越大。足球在空中飞行的速度受到重力的影响，不断变化，因此空气阻力也不断改变。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-115", "q": "下列与成语有关的描述错误的是：", "options": ["“叶落归根”是因为地球表面的物体会受到重力的作用", "“青出于蓝”描述的是传统植物染料的提取过程", "“囊萤映雪”中“囊萤”和“映雪”包含的光学原理相同", "“沙里淘金”中的“金”属于金属单质"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，物体由于地球的吸引而受到的力叫重力。重力的施力物体是地心，重力的方向总是竖直向下。叶落归根意思是树叶从树根发出，最终凋落后回到树根，是由于重力的作用。B项正确，“青出于蓝”中，青，即靛青；蓝，即蓼蓝之类可作染料的草。青是从蓝草里提炼出来的，但颜色比蓝更深。最初是比喻人通过学习可以提升自己，后多用来比喻学生超过老师或后人胜过前人。C项错误，“囊萤”出自典故“囊萤夜读”，是指车胤用白绢做成透光的袋子，装着萤火虫照亮书本在夜晚继续学习，萤火虫的发光原理是因为在其发光器的部位，存在着一种含磷的化学物质，称为萤光素；“映雪”出自典故“孙康映雪”，是指孙康利用半夜地上雪反射的月光读书，体现的光学原理是光的反射。故二者利用的光学原理不一致。D项正确，元素的存在形式由其化学性质决定，金的化学性质稳定，不与土壤中的水及氧气等物质发生反应，在自然界中以单质的形式存在。故“沙里淘金”中的“金”属于金属单质。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-116", "q": "电磁波包括无线电波、微波、红外线、可见光、紫外线等。下列关于电磁波的说法正确的是：", "options": ["红外线是电磁波粒子性的体现", "微波在真空中的传播速度小于可见光", "紫外线在遥控和热成像仪中普遍应用", "雷达可以通过无线电波的反射测距"], "a": 3, "e": ".【D】本题考查科技常识。A项错误，电磁波的波长越短，粒子性越强；波长越长，波动性越强。而红外线的波长较长，其更多体现的是波动性。B项错误，微波和可见光在真空中的传播速度是一样的，都是光速，速度为。C项错误，遥控和热成像仪应用的是红外线。红外遥控具有抗干扰、电路简单、容易编码和解码、功耗小、成本低的优点，因此应用广泛。自然界中一切物体都可以辐射红外线，热成像仪利用这个原理，将物体辐射出的红外线的功率信号转换为电信号，经过处理，从而得到物体的热像图。D项正确，“雷达”一词是音译，原意为“无线电探测和测距”，其实际含义是利用目标对电磁波的反射现象来发现目标并测定其位置。因此雷达可以通过无线电波的反射测距。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-117", "q": "下列关于微波的说法正确的是：", "options": ["微波的频率比一般无线电波的频率低", "含水量多少对微波加热效果没有影响", "微波会被玻璃、塑料和瓷器等物体反射", "微波通信容量大、质量好、传输距离远"], "a": 3, "e": ".【D】A项错误，微波是指频率为300MHz~300GHz的电磁波。微波频率比一般的无线电波频率高，通常也称为“超高频电磁波”。B项错误，水分子属极性分子，介电常数较大，其介质损耗因数也很大，对微波具有强吸收能力。C项错误，对于玻璃、塑料和瓷器，微波几乎是穿透而不被吸收。D项正确，由于微波频率很高，所以在不大的相对带宽下，其可用的频带很宽，可达数百甚至上千兆赫兹，这是低频无线电波无法比拟的。这意味着微波的信息容量大，所以现代多路通信系统，包括卫星通信系统，几乎都是在微波波段内工作的。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-118", "q": "已知物体表面颜色越浅，反射热辐射的能力越强，进行热辐射的能力越差；物体表面颜色越深，反射热辐射的能力越差，进行热辐射的能力越强。据此，下列关于石油液化气罐和电力变压器表面颜色的判断，说法正确的是。", "options": ["均应漆成银白色", "均应漆成灰黑色", "前者漆成灰黑色，后者漆成银白色", "前者漆成银白色，后者漆成灰黑色"], "a": 3, "e": ".【D】本题考查科技常识。液化气罐里面装有的液化气属于易燃易爆液体，因此要保持低温。但其本身不产生热，其温度升高主要是因为吸收来自环境中通过热辐射传递的热量，涂成银白色这种浅色，其外表面反射热辐射的能力就强，可以减少从外界吸收的热辐射，从而保持罐体温度较低，保证安全性。正常运行中的电力变压器，会有极少部分的电能转化为内能，导致其温度升高，当变压器的温度比环境温度高时，将其漆成颜色很深的灰黑色，有利于将热量通过热辐射的方式传递到环境中，从而避免自身温度升得过高。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-119", "q": "将1000 毫升水和1000 毫升酒精混合成溶液，下列关于该溶液说法正确的是：①质量小于2000 克②质量等于2000 克③质量大于2000 克④体积大于2000 毫升⑤体积等于2000 毫升⑥体积小于2000 毫升", "options": ["①⑥", "②⑤", "③④", "①⑤"], "a": 0, "e": ".【A】本题考查科技常识。①正确、②③错误，水的密度为1克每毫升（1/），故1000毫升的水质量为1000克；酒精的密度比水小，因此", "tag": "科技常识"},
{"id": "tech-120", "q": "在众多色彩中，人们往往对红色“情有独钟”，常采用红灯做指示，比如指挥交通的红灯，汽车尾部的红灯，公共场所安全门的红灯。这是因为，红色光在可见光中（）。", "options": ["波长最长，且不容易被散射", "波长最短，且不容易被散射", "波长最长，且容易被散射", "波长最短，且容易被散射"], "a": 0, "e": ".【A】红色，可见光谱中长波末端的颜色，波长大约为620-760纳米，类似新鲜血液的颜色，是三原色和心理原色之一。在所有的可见光中，红光的波长是最长的，因此红光的穿透力最强。大气对光的散射有一个特点：波长较短的光容易被散射，波长较长的光不容易被散射；因此红光不易被散射，它可以传得较远。所以，汽车尾灯和交通紧急提示灯都用红光，A项当选，其他选项说法本身错误。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-121", "q": "关于照明用品，下列说法错误的是：", "options": ["手术室里的无影灯利用了光沿直线传播的原理", "手电筒用凹面镜作反射面是为了增强照明效果", "声控灯利用麦克风接收声音信号来实现灯的开启", "家用台灯正常工作时流过灯丝的电流约为2 安培"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，由于光是沿直线传播的，所以当发光体（非点光源）所发出光线被非透明物体阻挡后，会在屏幕（或其他物体）上形成影子，该影子由两部分构成，其中影子中部特别黑暗的部分叫本影，四周灰暗的部分叫半影。发光物体的面积越大，本影就越小。手术中用到的无影灯就是根据这个原理制成的，无影灯是将若干个发光强度很大的灯在灯盘上排成球冠状形，形成的一个区域较大的光源，光从不同角度把光线照到手术台上，这样就能消除施手术者的头、手和器械均可能对手术部位造成的干扰阴影。B项正确，凹面镜是球面镜的一种，反射面凹进去，能将平行的光反射后聚在镜面前的一点上，这点叫焦点。如果光源在焦点上，所发出的光经反射后就形成平行的光束。手电筒的光源就在焦点上，这样就使发出的光线经凹面镜反射后成为平行于主轴的平行光，从而增强了照明效果。C项正确，声控灯是一种声控电子照明装置，由音频放大器、选频电路、延时开启电路和可控硅电路组成。声控灯接收声音信号用的是小话筒（也叫麦克风），话筒将声音信号转换成电信号，经整流，再去触发可控硅，实现电灯的开启。经过约一分钟的延时后，再去掉触发信号，可控硅就自动关断了，灯也就熄灭了。D项错误，台灯是人们生活中用来照明的一种家用电器，台灯的光亮照射范围相对比较小和集中，作用局限在台灯周围，便于阅读、学习、工作、节省能源。所以家用台灯的功率不会很高，一般都在几瓦到一百瓦之间。按照选项给出的2A电流，根据（家庭电压为220V），换算出的功率是440W，这已经相当高了，不仅不利于保护眼睛，更与设计台灯的初衷相违背，所以家庭台灯正常工作时流过灯丝的电流大约在0.2A到0.5A之间，不可能是2A。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-122", "q": "下列与电有关的说法正确的是：", "options": ["电风扇将电能全部转化为机械能", "保险丝串联接入才能起到保护电路的作用", "为城市输电的高压输电线电压为220 伏", "能使电笔发亮的插口连接的是零线"], "a": 1, "e": ".【B】电风扇在工作过程中，电能大部分转化为机械能，还有一部分电能转化为内能，A项错误；高压输电是为了减少电力的损耗而设计的，常见的最低高压输电也要35千伏起，题干中220伏是我们日常生活中常见的普通电压，注意单位中千伏和伏的区别，C项错误；能使电笔发亮的插口连接的是火线，不是零线，D项错误；保险丝的特性是有规定的熔化温度，当电路中的电流达到所上保险丝的规定值时，保险丝就会熔化，从而切断电路起到保护的作用，串联接入保险丝有助于保护电路，B项正确。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-123", "q": "两个完全一样的陶瓷杯中分别装有半杯沸腾的热茶和半杯冷牛奶，如果将它们混合在一起做一杯温度尽可能低的奶茶，下列方法效果最好的是（）。", "options": ["在热茶冷却2 分钟后，将牛奶倒入其中", "在冷牛奶倒入热茶后再冷却2 分钟", "在热茶冷却2 分钟后，将其倒入牛奶中", "在热茶倒入冷牛奶后，再冷却2 分钟"], "a": 2, "e": ".【C】本题考查科技常识。自然冷却一般不会是匀速降温，温度高时降温快，接近环境温度时，降温慢。故采用先冷却热茶的方法，排除B、D两项，由于在热茶倒入冷牛奶的过程中会不断向外界散热，而冷牛奶温度低于环境温度，故不会散热，所以在热茶冷却2分钟后，将其倒入牛奶中，可取得最低温度的奶茶。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-124", "q": "白纸、黑纸、镜子、红纸四种物体，吸收光的本领从强到弱依次是（）。", "options": ["白纸、黑纸、镜子、红纸", "黑纸、红纸、白纸、镜子", "镜子、白纸、红纸、黑纸", "镜子、黑纸、红纸、白纸"], "a": 1, "e": ".【B】本题考查科技常识。白色不透明物体能反射所有的色光，黑色不透明物体吸收所有的色光，彩色不透明物体只能反射和物体相同的色光，其他色光被物体吸收。因此黑纸吸收光的本领最强，之后依次是红纸、白纸。镜子是通过光的镜面反射来成虚像的，其界面光滑、反射率高，吸收光的本领最弱。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-125", "q": "光学树脂常用于制作镜片，它是一种有机材料，其分子间结构相对松弛，光线可通过率为。下列关于光学树脂镜片的表达错误的是。", "options": ["树脂镜片和普通玻璃镜片的透光率不相上下", "树脂镜片的抗撞击力比普通玻璃镜片更强", "和同样大小的普通玻璃镜片相比，树脂镜片要轻得多", "和普通玻璃镜片相比，树脂镜片更加耐磨"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，在可见光区，树脂镜片透光率接近玻璃，二者不相上下。B项正确，树脂镜片的抗冲击力强，不易破裂。万一镜片被击碎，不但碎片少，且较不尖锐，能使眼球及面部受伤的情形减至最低程度。C项正确，和同样大小的普通玻璃镜片相比，树脂镜片相当于玻璃镜片重量的二分之一至三分之一，要轻得多。D项错误，树脂镜片的缺点是容易擦伤，树脂镜片的耐刮性较玻璃镜片差，虽可经由表面硬化处理改善之，但效果有限。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-126", "q": "飞行器在速度接近音速时会有一股强大的阻力，使飞行器产生强烈的振荡，速度衰减。这一现象被称为音障。要突破音障，对超音速飞机的结构有一定要求，下列机翼的设计有利于突破音障的是：", "options": ["又薄又短", "又薄又长", "又厚又短", "又厚又长"], "a": 0, "e": ".【A】本题考查科技常识。飞机是靠机翼产生升力，而把飞机托上天空的，机翼越大，升力就越大。但是，从另一方面来看，机翼在飞行中也会产生阻力，机翼越厚越长，阻力也越大。在飞行速度比较低的时候，为了产生足够的升力，就要把机翼做得长一些，例如滑翔机的翅膀就特别长；当速度提高以后，特别是在超音速飞行的时候，如果机翼厚长，所产生的阻力就特别大，就很难突破音障。因此对于超音速飞机来说，把机翼设计得又短又薄才能有利于突破音障。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-127", "q": "西汉末巧工丁缓发明的“被中香炉”是世界上已知最早的常平支架，其构造精巧，使用时把燃烧的炭火放入香炉中心的火盆中，无论香炉如何滚动，香炉中心的火盆都能保持水平，炭火始终不会掉出来。下列装置的物理原理与之相同的是：", "options": ["指南针", "陀螺仪", "水平仪", "高度计"], "a": 1, "e": ".【B】本题考查科技常识。“被中香炉”是基于角动量守恒的力学原理，角动量守恒定律反映质点和质点系围绕一点或一轴运动的普遍规律；反映不受外力作用或所受诸外力对某定点（或定轴）的合力矩始终等于零的质点和质点系围绕该点（或轴）运动的普遍规律。A项错误，指南针是利用磁铁“同性相斥、异性相吸”的特性，与题干“被中香炉”原理不同。B项正确，陀螺仪是基于角动量守恒的理论设计出来的，主要是由一个位于轴心且可旋转的转子构成，一旦开始旋转，由于转子的角动量，陀螺仪有抗拒方向改变的趋向，与题干“被中香炉”原理相同。C项错误，水平仪的工作原理是重力的方向总是竖直向下，与题干“被中香炉”原理不同。D项错误，常见的高度计主要为气压高度计，利用气压差得出高度差，在3000m范围内，每升高12m，大气压减小1mmHg，与题干“被中香炉”原理不同。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-128", "q": "关于导体及其导电原理，下列说法错误的是：", "options": ["金属导电，是因为金属中有可以自由移动的电子", "人体导电，是因为人体内含有大量水分和矿物质", "石墨导电，是因为石墨中含有碳元素", "酸碱溶液导电，是因为溶液内含有自由离子"], "a": 2, "e": ".【C】A项，关于金属导体导电，经典导电理论认为，是由于金属导体内部存在大量的可以自由移动的自由电子，这些自由电子在电场力的作用下定向移动而形成电流，说法正确。B项，人体中的每个细胞全充满着水，溶解着各类电解质，像钠、钾、钙等。矿物质是人体内无机物的总称，其中包含钙、镁、钾、钠、磷、硫、氯等电解质元素。电解质溶解于人的体液中，便形成了带电的离子，这些离子在外电场的作用下，于体液内作定向移动，便形成了电流，人体同样就有了导电性，说法正确。C项，石墨中有大量的可流动的电子，电子的定向移动就是电流。石墨的原子结构中，每个碳原子用3个电子与周围的碳形成3个共价键，所以每个碳原子都剩余1个电子，这些电子能够自由移动，因此石墨能导电不是含有碳元素，而是因为有可以自由移动的电子，说法错误。D项，酸碱溶液导电是因为溶液内含有自由离子，说法正确。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-129", "q": "压强和温度会引起密度的变化。假定其他条件不变的情况下，下列关于压强和密度的说法中，错误的是", "options": ["氧气瓶中的氧气用掉一部分后，体积不变，密度变小", "给自行车胎打气，车胎体积不变，质量变大，密度变大", "通常情况下，水在0", "温度计内的水银随温度升高而密度减小，体积变大"], "a": 2, "e": ".【C】本题考查科技常识。密度（）是对特定体积内的质量（）的度量（），计算公式是物体的质量除以体积，即=/。A项正确，氧气瓶中的氧气是经压缩后保存的，在使用过程中，氧气被不断消耗，质量减小，而氧气瓶的体积不发生变化，即瓶内的氧气体积不变，故瓶内氧气的密度减小。B项正确，车胎在满气状态下，其体积已经达到最大，此时给车胎打气，车胎内气体质量不断增加，但由于外胎束缚，车胎体积已基本不再变化，故车胎内气体密度变大。C项错误，水在0是密度为0.99984g每立方厘米，水在4是密度为0.99997g每立方厘米，因此通常情况下，水在", "tag": "科技常识"},
{"id": "tech-130", "q": "“舞动青春翅膀，谱写七彩人生。”所谓的“七彩”原意指“红、橙、黄、绿、蓝、靛、紫”七种颜色。下列镜体在阳光照射下能呈现七色光的是：", "options": ["凸面镜", "凹面镜", "平面镜", "三棱镜"], "a": 3, "e": ".【D】D项正确：三棱镜是由透明材料作成的截面呈三角形的光学仪器，能够使复色光在通过棱镜时发生色散。太阳光是由各种单色光组成的复色光，通过三棱镜会将各单色光分开，分解为红、橙、黄、绿、蓝、靛、紫七种色光。A项错误：凸面镜具有发散作用，可以扩大视野，但并不能呈现七色光。B项错误：凹面镜具有聚光作用，太阳光通过凹面镜会聚焦产生强烈的光点，不会呈现七色光。C项错误：平面镜具有反射作用，太阳光照射在平面镜上，光的传播方向会发生改变，不会呈现七色光。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-131", "q": "耀斑是指太阳大气局部区域突发变亮的活动现象。专家认为耀斑不会直接影响人体，是因为：", "options": ["地球有磁场和大气层两层防护", "太阳耀斑不够强大影响不了人体", "地球距离太阳太遥远削弱了其影响", "人体自身具备抵御太阳耀斑辐射的能力"], "a": 0, "e": ".【A】本题主要考查物理常识。太阳耀斑是发生在太阳大气局部区域的一种最剧烈的爆发现象，在短时间内释放大量能量，引起局部区域瞬时加热，向外发射各种电磁辐射，并伴随粒子辐射突然增强，太阳耀斑对地球和人体的影响主要表现为其发射的高能带电离子流。A项正确，太阳耀斑是一种等离子体，有自己的磁场，会对地球磁场施加作用，但地球磁场能有效阻止太阳耀斑长驱直入。在地球磁场的反抗下，太阳耀斑携带的等离子流大部分会绕过地球磁场，继续向前运动。当太阳耀斑辐射来到地球附近时，也与大气分子发生剧烈碰撞，虽然破坏了地球电离层，但它基本抵消了耀斑射到地面的能力。因此太阳耀斑不会直接射到地球表面，危害人体。B项错误，耀斑的持续时间在几分钟到几十分钟内，在这短暂的时间里却能释放出焦耳的巨大能量，这大约相当于上百亿颗巨型氢弹同时爆炸释放的能量，或者相当于十万至百万次强大火山爆发释放的能量总和，可见其威力之大。C项错误，地球虽然离太阳遥远，但相对于太阳系空间而言，是离太阳第三近的行星，并且太阳耀斑的等离子流能量大，速度快，所携带的能量完全可以到达地球。D项错误，人体没有直接抵御太阳耀斑的能力，只是太阳耀斑所携带的等离子流几乎无法到达接触到人体。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-132", "q": "我国海洋综合科考船“海洋六号”从珠江口进入南海海域，执行大洋南极科考任务。下列关于科考船从珠江口进入南海，所受浮力情况说法正确的是：", "options": ["由于船始终浮在水面上，所以受到的浮力不变", "由于海水的密度更大，所以船在海洋里受到的浮力更大", "由于船排开海水的体积更小，所以在海洋里受到的浮力更小", "由于船排开江水的体积更大，所以在江水里受到的浮力更大"], "a": 0, "e": ".【A】本题考查浮力相关知识。浸在液体里的物体会受到液体竖直向上托的力，这就是浮力。物体受到的浮力等于物体下沉时排开液体的重力。当浮力等于物体自身的重力，且物体的平均密度小于液体的密度时，物体就可以漂浮在液体之上。A项正确：科考船不论是在江水中还是在海水中，都为漂浮状态，此时浮力始终等于重力，所以船受到的浮力是不变的。B项错误：船在漂浮状态下的浮力等于重力，与水的密度无关。C项错误：船从江水到海水中，受到的浮力始终等于重力，不会因为排开海水的体积变小而变小。D项错误：江水中的船所受到的浮力仍等于重力，不会因为排开江水的体积变化而变化。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-133", "q": "关于物理现象，下列说法错误的是：", "options": ["将充满空气的气球放气时，气球内的温度比外界高", "用易拉罐给收音机做一个密封壳，可以屏蔽无线电波", "用沾过洗洁精的抹布擦拭汽车玻璃，可以避免车窗产生水雾", "充满空气的黑色密封塑料袋在太阳底下暴晒，塑料袋会慢慢上升"], "a": 0, "e": ".【A】本题考查物理常识。A项错误，放气时，气球内部压强降低，气球内的气体会对外做功，气体内能转变为气球动能，使气体内能减少，同时又来不及从外界吸热，只能通过降低温度（减少内能）来实现对外做功。B项正确，无线电波是一种电场和磁场的波动，所以又叫电磁波。如果想屏蔽电磁波应该使用磁性材料，即只要使金属变成网罩在物体上就可以有效的屏蔽电磁波，题干指出是密封的金属壳，所以可以屏蔽无线电波。C项正确，车窗起雾的原因是车内外存在温差，而当车内温度高于车外温度时，就会形成雾气。洗洁精中含有的活性成分，能在玻璃表面形成一层膜，隔绝玻璃和水，可有效防止水蒸气在玻璃上凝结。D项正确，黑色可以吸收光线中所有的波段，不反射任何可见光，所以对热辐射的吸收能力强，导致塑料袋温度升高，空气受热膨胀，密度变小，所以会上升。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-134", "q": "下列古语与物理现象对应错误的是：", "options": ["磁石召铁，或引之也——磁现象", "马力即竭，辀（指车辕）犹能一取焉——惯性现象", "鉴洼，景一小而易倒，一大而正，说在中之外、内——凸面镜成像", "瓶存二窍，以水实之，倒泄；闭一则水不下，盖（气）不升则水不降——大气压力现象"], "a": 2, "e": ".【C】本题考查物理常识，主要考查生活中常见的物理现象对应的原理。C项错误：战国时期的《墨子经下》中记载：“鉴洼，景一小而易，一大而正。说在中之外、内。”意思是：凹面镜成像，一种情况是缩小而倒立，一种情况是放大而正立，这是由于物处于“中”的外、内的不同而造成的。“鉴洼”即凹面镜，“中”是指球面中心与焦点之间的区域。A项正确：战国时期秦国的《吕氏春秋》中记载：“磁石召铁，或引之也。”意思是：磁石吸引铁器，是有一种力在吸引它。这是物理上的磁现象。B项正确：春秋时期的《考工记》中记载：“马力既竭，辀犹能一取焉。”意思是：在马拉车时，马不走了，即马对车不施力了，车子还有前进的趋势。这是物理上的惯性现象，说明物体不受力了，却依然具有速度。D项正确：南北朝时期的《关尹子九药篇》中记载：“瓶存二窍，以水实之，倒泻；闭一则水不下，盖（气）不升则（水）不降。”意思是：有两个小孔的瓶子能倒出水，如果闭住一个小孔，另一个小孔外面的空气压力会比瓶里水的压力大，水就流不出来。这是物理上的大气压力现象，即虹吸原理。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-135", "q": "下列选项中，导热性最好的是，它比大多数气体的导热系数高出10 倍，在能源工业中是极好的传热导体。", "options": ["氢气", "氧气", "氮气", "氦气"], "a": 0, "e": ".【A】本题考查科技常识。导热系数是表征物质导热能力的物理量。表示材料在一维稳态传热情况下，面积为，厚度为的材料，当其两侧表面温度差为时，单位时间内由导热方式传递的热量，单位为瓦/米·度（W/(m·K)，此处为K可用代替）。下氢气导热系数约为0.17W/(m·K)，是导热性最好的气体，比大多数气体的导热系数高出10倍，因此在能源工业中，氢气是极好的传热导体。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-136", "q": "下列国际单位制对应不正确的是：", "options": ["功率—瓦特", "电流—伏特", "电阻—欧姆", "频率—赫兹"], "a": 1, "e": ".【B】A项正确，功率符号（P）单位名称（瓦特）简称“瓦”，符号是“W”；B项错误，电流符号（I）单位名称（安培）简称“安”，符号是“A”，这个单位是为了纪念法国物理学家安培在电学研究中的巨大贡献而命名；C项正确，电阻符号（R）单位名称（欧姆），符号是“Ω”；D项正确，交流电的频率是指它单位时间内周期性变化的次数，单位是赫兹（Hz）。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-137", "q": "在浮力应用的过程中，下列有关说法正确的是", "options": ["潜水艇——通过改变排水的多少来实现下沉和上浮", "热气球——在上升过程中球囊内的气体密度小于外界空气密度", "轮船——在风力更大的江面上吃水会变深", "密度计——测量不同密度的液体时所受到的浮力不同"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，潜水艇外形、体积固定，因此排水量一定，潜入海中所受海水浮力也一定，故只有改变自身重量才能控制下沉和浮起。下沉时潜水艇打开压舱入水口，海水进入潜艇内部的水舱，使艇重超过浮力而下沉；需浮起时潜艇应用内部贮备的压缩空气，将水舱内的海水排出艇外，此时，艇重小于浮力而向上浮起。B项正确，微观来讲，气体受热之后分子之间的距离变大，导致体积变大、密度变小。热气球就是利用这一原理，喷火装置启动后，将热气球气囊中的空气加热，空气受热膨胀，密度变小，热气球所受大气浮力为气囊所排开的空气重力，即，大于气囊内空气重力。随着加热的进行，气囊内部空气密度进一步减小，当大气浮力大于气囊内空气重力和热气球附属设备重力之和时，热气球便缓缓上升。C项错误，根据伯努利效应，流体的速度越大，压力越小，这时候整体的大气压力减小了，因此轮船会获得一个向上的升力，而自身重力不变的情况下，需要水的浮力会变小，吃水变浅。风力越大，吃水越浅。D项错误，密度计是根据阿基米德原理和物体浮在液面上平衡的条件制成的。它是一根密闭的玻璃管，上部粗细均匀，内壁贴有刻度纸，下部较粗，下端装有铅丸或水银，使玻璃管能竖直浮在液面上。测量液体密度时，密度计漂浮在液体中达到二力平衡，自身重力与所受浮力方向相反、大小相同，由于密度计自身重力始终不变，所以测量不同密度的液体时所受到的浮力也不变。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-138", "q": "关于“嫦娥三号”探测器在月球表面降落时没有使用降落伞的原因，下列表述描述正确的是（）。", "options": ["“嫦娥三号”质量太大，无法制作与其质量匹配的降落伞", "月球表面附近并没有大气，使用降落伞也起不到减速作用", "在降落后，降落伞极可能将探测器的视线遮住，从而引发重大安全事故", "探测器在距离月球较远已开始减速，期间的时间足够探测器将速度降为零"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，降落伞可以根据物体不同质量制作成相应大小，因此可以制作与其质量匹配的降落伞，不对。B项正确，月球表面是真空状态，没有大气，降落伞是利用空气阻力原理，展开后可增大迎风面积产生气动力作用，使与其相连的物体减速。月球没有大气，故降落伞无法使用。C项错误，航空器降落伞采用一套非常精密的控制系统控制开伞的时间以及步骤，探测器的视线即使被遮住也不会影响降落过程。D项错误，月球表面无大气，因此，嫦娥三号无法利用气动减速的方法着陆，只能靠自身推进系统减小约1.7公里每秒的速度，在此过程中探测器还要进行姿态的精确调整，不断减速以便在预定区域安全着陆。为了保证着陆过程可控，研制团队经过反复论证，提出“变推力推进系统”的设计方案，研制出推力可调的7500N变推力发动机，经过多次点火试车和相关试验验证，破解着陆减速的难题。选项说明的是探测器减速的方法，而非不使用降落伞的原因。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-139", "q": "关于物理学原理在实际生活中的运用，以下说法错误的是：", "options": ["气压越高，沸点越低——高压锅能更快地煮好食物", "冰刀作用于冰面的压力促使冰面融化——溜冰运动员能快速在冰面移动", "凸面镜的视野比平面镜广阔——汽车前方两侧的后视镜是凸面镜", "冷空气下沉——空调安装在房间上方"], "a": 0, "e": ".【A】A项错误：沸腾就是液体分子离开液体变成气体分子的剧烈过程，液体表面的气压越高，液体分子离开液面变成气体更加困难，离开液面必须获得更高的能量，所以需要更高的温度，即沸点会有所升高。高压锅正是运用气压越高，沸点越高这一原理使得食物在高温条件下更容易煮熟。B、C、D三项均正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-140", "q": "通常情况下，使用高压锅可以大大缩短食物的烹煮时间，节约能源。下列对其所用物理原理的解释正确的是：", "options": ["锅内蒸汽的压强增大，导致水的沸点降低", "锅内水的沸点降低，导致蒸汽的压强增大", "锅内蒸汽的压强增大，导致水的沸点升高", "锅内水的沸点升高，导致蒸汽的压强增大"], "a": 2, "e": ".【C】本题考查物理常识。水的沸点受压强影响，当水所受的压强增大时，沸点升高。在标准大气压强下水的沸点为100℃，高压锅的原理相当于把水紧密地封闭起来，水受热后产生的水蒸气不能扩散到空气中，只能保留在高压锅内，于是高压锅内部形成高温高压的环境。由于锅内水蒸汽的压强增大，导致水的沸点提高，这样就可以在较短时间内将食物煮熟。故A、B、D三项错误。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-141", "q": "下列说法正确的是：", "options": ["雨后想看到彩虹必须面对太阳", "光的三原色和颜料的三原色都是红绿蓝", "光在空气中的传播速度慢于在水中的传播速度", "警告类标识一般用红色是因为红色波长最长、传播最远"], "a": 3, "e": ".【D】A项错误，彩虹又称天虹，简称虹，是气象中的一种光学现象。下雨之后，必须背对阳光才能看见彩虹。B项错误，光的三原色是红绿蓝；颜料的三原色是品红、黄、青。C项错误，空气相对于水是光疏介质，光在空气中折射率比水小。折射率是光在真空中速度与光在该介质中速度的比值，折射率越大，光的传播速度越小。因此光在空气中传播速度更快。D项正确，警告类标识一般用红色是因为红色波长最长、传播最远。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-142", "q": "彩虹是太阳光照射到空气中的水滴时，光线被折射及反射，在天空中形成的拱形七彩光谱。下列关于彩虹的说法正确的是：", "options": ["冬天不易出现彩虹", "水滴越大，彩虹越不明显", "彩虹上的蓝光总在红光上方", "彩虹的明显程度与阳光强度无关"], "a": 0, "e": ".【A】本题主要考查物理常识，涉及到彩虹相关知识。A项正确，一般冬天的气温较低，在空中不容易存在小水滴，下阵雨的机会也少，所以冬天一般不容易有彩虹出现。B项错误，在阳光强度一定的条件下，彩虹的明显程度，取决于空气中小水滴的大小。小水滴体积越大，形成的彩虹越鲜亮，小水滴体积越小，形成的彩虹就不明显。C项错误，水对阳光有色散作用，不同波长的光的折射率有所不同。因为蓝光的折射率比红光大，致使蓝光的偏折程度大。所以红光在最上方，其它颜色在下。D项错误，彩虹的明显与否，一主要取决于在各色光的宽度上，宽度大就明显，宽度小则各色光重叠不明显；二与太阳光的强度有一定关系，因为太阳光强可以影响各色光的亮度。因此彩虹明显度与太阳光强有关。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-143", "q": "下列说法中，正确的一项是（）。", "options": ["牛顿被称为“近代科学之父”", "等量的", "爱因斯坦是现代量子物理学的奠基人", "雨后彩虹是光的反射与折射共同作用产生的现象"], "a": 3, "e": ".【D】本题考查物理常识。A项错误，伽利略是意大利的物理学家，是科学革命的先驱，他融会贯通了当时的数学、物理学和天文学，开创了以实验事实为根据并具有严密逻辑体系的近代科学，被称为“近代科学之父”。牛顿是英国著名的物理学家，提出了牛顿三大运动定律。故“近代科学之父”是伽利略，而不是牛顿。B项错误，等量的水蒸气与水都是100℃，它们接触到皮肤都要向人体放热。而100℃水蒸气向人体放热时会发生液化，液化时会放出大量的热。因此等量的100℃的水蒸气对人体的烫伤比100℃的水更为严重。C项错误，1900年，德国物理学家普朗克研究发现，认为电磁波的发射和吸收不是连续的，而是一份一份进行的，这样的一份能量叫做能量子。普朗克把物理学带进了量子世界，受到普朗克的启发，爱因斯坦于1905年提出，在空间传播的光也不是连续的，而是一份一份的，每一份叫做一个光量子。所以现代量子物理学的开创者和奠基人是德国物理学家马克斯普朗克，而不是爱因斯坦。D项正确，彩虹是气象中的一种光学现象。雨后当太阳光照射到空气中的水滴时，光线被折射及反射，在天空上形成七彩光谱。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-144", "q": "下列说法中正确的一项是：", "options": ["日光灯通过电流加热钨丝产生热量，继而产生光辐射来发光", "数码相机利用电子传感器技术，与普通相机记录图像的原理基本相同", "等离子电视显示器采用荧光粉显示屏幕，因而亮度高于液晶电视", "激光打印机是把射到感光器的图像传印到打印板（或复印纸）上，其原理与复印机不同"], "a": 2, "e": ".【C】A项错误，日光灯通电后，管内电极通过汞蒸气放电而产生紫外线，激发荧光物质发出可见光；B项错误，数码相机是一种利用电子传感器把光学影像转换成电子数据的照相机，与普通照相机在胶卷上靠溴化银的化学变化来记录图像的原理不同；C项正确，等离子电视，它是在两张超薄的玻璃板之间注入混合气体，并施加电压利用荧光粉发光成像的设备。与液晶电视相比，具有亮度高，对比度高，可视角度大，颜色鲜艳和接口丰富等特点；D项错误，复印机和激光打印机的大致原理基本是相同的，复印机比打印机多了一个曝光的步骤而已。二者都是将接收的光信号经F-theta镜头实现对感光鼓的横向扫描且感光鼓转动实现纵向扫描，从而在感光鼓上留下要打印或复印的文字图像的潜影，再经过后面相同的步骤将其在复印纸上定影。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-145", "q": "下列有关光的原理表达正确的是：", "options": ["星星闪烁——光的衍射", "下雨过后夜间亮者为水，暗者为陆——光的反射", "电影银幕——光的直线传播", "通过狭缝观察发光的日光灯时能看见彩色条纹——光的漫反射"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，光从一种介质斜射入另一种介质时，传播方向发生改变，从而使光线在不同介质的交界处发生偏折，这种现象叫做光的折射。地球的大气层由于分布不均匀，犹如层层透镜，射入其中的光线便会发生多次折射层层弯折。遥远的星光要到达我们的视野同样需要穿过大气层的多次折射和弯折。而且由于大气层（尤其是其中的对流层）非常不稳定，一直在无规则的湍动，经过弯折的星光会随之改变方向，因此我们观望星空时，看到的星光是闪烁的。所以星星闪烁是因为光的折射，不是光的衍射。B项正确，下雨过后，水面发生镜面反射，地面发生的是漫反射。夜间，当人迎着月光走路时，水面反射的较强月光刚好能进入人眼，而地面漫反射的月光射向各个方向，只有较少的一部分能进入人眼。因此，迎着月光走路时，较亮处是水，较暗处为陆地。C项错误，电影幕布是影院的硬件设施，投影机将映像投放到幕布上，观众直接从幕布上观看。为了使坐在不同位置上的人都能看到，电影银幕往往要用粗糙的白布制作。一方面，白色能反射所有颜色的光，使所看到的像更加逼真；另一方面，白布表面粗糙（不光滑）能产生漫反射，使光线向各个方向传播。因此应用的原理是光的漫反射，而不是光沿直线传播。D项错误，两列或几列光波在空间相遇时相互叠加，在某些区域始终加强，在另一些区域则始终削弱，形成稳定的强弱分布的现象，这就是光的干涉现象，证实了光具有波动性。“漫反射”是指当一束平行的入射光线射到粗糙的表面时，表面会把光线向着四面八方反射，所以入射线虽然互相平行，由于各点的法线方向不一致，造成反射光线向不同的方向无规则地反射的现象。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-146", "q": "下列关于声音的说法错误的是：", "options": ["声音是由物体振动产生的声波", "声音在水中传播的速度比在空气中要快", "用空心砖砌墙降噪是在声源处减弱噪声", "接听电话主要靠音色来分辨熟人的声音"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，声音是由物体振动产生的声波，是通过介质（空气或固体、液体）传播并能被人或动物听觉器官所感知的波动现象，它以声波的形式向周围传播。声音的特征用声音的音调、响度、音色来表示。我们能听出在身后叫自己的是谁是根据声音的音色分辨出来的。B项正确，声音在水（常温）中的传播速度为1500（m/s）。声音在空气中的传播速度为（）:331（m/s）；（）:340（m/s）；（）:346（m/s）。据此可知，声音在水中的传播速度比在空气中要快。C项错误，用空心砖砌墙是在传播过程中减弱噪声，而非在声源处。在空心砖中有相当一部分声音是曲线传播，这样就使声音的传播路线长短不齐，加上空心砖中还有空气的传播速度，也就是这些速度的不同，会使声音互相之间产生干涉，这种干涉就极大的减弱声音的传播。尤其噪声都是一些尖脉冲，互相干扰更为明显。D项正确，声音的三个特性是音调、响度和音色。音色是发声体的声音品质，由发声体本身的特征决定，是区别声音的重要标志。接听电话时，很容易分辨出熟人的声音，这主要是根据声音的音色来判断的。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-147", "q": "下列自然现象，解释正确的是：", "options": ["冬天热汤会冒白气，是汽化现象", "樟脑丸会越来越小，是蒸发现象", "洗澡时卫生间的镜子有一层小水珠，是液化现象", "报废的电灯泡取下发现变黑了，是腐蚀引起的"], "a": 2, "e": ".【C】本题主要考查物理常识。A项错误，“白气”是液体的小水滴，该项中的“白气”是水蒸气遇冷液化而成的小水滴，这是一个液化过程，而不属于汽化现象。汽化是物质从液态变为气态的过程。B项错误，樟脑丸越来越小是固态直接变成气态，属于升华现象，这一过程是要吸收热量的。蒸发是物质从液态转化为气态的过程。C项正确，在卫生间洗澡后，镜子上有小水珠，是因为卫生间内的水蒸气遇冷液化成小水珠附着在镜面上。液化是物质由气态转变为液态的过程。D项错误，报废的电灯泡会变黑，是因为钨丝受热而升华，然后钨蒸气又在灯泡壁上凝华的缘故。升华是物质由固态直接变成气态的现象，凝华是物质由气态直接变成固态的现象。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-148", "q": "下列哪一种现象的物理原理不同于其他三项：", "options": ["水中的手指变粗", "池水看起来比实际的浅", "只有瞄准鱼的下方才能叉到鱼", "小明在宁静的湖边看见“云在水中飘”"], "a": 3, "e": ".【D】本题考查科技常识。光从一种透明介质斜射入另一种透明介质时，传播方向一般会发生变化，这种现象叫光的折射。A项正确，盛水的水杯中间厚、边缘薄，就如同一个凸透镜（放大镜），对手指有放大作用，使得水中部分手指看上去变粗了。凸透镜利用的是光的折射原理。B、C项正确，从池底或鱼身上（S点）反射的光线由水中进入空气时，在水面上发生了折射，由于水的折射率大于空气，使得折射角大于入射角，折射光线进入人眼，人眼会逆着折射光线的方向看去，就会觉得池底或鱼的位置偏高（如图S’点），看上去池子变浅了，叉鱼时也须瞄准鱼的下方才能叉到鱼。C、D项错误，宁静的湖水有平面镜的效果，能将天空中云朵反射进小明的眼中，体现的是光的反射原理。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-149", "q": "下列关于自然现象的解释，正确的一项是：", "options": ["冬天户外用嘴呼气冒“白气”，是汽化现象", "白炽灯泡用久后玻璃泡壁变黑，是凝华现象", "利用干冰进行人工增雨，干冰发生的变化属于液化现象", "冬天房顶上的积雪虽没有融化，却逐渐减少，是蒸发现象"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，人呼出的气体中含有水蒸气，刚呼出时温度较高（36.5摄氏度），为气态；而冬天温度较低，呼出的水蒸气会大量凝结为小液滴且浓度较高，所以会看见白气，此为液化现象，而不是汽化现象。汽化是指物质从液态变为气态的相变过程。B项正确，凝华是物质直接从气态变为固态的现象，凝华过程物质要放热。用久的白炽灯泡会从透明变成黑色，是在电灯泡工作时发热，而钨丝受热升华形成的钨蒸气又在灯光泡壁上遇冷凝华成极薄的一层固态钨。C项错误，液化是物质由气态转变为液态的过程，会对外放热。干冰是由二氧化碳凝华而成的，当它投放到云层中时就会吸热升华。从而使云层迅速降温，让云层中的一些水蒸气和小水滴凝成小冰晶或大的水滴，达到人工降雨的效果。因此，干冰发生的变化属于升华现象，而不是液化现象。D项错误，蒸发是物质从液态转化为气态的相变过程，而雪融化属于固态转变为液态，因此D项中的现象不是蒸发现象。此处应主要为固态直接变为气态，是升华现象。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-150", "q": "半导体在我们的日常生活中有着广泛应用，下列关于半导体的说法正确的是：", "options": ["麦克斯韦首次发现了半导体现象", "所有半导体材料都属于金属化合物", "温度升高，半导体的电阻会随之变高", "LED 灯利用半导体将电能转化为光能"], "a": 3, "e": ".【D】本题考查科技常识。半导体是指常温下导电性能介于导体和绝缘体之间的物体。A项错误，法拉第最先发现硫化银的电阻随着温度的变化情况不同于一般金属。一般情况下，金属的电阻随温度升高而增加，但法拉第发现硫化银材料的电阻是随着温度的上升而降低，这是半导体现象的首次发现。麦克斯韦，著名的物理学家，预言了电磁波的存在。B项错误，半导体材料很多，按化学成分可分为元素半导体和化合物半导体两大类。锗和硅是最常用的元素半导体。C项错误，一般情况下，金属的电阻随温度升高而增加，但是温度升高，半导体的电阻会随之降低，导电率升高。D项正确，LED灯即半导体发光二极管，是一种能够将电能转化为可见光的固态的半导体器件，它可以直接把电能转化为光能。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-151", "q": "关于电学常识，下列说法错误的是：", "options": ["两个绝缘体摩擦可能产生静电", "不能随意使用铜丝、铁丝代替保险丝", "磁悬浮列车利用了电流的磁效应原理", "测电笔在正确操作时，检测零线氖管会发光"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，摩擦起电本质是电子的转移。不同绝缘体吸引电子的能力有强弱之分，摩擦时吸引电子能力弱的物质中的电子转移到吸引电子能力强的物质上，由于电子带负电，故后者物质带负电，前者带正电。所以两个绝缘体摩擦可能产生静电。B项正确，保险丝一般用电阻率较大、熔点较低的铅锑合金制成。铜丝或铁丝的电阻小、熔点高，在电流过大时，产生的热量不容易达到熔点，因此不会熔断，起不到保险的作用。故不能随意用铜丝、铁丝代替保险丝。C项正确，磁悬浮列车主要由悬浮系统、推进系统和导向系统三大部分组成。磁悬浮列车的运行涉及到三个物理原理：第一个是当靠近金属的磁场改变，金属上的电子会移动，并产生电流。第二个是电流的磁效应，当电流在电线或一块金属中流动时，会产生磁场，通电的线圈就成了一块磁铁。磁浮的第三个原理是磁铁间会彼此作用，同极性相斥，异极性相吸。D项错误，测电笔是用来判别火线与零线的工具，它由笔尖金属体、电阻、氖管、弹簧和笔尾金属体等组成。使用时，将笔尖接触火线，手接触笔尾的金属体（注意：千万不能用手接触笔尖金属体），氖管便发红光；若笔尖接触的是零线，氖管便不发光。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-152", "q": "荷花虽生长于池塘的污泥中，但荷叶却出污泥而不染，其主要原因是：", "options": ["荷叶含有大量的叶绿素，能与太阳光发生光合作用，产生自清洁", "荷叶表面光滑，具有非常强的光洁度，污泥很难在它的表面吸附", "荷叶含有疏水的纳米级蜡质，雨露落在上面会形成水珠清洁叶面", "荷花枝干细长，水珠落在荷叶上，容易造成荷叶晃动，甩出污泥"], "a": 2, "e": ".【C】本题考查科技常识。荷叶之所以能出污泥而不染是由荷叶叶面上存在着复杂的多重纳米和微米级的超微结构决定的：在超高分辨率显微镜下可以清晰看到，荷叶表面上有许多微小的乳突，它上面长满绒毛，在紧贴叶面处形成一层极薄的只有纳米量级厚的空气层。这使得在尺寸上远大于这种结构的灰尘、雨水等降落在叶面上后，隔着一层极薄的空气，从而雨水会自动聚集成水珠，而水珠的滚动会把落在叶面上的尘土污泥吸附掉滚出叶面，使叶面始终保持干净，这就是著名的“荷叶自洁效应”。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-153", "q": "下列现象的物理解释错误的是：", "options": ["高压锅烹煮食物——升高水的沸点", "露珠呈球状——液体表面张力", "铁轨铺在枕木上——减少压强", "大银幕观影——光的漫折射"], "a": 3, "e": ".【D】本题主要考查物理常识。A项正确，水的沸点受压强影响，压强越高，沸点越高。高压锅烹煮食物增大了锅内的气压，提高了水的沸点，要煮的食物温度升高，从而使食物熟透。B项正确，物质由分子组成，分子之间有间隙，由于分子在不停地做无规则运动，分子间存在相互作用的引力和斥力。在液体表面，分子间的作用力表现为相互吸引，由此表现为液体的表面张力。表面张力促使露珠以最小的表面积的状态存在，而体积相等的物体中，只有球体的表面积最小，所以露珠总是呈球状的。C项正确，把铁轨铺在枕木上，是为了在压力一定的情况下，增大铁轨与地面的接触面积，从而减小火车对地面的压强。D项错误，漫反射是指投射在粗糙表面上的光向各个方向反射的现象。电影院里人能在不同的座位上看到银幕上的画面，是因为屏幕上的光源在银幕上形成了漫反射，而不是光的漫折射。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-154", "q": "户外运动可以促进骨骼的健康，这是因为太阳光中的某种频率的电磁波可以促成维生素D 的活化，促进身体吸收食物中钙和磷，从而促进骨骼的生长。这种电磁波是：", "options": ["紫外线", "", "无线电波", "红外线"], "a": 0, "e": ".【A】本题主要考查物理常识。A项正确，紫外线是电磁波谱中波长从5nm～370nm之间的电磁波。太阳光里有紫外线，人体接受适量的紫外线照射，能促进钙的吸收，促进骨骼生长，改善身体健康。B项错误，射线又称伦琴射线，能够穿透物质，可以用来检查人体内部器官。在工业上，利用射线检查金属零件内部的缺陷。γ射线是波长最短的电磁辐射，能够破坏生命物质。可以摧毁病变的细胞，用来治疗某些癌症。C项错误，波长大于1mm的电磁波是无线电波。无线电波用于通信、广播及其他信号传输。D项错误，红外线波长比无线电波短，比可见光长，所有物体都发射红外线。利用此现象制造的红外探测器，能够在较冷的背景上探测出较热物体的红外辐射，这是夜视仪器和红外摄影的基础。此外，红外线在军事上的应用也十分重要。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-155", "q": "北极气候恶劣，冰雪无边。室外最低气温能达到零下59 摄氏度，但冰屋却给那里的居民提供了温暖的住所。下列关于冰屋的说法，不正确的是：", "options": ["冰屋能够保留其内部空间的热量，因为冰墙是热的不良导体", "为了避免冷空气的进入，冰屋顶部应该被设计成密封圆拱形", "冰屋一半陷入地下，通过冷暖空气对流来保证冰屋内部气温", "冰屋的内壁较为光亮，可以通过辐射防止内部热量向外扩散"], "a": 1, "e": ".【B】本题考查的是科技常识的相关知识。A项正确，因为冰是热的不良导体，能很好地隔热，屋里的热量几乎不能通过冰墙传导到屋外，所以冰屋能够保留其内部热量。B项错误，冰屋顶部设计为圆拱形，是因为拱形受压时会把力传给相邻的部分，拱形可以向下向外分散压力，所以拱形所能承受的力量更重。所以冰屋屋顶设计成密封圆拱形，是为了承受更大的压力。C项正确，冰屋在建造过程中会在半球形屋顶罩住的土地上挖掘一个深坑，根据热空气上升冷空气下降，冷空气会降到冰坑里，热空气升到人所在的位置，因此保证内部温度。D项正确，冰屋内壁光亮的冰壳能够把辐射出去的热能反射回来，有效阻止屋内的热量向外扩散，从而保证室内温度的均衡。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-156", "q": "下列现象的物理解释错误的是：", "options": ["露珠呈球状——液体表面张力", "铁轨铺在枕木上——减少压强", "道路转弯镜——凸透镜对光发散", "微波炉烤面包——涡流感应加热"], "a": 2, "e": ".【C】本题考查科技常识。该真题命制不严谨。A项正确，物质由分子组成，分子之间有间隙，由于分子在不停地做无规则运动，分子间存在相互作用的引力和斥力。在液体表面，分子间的作用力表现为相互吸引，由此表现为液体的表面张力。表面张力促使露珠以最小的表面积的状态存在，而体积相等的物体中，只有球体的表面积最小，所以露珠总是呈球状的。B项正确，把铁轨铺在枕木上，是为了在压力一定的情况下，增大铁轨与地面的接触面积，从而减小火车对地面的压强。C项错误，道路转弯镜利用的是凸面镜，可以扩大司机视野，及早发现弯道对面车辆，以减少交通事故的发生。D项存在问题，微波炉加热食物主要利用微波。此外部分微波炉烧烤功能主要是利用烧烤组件来完成的，用电热丝发热来工作。一般认为利用涡流感应加热的是电磁炉。本题命制不严谨，C项和D项均存在问题，C项相关知识点在往年考试中出现较多，故小粉笔认为该真题判卷时以C项为标准答案可能性更大。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-157", "q": "下列选项中的现象包含了相同物理原理的是：", "options": ["搓手取暖：钻木采火", "摇扇纳凉：冰镇降温", "气球升空：桂花飘香", "水往低流：唱响全场"], "a": 0, "e": ".【A】A项正确，冬天搓手取暖和钻木采火都是利用摩擦，使得机械能转换为内能。B项错误，夏天摇扇体现的是空气的流动，空气的流动使人体表面的汗液蒸发加快，由于蒸发吸热，所以人感到凉快；冰镇降温体现的是熔化原理，因为冰在空气中会熔化，而熔化需要吸热，吸收人体的热量，让病人降温。C项错误，气球升空体现的是浮力原理，桂花飘香体现的是分子在不停地做无规则运动。D项错误，水受到地球磁场引力的作用，引力的方向是竖直向下的；唱响全场体现的是声音通过介质不断传播。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-158", "q": "以下现象，与液体表面张力无关的是：", "options": ["雨水落到荷叶上形成水珠", "某些小型昆虫在水上行走", "回形针能够漂浮在水面上", "船能够在水面上航行"], "a": 3, "e": ".【D】本题主要考查物理常识。液体表面张力，是指作用于液体表面，使液体表面积缩小的力。其产生的原因是：液体跟气体接触的表面存在一个薄层，叫做表面层，表面层里的分子比液体内部稀疏，分子间的距离比液体内部大一些，分子间的相互作用表现为引力。A项正确，由于荷叶具有疏水、不吸水的表面，落在叶面上的雨水不会浸润展开，而会因表面张力的作用形成水珠。B项正确，昆虫一般长着细长的脚，像一个保持平衡的支架，来帮助昆虫利用水的表面张力（其作用力小于水的张力），从而在水面上行走自如。C项正确，回形针在水面的有效张力范围内，用水撑起一张膜，从而支撑和分摊了回形针在水面的重量，使其不至于下沉。D项错误，船能够漂浮在水面上，跟它排开水的体积有关。物体浮力的大小等于该物体下沉时排开的液体的重力，物体排开的水越多，它所受的浮力也就越大，当船浮在水面上时，船所受到的浮力等于船自身的重力，与表面张力无关。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-159", "q": "下列说法与其所涉及的物理原理对应不正确的是", "options": ["长啸一声，山鸣谷应——声波的衍射", "小小秤砣压千斤——杠杆原理", "坐井观天，所见甚少——光沿直线传播", "墙内开花墙外香——分子无规则扩散运动"], "a": 0, "e": ".【A】本题考查物理常识，需结合选项具体分析。A项错误，“长啸一声，山鸣谷应”是指声音遇到山谷反射回来形成回声。而声波的衍射是指声波传播过程中遇到障碍物时，部分声波会绕至障碍物背后并继续向前传播的一种现象，不符合题意。B项正确，“小小秤砣压千斤”，根据杠杆平衡的条件：动力×动力臂=阻力×阻力臂，秤砣对秤杆作用的力臂比所挂物对秤杆作用的力臂大的多，所以用较小的秤砣可以与挂较重物体的杠杆平衡。因此，体现的是杠杆原理。C项正确，青蛙坐在井里，只能看到头顶很小的一片天，是因为光在空气中是沿直线传播造成的。D项正确，“墙内开花墙外香”是一种扩散现象，分子可以在空气中扩散，当它扩散到墙外的时候，人就闻到花的香味了。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-160", "q": "单向玻璃的“秘密”就在于玻璃面上涂有很薄的银膜或铝膜。强光照在镜子的银膜上大部分都反射了，而从另一面过来的暗光太弱，被反射的强光所“遮挡”，以至于人们看不见另一面。下列关于单向玻璃描述正确的是。", "options": ["为了达到单向观察的目的，单向玻璃利用特殊的涂层破坏了光路的可逆性", "单向玻璃正面为玻璃镜面，安装时应把正面朝向监控室", "被监控室光线越亮越强，玻璃的单向透视效果越明显", "监控室内要保证一定的亮度，否则不能有效观察被监控室内的情况"], "a": 2, "e": ".【C】本题考查物理常识。单向玻璃即单向透镜。其原理是：涂有金属或反光油漆的一面（A面），能反射大部分的光，如此站在此面的人物（如甲），只能看到玻璃上的一个反射的影像，与传统的镜子没有什么区别。但是还是会有一部分光线，穿透玻璃到达另外一面（B面），使得B面的人（如乙）观察到。A项错误，光路的可逆性是指光能以一条路径从A出发到达一个终点B，那么必然能从这个终点B以完全反向的同一路径到达A点。光路的可逆性不可改变，单向玻璃无法改变。B项错误，正面为玻璃镜面，即站在此面的人看着像普通镜子的一面，所以安装时应把正面朝向被监控室（即：所要观察的空间，如犯罪嫌疑人所在空间）；而把反面朝向监控室所在位置。C项正确，被监控室的灯光强度应保证足够亮度，被监控室光线越亮、越强，玻璃的单向透视效果越明显。D项错误，为使玻璃的单向透视性能达到最佳状态，监控室内原则上不安装天花顶灯，不允许有其他发光灯源存在。监控室旁边若有窗户，必须安装不透光的窗帘，如宾馆酒店使用的密封窗帘。若监控室内一定要使用灯光，建议使用点状灯光，如书写台灯等（灯罩不透光），以缩小灯照范围。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-161", "q": "氯乙烷在常温常压下是气体，平时储存在压强较高的金属罐中。医护人员在对突然受伤的运动员实施急救时，常常会对着受伤部位喷氯乙烷雾状药剂，使受伤部位迅速降温并冷冻，神经被麻痹，疼痛感得以缓解。下列关于氯乙烷的说法正确的是。", "options": ["氯乙烷的沸点比水高", "从气体变成液体过程中，氯乙烷会吸收大量的热量", "在金属罐中，氯乙烷一般处于液体状态", "氯乙烷能使神经麻痹的原因是它含有使神经麻醉的药物成分"], "a": 2, "e": ".【C】本题考查氯乙烷的特性。氯乙烷在常温常压下为无色气体，具有类似醚样的气味，常用作聚丙烯的催化剂，也用作冷冻剂、麻醉剂、杀虫剂等。A项错误，氯乙烷的沸点只有，比水的沸点低，排除。B项错误，物质由气态转变为液态的过程，是液化的过程，液化过程要放热。因此氯乙烷从气体变成液体过程中，会放出热量。C项正确，氯乙烷在常温常压下是气体，但它通常以液体形式被储存在压强较高的金属罐中。低温高压下，气体通常可以被液化，液化后安全性高、运输和储存方便。D项错误，由液体变成气体的氯乙烷从受伤部位的皮肤上吸收了大量热量，皮肤温度瞬间大幅降低，使皮肤肌肉及浅表神经受冷冻麻木，于是疼痛感就被迅速缓解了,而非含有使神经麻醉的药物成分。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-162", "q": "飞机轮胎是飞机上安全性与可靠性要求都很高的重要部件。例如要求轮胎的爆破压力高于额定内压4 倍以上。飞机的安全起飞和降落都必须依靠飞机轮胎的各种独特的功能。下列关于飞机轮胎的说法，正确的是。", "options": ["制造飞机轮胎的橡胶材料要能耐高温和低温，且要有很低的生热性", "为了防止爆胎，飞机轮胎用的是实心轮胎", "为了防止静电积累，飞机轮胎用的是绝缘橡胶", "飞机轮胎承受的落地冲击力约等于飞机的重力"], "a": 0, "e": ".【A】本题主要考查科技常识。飞机轮胎，又称航空轮胎，是指用于航空飞行器械上的充气轮胎。这种轮胎具备的特性主要有：（1）具有高抗冲击强度和很低生热性；（2）用于制造航空轮胎的橡胶材料必须确保在以下和以上的苛刻条件下，经24h后性能符合规定指标；（3）轮胎的爆破压力高于额定内压4倍以上；（4）飞机起飞和降落时轮胎产生的静电荷要能均匀传至地面。A项正确，因为在起飞和降落时与地面摩擦产生大量热量，会使轮胎温度变高，飞机在高空飞行时气温又很低，这就要求飞机轮胎既要耐高温，又要耐低温，且要求轮胎具有很低的生热性。B项错误，飞机轮胎属于充气轮胎，即飞机轮胎是空心的，它行驶舒适，重量轻，操控性比实心胎好，飞机在降落时还可以起到吸收地面震动，起到减震的功能。C项错误，飞机起飞和降落时，轮胎会产生静电荷，为使静电能均匀传至地面，飞机轮胎一般为导电橡胶。D项错误，飞机轮胎必须具有高抗冲击强度，其承受的落地冲击力大于飞机的重力。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-163", "q": "超声波技术用途非常广泛，它使用类似于声波，但某项参数大于普通声波的振动技术来工作，所以称为超声波，这个大于普通声波的参数是：", "options": ["波长", "振幅", "传播速度", "频率"], "a": 3, "e": ".【D】人对声音的感觉有一定频率范围，大约每秒钟振动20次到20000次范围内，即频率范围是20Hz~20000Hz，如果物体振动频率低于20Hz或高于20000Hz人耳就听不到了。高于20000Hz的频率就叫做超声波，而低于20Hz的频率就叫做次声波。据此可知，这个大于普通声波的参数是频率。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-164", "q": "中国首位80 后女航天员王亚平，随神舟十号飞船进入太空飞行15 天。飞行中她不会碰到的情况是：", "options": ["看到绚丽多彩的极光", "四周一片漆黑", "穿过稠密的大气层", "听到远处星体爆炸的声音"], "a": 3, "e": ".【D】声音的传播是需要介质的，比如固体，液体，气体。太空接近真空状态，不能传声，所以航天员不可能听到爆炸声，故D选项错误，其他选项均表述正确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-165", "q": "下列古代汲水灌溉工具与应用原理对应错误的是：", "options": ["桔槔——杠杆原理", "辘轳——轮轴原理", "翻车——对称守恒原理", "筒车——叶轮原理"], "a": 2, "e": ".【C】A项正确：桔槔始见于《墨子备城门》，作“颉皋”。是一种利用杠杆原理的取水机械。B项正确：辘轳，汉族民间提水设施，流行于北方地区。由辘轳头、支架、井绳、水斗等部分构成。利用轮轴原理制成的井上汲水的起重装置。C项错误：中国古代链传动的最早应用就是在翻车上，是农业灌溉机械的一项重大改进。翻车并没有应用对称守恒原理，此原理经常用在协同反应中描述分子轨道。D项正确：筒车是和翻车相类似的提水机具。这是利用湍急的水流转动车轮，使装在车轮上的水筒，自动戽水，提上岸来进行灌溉。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-166", "q": "下列关于生活常识的表述错误的是：", "options": ["水在真空中会先沸腾后结冰", "颜色深的汽车隔热膜，隔热效果好", "纯水（只有水分子）在", "天凉时，湿润的地方比干旱的地方使人觉得更冷"], "a": 1, "e": ".【B】A项，正确：水的沸点随着气压的降低而降低，而真空中没有空气，所以水开始会沸腾，然后水变成水蒸气吸收热量，温度降低进而结冰。B项，错误：汽车贴隔热膜的主要目的，就是在汽车玻璃上形成一道隔绝层，阻止热量透过玻璃进入到车内。早期的隔热膜以染色工艺为主，靠颜色来隔热，需要颜色越深才能起到效果。而实际上这种方式并不好。现在的汽车隔热膜的隔热效果和膜的颜色深浅没有必然的关系。优质的隔热膜不但能够高效地隔热，还能同时保证高的透光度，保障行车安全。C项，正确：纯水只含水分子时，当温度降低到冰点以下时还会保持液态，这被称为过冷水。但是一旦有振动或凝结核加入（比如随机的灰尘、气泡以及不平整的容器壁）时就会迅速结晶。D项，正确：天凉的时候，人感觉到的温度实际上是衣服以及被衣服隔离的皮肤表面那些空气的温度。水的比热很大，用人的体温来加热潮湿的空气要比加热干燥的空气会消耗更多的热量，所以人会在湿润的地方感觉到更冷。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-167", "q": "对着电视画面拍照，应关闭照相机闪光灯和室内照明灯，这样照出的照片画面更清晰。这是因为：", "options": ["闪光灯和照明灯在电视屏上的反射光会干扰电视画面的透射光", "闪光灯和照明灯在电视屏上的反射光会干扰电视画面的散射光", "闪光灯和照明灯在电视屏上的透射光会干扰电视画面的散射光", "闪光灯和照明灯在电视屏上的透射光会干扰电视画面的反射光"], "a": 0, "e": ".【A】闪光灯、照明灯和电视机屏幕都是光源，都会发光。电视机屏幕相当于透镜，当闪光灯和照明灯的光线照射到电视机屏幕上时，会发生光线反射，从而干扰到电视机自身发出的透射光。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-168", "q": "人造骨要求作为原料的金属具有耐热性、韧性和生物相容性等特点。据此，下列材料最适合制作人造骨的是：", "options": ["钛合金", "青铜", "焊锡", "不锈钢"], "a": 0, "e": ".【A】A项：正确。钛是20世纪50年代发展起来的一种重要的结构金属，无毒、质轻、强度高且具有优良的生物相容性，钛合金因具有强度高、耐蚀性好、耐热性高等特点，是非常理想的医用金属材料，可用作植入人体的植入物、矫形器等。B项：错误，青铜是3000多年前人类掌握的第一种合金（铜和锡或铅），韧性、生物相容性较差。C项：错误，焊锡是在焊接线路中连接电子元器件的重要工业原材料，广泛应用于电子工业、家电制造业、汽车制造业、维修业和日常生活中。D项：错误，不锈钢主要用于建筑、工业生产和日常生活中，不适用于人造骨。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-169", "q": "如果将豆腐冰冻一段时间再解冻，豆腐内部会出现非常多的小孔。这一变化的原因是：", "options": ["豆腐内的水分聚集凝结成冰晶，体积增大，挤出了这些小孔", "豆腐在低温下组织纤维变硬，体积膨大，露出了空隙", "温度骤然变化导致豆腐的组织纤维热胀冷缩，露出了空隙", "豆腐中的某些成分在低温环境下释放出大量气体，挤出了这些小孔"], "a": 0, "e": ".【A】A项符合题意：冷冻后的豆腐发生了物理变化。水有一种特性：在时，它的密度最大，体积最小；到以下时，水结成了冰，密度变小，体积变大，比常温时水的体积约大左右。当豆腐的温度降到以下时，里面的水分结成冰，原来的小孔便被冰撑大了，整块豆腐就被挤压成网格形状。等到冰融化成水从豆腐里跑掉以后，就留下了数不清的孔洞，使豆腐变得像泡沫塑料一样。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-170", "q": "水银可用于制作体温计，其主要原因不包括：", "options": ["水银对温度变化敏感", "水银容易获得", "水银的熔点低，沸点高", "水银的化学性质稳定"], "a": 1, "e": ".【B】给体温计选用材料时，优先考虑的是原材料的特性。对利用液体热胀冷缩的特性来制造的体温计，一般应考虑以下因素：①液体的沸点和熔点；②性能是否稳定；③液体体积对温度变化是否敏感。B项错误：体温计的工作物质是水银，水银体温计中含有汞。汞在自然界以硫化汞矿石的形式大量存在，即“朱砂”，制取过程相对容易。但题目中说的水银用作体温计的主要原因，强调的是水银的物理性质和化学性质，容易获得并不是主要原因，就像CPU（中央处理器）中含有黄金，黄金容易取得，但这不是CPU发挥功能的主要原因，故B项错误。A项正确：体温计液泡里的水银，由于受到体温的影响，产生微小的变化，水银体积的膨胀，使管内水银柱的高度发生明显的变化。体温计的下部靠近液泡处的管颈是一个很狭窄的曲颈，在测体温时，液泡内的水银，受热体积膨胀，由曲颈部分上升到管内某位置。当与体温达到热平衡时，水银柱恒定。当体温计离开人体后，外界气温较低，水银遇冷体积收缩，就在狭窄的曲颈部分断开，使已升入管内的部分水银退不回来，水银柱仍保持在与人体接触时所达到的高度。微小的变化就能使水银柱的高度发生明显变化，这说明水银对温度的变化敏感。C项正确：水银是在常温、常压下唯一以液态存在的金属。熔点，沸点，密度13.59，可见水银的熔点低、沸点高，这使得它在除了极端环境外的绝大多数环境条件下，都能正常使用。D项正确：汞是银白色闪亮的重质液体，不溶于酸也不溶于碱，其化学性质稳定。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-171", "q": "不要靠近高压带电体是安全用电常识。但是我们经常可以看到，站在高压线上的小鸟并不会发生触电事故。这是因为：", "options": ["电线上有绝缘层", "小鸟爪上的角质层不导电", "小鸟能承受高压电", "小鸟两爪间的电压很低"], "a": 3, "e": ".【D】本题考查物理常识。主要涉及高压触电的相关内容。D项正确：高压触电的两种方式：高压电弧触电和跨步电压触电。而跨步电压触电的本质原因是（以人为例）：人的两只脚离高压电源的距离不同（除非只用一条腿跳），这就造成两条腿形成了较大的电压差，导致电流从一条腿流进去，从另一条腿流出来，就触电了。但是小鸟呢？它的两条腿之间的距离很小，导致两条腿之间的电压很低，此时电流就不会从鸟的一条腿流进去，从另一条腿流出来，电流只会通过电线流过去（这可以看成是短路），所以鸟就安然无恙了。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-172", "q": "下列现象对应的光学原理错误的是：", "options": ["汽车后视镜扩大驾驶员视野——折射", "雨夜路灯出现一圈圈的光环——色散", "看立体电影需戴上特殊眼镜——偏振", "使用闪光灯拍照时出现红眼——反射"], "a": 0, "e": ".【A】A项对应错误：汽车后视镜利用光的反射原理观察车后情况，同时利用凸面镜对光有发散作用的原理，可以扩大视野，从而更好地注意到后方车辆的情况。而光的折射是光从一种介质斜射入另一种介质时，传播方向发生改变，从而使光线在不同介质的交界处发生偏折。当选。B项对应正确：色散是指白色的复合光（如阳光），经过介质被折射，形成单色光的现象。雨天水雾笼罩着路灯，灯光发射出来，发生了色散，不同颜色的光线被分开，从而形成五颜六色的光环。排除。C项对应正确：偏振式3D技术是利用光线有“振动方向”的原理来分解原始图像的，它先把图像分为垂直向偏振光和水平向偏振光两组画面3D眼镜左右镜片分别采用不同偏振方向的偏光镜片，这样人的左右眼就能接收到两组画面，再经过大脑合成立体影像。排除。D项对应正确：当人长时间地待在较黑暗的环境中，瞳孔为适应视觉需要而放大，这时如果闪光灯的位置与人的眼睛一般高低，被拍摄者又是正面对着镜头，瞳孔与闪光灯处于同一直线上。那么，在拍摄时，当闪光灯的强光照射到眼睛时，就会直射视网膜，其红色的反射光就很有可能进入相机的拍摄视角，从而产生“红眼”。排除。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-173", "q": "有四个同样大小、质量相等的空心球，他们分别由铁、铝、铜、铅制成。则四个球空心部分体积最大的是：", "options": ["铁球", "铝球", "铜球", "铅球"], "a": 3, "e": ".【D】本题考查物理常识。由四个球的质量结合它们的密度，利用密度公式可比较它们实心时的体积大小；再与它们的实际体积比较就能得到答案。四个球的质量相等，即：；四个球的密度关系是：，又因为密度和体积成反比，因此可知同等质量的条件下，铅球的体积是最小的，如果将其做成质量同样大小的空心球，则其空的部分会最大，因此四个空心球中空心部分体积最大的是铅，其次是铜，然后是铁，铝质空心球中空心部分的体积最小。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-174", "q": "每年春天，广州经常出现“返潮”现象，俗称“回南天”。专家解释这是因为暖湿气流来到我市，空气中水蒸气的含量较高，遇到地面、墙壁等处的温度较低，极易发生（）现象，使地面、墙壁冒“冷汗”。", "options": ["凝固", "升华", "凝华", "液化"], "a": 3, "e": ".【D】本题考查物理常识。A项错误，物质从液态变为固态叫凝固，凝固时要放热。本题中，使地面、墙壁冒“冷汗”不是固态。B项错误，升华指物质从固态直接变成气态的相变过程。本题中，空气中的水蒸汽不是固态。C项错误，凝华指物质从气态不经过液态而直接变成固态的现象。本题中，使地面、墙壁冒“冷汗”不是固态。D项正确，液化指物质由气态转变为液态的过程。本题中，空气中水蒸汽的含量较高，遇到地面、墙壁等处的温度较低，使地面、墙壁冒“冷汗”，是液化。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-175", "q": "关于成语或俗语所揭示的声学、热学现象，下列表述错误的是：", "options": ["长啸一声，山鸣谷应：声音在山谷之间发生多次反射，形成回声", "曲高和寡：频率越大，所发声音的音调越高，能跟着唱的人越少", "瑞雪兆丰年：雪覆盖在农作物上面，防止热传导和空气对流，起到保温作用", "弦外之音：声音在传播过程中，会发生衍射，所以有些声音我们听不到"], "a": 3, "e": ".【D】D项错误：“弦外之音”原指音乐的余音，比喻言外之意，即在话里间接透露，而不是明说出来的意思。用物理常识来解释就是指人的听觉频率范围之外的（如超声、次声）确实存在且我们是听不到的声音。声衍射是指声波传播过程中遇到障碍物时，部分声波会绕至障碍物背后并继续向前传播的一种现象，又称声绕射。衍射和听不到之间没有因果关系。A项正确：“长啸一声,山鸣谷应”是回声现象，声音遇到障碍物会被反射回来。具体说是声音的反射现象，声音从人口中啸出会经过多次反射，而每次反射都会有一部分进入你的耳朵，所以山反射的像是山在回应，谷反射的像是谷在回应。B项正确：“曲高和寡”的字面意思是乐曲的音调越高，能跟着唱的人就越少。曲高指的是音乐的音调高，音调就是指声音的高低，频率是指发声体一秒钟振动的次数。音调主要由声音的频率决定,同时也与声音强度有关。对一定强度的纯音,音调随频率的升降而升降；对一定频率的纯音、低频纯音的音调随声强增加而下降,高频纯音的音调却随强度增加而上升。C项正确：“瑞雪兆丰年”的科学道理是，对于北方来说,秋季种的冬小麦,在冬天里,如果下雪的话,雪不易融化,盖在土壤上的雪是比较松软的,雪花和雪花之间留有空隙,空隙中充满空气,空气又具有不良的热传导特性,这样就像给庄稼盖了一条棉被,外面天气再冷,下面的温度也不会降得很低,起到一种保温作用。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-176", "q": "关于通信，下列说法错误的是：", "options": ["如今“通信”这一术语一般指“电信”", "电信是利用电信号来传输信息的通信方式", "击鼓和鸣金传递作战命令也是通信手段", "赫兹证明了电磁波的存在，开创了通信新时代"], "a": 0, "e": ".【A】A项错误：通信，指人与人或人与自然之间通过某种行为或媒介进行的信息交流与传递。它不单指电信，还包括邮政通信，传递消息等概念。B项正确：电信是指以任何电磁方式传递或接收信号，非电的物理量可以通过各种传感器转换成电信号进行信息的传递。C项正确：通信是人与人或人与自然之间通过某种行为或媒介进行的信息交流与传递，从广义上说，无论采用何种方法，使用何种媒质，只要将信息从一地传送到另一地，均可称为通信。击鼓鸣金即为以鼓和金为媒介传递作战信息的通信手段。D项正确：电磁波首先由詹姆斯•麦克斯韦于1865年预测出来，而后由德国物理学家海因里希•赫兹于1887年至1888年间在实验中证实存在。电磁波被发现后，广泛应用于无线电广播及手机通讯、卫星信号、导航、遥控、定位等领域。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-177", "q": "关于物理现象的解释，下列说法错误的是：", "options": ["量子隧穿效应不遵循牛顿运动定律", "“小小秤砣压千斤”运用的是杠杆原理", "汽车的观后镜多使用凸面镜，可以扩大视野范围", "高压锅煮食物快主要是因为增大了锅内气压，降低了水的沸点"], "a": 3, "e": ".【D】D项错误：高压锅煮食物快是因为水的沸点与压强有关，压强增大，沸点升高，煮饭菜时高压锅的气压比普通锅内的气压高，所以水沸腾时高压锅内的温度高于普通锅内的温度，温度越高，饭菜熟的越快。A项正确：量子隧穿效应是一种量子特性，是电子等微观粒子能够穿过它们本来无法通过的“墙壁”的现象。这种效应无法用经典力学来解释，不遵循牛顿运动定律。B项正确：秤杆可以看做一个杠杆，根据杠杆原理，秤砣的质量比较小，但是它的力臂比较长。相反，千斤物体的质量虽然大，但是力臂却比较短，所以二者可以平衡。C项正确：汽车的观后镜是凸面镜，凸面镜对光有发散作用，能使驾驶员观察到更大范围的景物，因此利用凸面镜制作的观后镜可以扩大驾驶员的视野。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-178", "q": "在能源危机面前，人们纷纷将目光投向大海，浩瀚的大海有类型多样、数量巨大的海洋能源，关于各种海洋能源利用，以下表述错误的是：", "options": ["人们所说的海洋能源主要指海底所储存的煤、石油、天然气等海底能源资源以及溶于水中的铀、锂、镁、重水等化学", "通过风的作用引起海水沿水平方向周期性运动产生的波浪能可以发电", "盐差能发电原理实际上是利用浓溶液扩散到稀溶液中释放出的能量", "海水容纳的热量是巨大的，海洋热能是电能的来源之一"], "a": 0, "e": ".【A】A项错误：浩瀚的大海，不仅蕴藏着丰富的矿产资源，更有真正意义上取之不尽、用之不竭的海洋能源。它既不同于海底所储存的煤、石油、天然气等海底能源资源，也不同于溶于水中的铀、镁、锂、重水等化学能源资源，而是潮汐能、波浪能、海水温差能、海流能及盐度差能等独特的能源形态。B、C、D三项说法均正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-179", "q": "参会代表在主席台前合影后，某专家要求拍一张单身照，摄影师应采取的方法是：", "options": ["使照相机靠近他，同时镜头往后缩，离胶片近一些", "使照相机靠近他，同时镜头向前伸，离胶片远一些", "使照相机远离他，同时镜头往后缩，离胶片近一些", "使照相机远离他，同时镜头向前伸，离胶片远一些"], "a": 1, "e": ".【B】B项正确：照相机前面都有一个镜头，镜头相当于一个凸透镜，来自物体的光经镜头后会聚在胶片上，形成一个倒立、缩小的实像。根据题意，参会代表在合影结束后要再拍张单人照，实际上就是要让人的像变大。根据照相机的调节方式，要使底片上人的像变大，人离镜头应该近一些，像离镜头要远一些，所以照相机要更靠近人，同时镜头应该往前伸，拉大镜头与胶片的距离，A、C、D项均错误。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-180", "q": "以下选项中的工具或应用所依据的科学原理与其他三项不同的是（）。", "options": ["温度计", "热气球", "热继电器", "潮汐发电"], "a": 3, "e": ".【D】A项温度计是利用了水银热胀冷缩的原理。B项中热气球也是利用了空气受热膨胀上升的原理。C项中热继电器是利用了双金属片受热膨胀变形达到保护元件的目的。D项潮汐发电是一种利用涨潮落潮之间的落差推动水轮发电机，带动发电机发电。A、B、C三项利用的是热胀冷缩的原理，D项利用的是潮位落差，因此D项不同。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-181", "q": "人们在厨房做菜时，如果不小心把水滴进热油锅中，常常会发生溅油的现象。这是因为（）。", "options": ["水与油一起加热产生了化学反应，释放出热量", "水密度比油大而沸点比油低，会在油面下迅速汽化", "油在加热情况下与水相溶，更容易蒸发而产生气泡", "水在加热时对流速度加快，与油发生摩擦而产生了热量"], "a": 1, "e": ".【B】油的密度比水的小，且其沸点比水的大，所以水滴入热油中，水被瞬时加热，超过了水的沸点，会沸腾，将油溅起来，就产生了“溅油”现象，故B项正确。溅油现象属于物理现象不是化学反应，故A项错误。水分子和油分子由于表面张力差别太大，互相不会融合。水分子在油里面是以滴状形式存在的。换句话说，油水互不交融也不会产生摩擦，故C、D项错误。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-182", "q": "下列对诗词中的物理现象描述错误的是：", "options": ["坐地日行八万里，巡天遥看一千河——地球的公转", "两岸青山相对出，孤帆一片日边来——运动的相对性", "八月秋高风怒号，卷我屋上三重茅——空气振动发声", "飞流直下三千尺，疑是银河落九天——势能转化为动能"], "a": 0, "e": ".【A】A项错误，“坐地日行八万里”是指地球自转。地球赤道半径约6371公里,地球自转一周,人行的路程为周长值约为：。B项正确，“两岸青山相对出”，研究的对象是“青山”，运动状态是“出”，青山是运动的，是相对于船来说的；“孤帆一片日边来”，研究的对象是“孤帆”，运动状态是“来”，船是运动的，相对于日（或两岸、青山）来说的。同一个物体，以不同的参照物，它的运动状态可能不同，这就是运动和静止的相对性。C项正确，“八月秋高风怒号”中的风声是空气振动发出的声音。D项正确，“飞流直下三千尺”，是因为水受到重力的作用，从高处往低处流，在此过程中势能减小，减小的势能转化为动能。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-183", "q": "在生活中，下列哪一做法或现象与热胀冷缩无关：", "options": ["夏天在架设电线时，不宜把电线绷得太紧", "往保温瓶灌开水时，不灌满比灌满更容易保温", "把刚煮熟的鸡蛋放到冷水中浸一下，更容易剥壳", "冬天往玻璃杯中倒开水，应先用少量开水预热杯子"], "a": 1, "e": ".【B】夏天比较热，电线吸收热量，处于伸张状态；天气转凉后，电线因释放热量，会收缩。所以绷太紧容易导致收缩过量产生拉力，电线容易形变，当形变超过临界值，就会发生断裂，产生事故。A项说法与热胀冷缩有关。空气是热的不良导体，如果水没有完全灌满，相对于水直接接触瓶盖来说，相当于多了一层保温层。B项说法与热胀冷缩无关。大多数物质都有“热胀冷缩”的物理特性。但是，各种物质的伸缩程度又各不相同。鸡蛋是由硬的蛋壳和软的蛋白、蛋黄组成的，当温度剧烈变化时，蛋白和蛋壳的步调会不一致，形成了蛋白与蛋壳的脱离。因此，就不会连蛋壳带蛋白一起剥下来。C项说法与热胀冷缩有关。玻璃是热的不良导体，热量在玻璃中传得很慢，杯子中倒进热水后，玻璃里面一面很快被加热，体积膨胀，但杯子外壁还没有被加热，体积不变，这样就会造成杯子破裂。D项说法与热胀冷缩有关。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-184", "q": "高铁列车的车窗和车门在运行过程中必须完全密闭。对此，下列解释最准确的是：", "options": ["减少高铁列车运行的能源消耗", "保持高铁列车车厢内部的安静", "避免车速过快形成空气压强差", "确保高铁列车车厢内部的整洁"], "a": 2, "e": ".【C】高铁列车行驶时会产生巨大的空气压强差，特别是列车进出隧道和两车交会时的巨大噪声也会乘虚而入，乘客根本无法忍受这种空气压强差，轻则使乘客耳膜产生压迫感，重则会使乘客感到头晕恶心，严重时甚至造成耳膜破裂。事实上，高铁列车上不仅窗户要固定、密闭，其车门、车厢连接处等都要尽可能地做到密闭，如此才能保证旅客有一个舒适的乘坐环境。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-185", "q": "声音与人们的生活密切相关，以下有关声音现象的说法正确的是（）。", "options": ["市区内禁止鸣笛是为了减弱声音在传播过程中的噪音", "用超声波能粉碎人体内的结石，说明超声波具有能量", "“闻其声而知其人”主要是根据声音的音调进行判断的", "在生活中，有些高科技产品，不振动也可以发出声音"], "a": 1, "e": ".【B】A项错误，市区内禁止鸣笛是为了从声源处切断噪音。B项正确，超声碎石是利用电能转变成声波，声波在超声转换器内产生机械振动能，通过超声电极传递到超声探杆上，使其顶端发生纵向振动，当与坚硬的结石接触时产生碎石效应，但对柔软的组织并不造成损伤。C项错误，“闻其声而知其人”靠的是音色。D项错误，声音是由物体振动产生的声波，是通过介质（空气或固体、液体）传播并能被人或动物听觉器官所感知的波动现象。因此，声音的发出和传递都要靠振动，没有振动就没有声音。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-186", "q": "蜜蜂载着花蜜飞行时，翅膀平均每秒振动300 次；不载花蜜时，平均每秒振动440 次。有经验的养蜂人能辨别出蜜蜂是飞出去采蜜，还是采了蜜飞回来。养蜂人的依据是翅膀振动发出声音的：", "options": ["音色不同", "音调不同", "音节不同", "响度不同"], "a": 1, "e": ".【B】声源在一秒钟之内振动的次数叫做频率，声源振动频率的高低决定音调的高低，即声源振动频率越高，音调越高，反之亦然。结合题干，可知养蜂人是根据蜜蜂翅膀振动发出声音的音调不同来判断蜜蜂的采蜜情况。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-187", "q": "雨后晴朗的月夜，为了防止踩到地上的积水，下列判断正确的是：", "options": ["迎着月光走，地上发亮处是水；背着月光走，地上暗处是水", "迎着月光走或背着月光走，都应该是地上暗处是水", "迎着月光走或背着月光走，都应该是地上发亮处是水", "迎着月光走，地上暗处是水；背着月光走，地上发亮处是水"], "a": 0, "e": ".【A】由于地面凹凸不平，光射到地面上发生漫反射，漫反射能让人从各个方向看到物体；水面光滑无凹凸，光射到地面的积水上发生镜面反射，镜面反射只能让我们从某个方向看到物体。迎着月光走时，水面的反射光线全部射进人眼，地面的反射光线只有部分射进人眼，因此水面的光更强，即发亮处是水；背着月光走时，水面的反射光射向人的背部，无法进入人眼，地面的反射光仍有部分进入人眼，此时发亮处是地面，暗处的地方则为积水。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-188", "q": "关于自然光学现象的成因，下列解释错误的是：", "options": ["晚霞：太阳光斜照至地球时，遇到悬浮在大气层高处的细小尘粒产生散射", "地球极光：来自太阳的高能带电粒子流与大气摩擦生热发光", "彩虹：阳光照射到空中接近球形的小水滴光线发生色散及衍射", "海市蜃楼：光在均匀的空气中连续发生折射和全反射"], "a": 2, "e": ".【C】A项正确，晚霞是指傍晚日落前后的天边出现的五彩缤纷的彩霞。晚霞的形成都是由于空气对光线的散射作用。当太阳光射入大气层后，遇到大气分子和悬浮在大气中的微粒，就会发生散射。这些大气分子和微粒本身是不会发光的，但由于它们散射了太阳光，使每一个大气分子都形成了一个散射光源。B项正确，极光是来自太阳的高能带电粒子与地球上层大气中的中性原子相互作用引起的。这些高能粒子能激活(通过碰撞)那些束缚于中性原子上的化合价，使其放电发光，并由于高强度摩擦发热放光，产生带色光。C项错误，彩虹是太阳光照射到空气中的水滴、微尘等，光线经折射、反射、色散，在天空上形成拱形的七彩光谱，雨后常见。其中没有光的衍射，光的衍射是指光在传播过程中，遇到障碍物或小孔时，光将偏离直线传播的途径而绕到障碍物后面传播的现象。D项正确，海市蜃楼，简称蜃景，是一种因为光的折射和全反射而形成的自然现象，是地球上物体反射的光经大气折射而形成的虚像。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-189", "q": "下列关于新能源的说法正确的是：", "options": ["沼气的主要成分与瓦斯相同", "核电站是利用核衰变发电", "氢气的热值低于汽油", "风能的来源与太阳能无关"], "a": 0, "e": ".【A】A项说法正确，沼气和瓦斯的主要成分都是甲烷。B项错误，核电站主要利用核裂变发电；C项错误，汽油的热值约为46kJ/g，氢气的热值为143kJ/g，约为汽油的3倍；D项错误，风是由空气流动引起的自然现象，风能即是地球表面大量空气流动所产生的动能，而风是太阳辐射热引起的，因此风能的来源与太阳能有关。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-190", "q": "下列生活现象与大气压强无关的是：", "options": ["用注射器进行肌肉注射", "给钢笔吸取墨水", "茶壶上留一个小孔", "将吸盘挂衣钩贴在墙上"], "a": 0, "e": ".【A】A项用注射器进行肌肉注射，是人为用力推动注射器的活塞，使注射器内压强大于人体内压强，从而将注射液压入体内，与大气压强无关。B项是利用大气压把墨水吸到钢笔的墨水囊里，C项茶壶上留小孔是为了保持茶壶内外的气压平衡，D项是利用大气压使吸盘紧贴在墙上，B、C、D三项提及的现象均与大气压强有关。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-191", "q": "下列对于作用力的分析正确的是：", "options": ["推出的铅球在空中受到重力和推力的作用", "桨对水的推力是木船前进的动力", "丢入池塘的石子没入水中后，在不同深度所受浮力不同", "匀速行驶的汽车对放在车上的货物没有静摩擦力作用"], "a": 3, "e": ".【D】D项分析正确，装载货物的汽车，货物与汽车之间的静摩擦力与汽车的行驶状况有关，汽车加速或减速行驶时，车上货物会受到静摩擦力作用，匀速行驶时，货物则不受静摩擦力作用。A项错误，铅球被推出去后，铅球和手之间的相互作用力消失，即手的推力消失，铅球在空中只受到重力作用；B项错误，木船前进的动力是桨推水时受到的反作用力，也就是水作用于桨的力，而不是桨对水的推力；C项错误，当石子没入水中后，所受的浮力的大小等于它排开的液体受到的重力，与深度无关。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-192", "q": "马航MH370 航班失踪之后，国际海事卫星组织试图利用多普勒原理计算出失踪航班的下落。多普勒原理，源于这样的一种物理现象(多普勒效应)：随着飞机高速接近(或远离)接受微波信号的卫星，卫星所侦测到的微波频率都会越来越高(或越来越低)。下列描述的现象中，哪一种也体现了同样的多普勒效应：", "options": ["站在铁轨附近的人，听到鸣笛的火车由远及近高速驶来时，汽笛的音调逐渐变得尖锐。", "一束自然光射入三棱镜，射出时，被分解为不同的颜色。", "向平静的湖面投入一颗小石子，激起涟漪呈圆形逐渐向周围扩散。", "在日环食的过程中，观测到太阳黑子的存在。"], "a": 0, "e": ".【A】多普勒效应主要内容是物体辐射的波长因为波源和观测者的相对运动而产生变化。A项满足定义描述。B项的原理为色散，因为同一种介质对各种单色光的折射率不同，所以通过三棱镜时，各单色光的偏折角不同。因此，白色光通过三棱镜会将各单色光分开，形成红、橙、黄、绿、蓝、靛、紫七种色光。C项的原理为波的传导的一种表现，即机械振动的传递构成的机械波。D项太阳黑子是一种太阳活动，是出现在光球层（太阳大气层的最内层）上的黑斑点。太阳黑子区域温度比周围低，因此颜色看上去深一些，与题干无关。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-193", "q": "普朗克曾这样评论爱因斯坦的科学成就：“这个原理在物理世界观上所引起的革命，只有哥白尼世界体系的引入才能与之相提并论。”文中的“这个原理”是：", "options": ["相对论", "日心说", "量子假说", "万有引力定律"], "a": 0, "e": ".【A】四个选项中，A项相对论由爱因斯坦提出，B项日心说由哥白尼提出，C项量子假说最早是由普朗克提出的，D项万有引力定律由牛顿提出。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-194", "q": "红色与黄色混合得到一种新颜色，红色与蓝色混合得到另一种新颜色，这两种新颜色分别是：", "options": ["绿色、紫色", "绿色、橙色", "橙色、紫色", "紫色、绿色"], "a": 2, "e": ".【C】红色、黄色和蓝色合称为颜料三原色，又称作减色法三原色。这三种颜色按不同比例混合，可变化出各种颜色。红色和黄色按1比1比例混合是砖红色，按1比3混合是橙色。红色和蓝色按1比1比例混合是紫色。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-195", "q": "下列现象属于化学反应的是：", "options": ["春江水暖鸭先知", "蜡炬成灰泪始干", "玉不琢不成器", "绳锯木断、水滴石穿"], "a": 1, "e": ".【B】判断一个反应是否为化学反应的依据是反应是否生成新的物质。题干四个选项中，只有B项有新的物质形成，“灰”便是“蜡炬”经过不完全燃烧生成的炭和蜡炬中杂质燃烧后的产物。A、C、D三项都属于物理现象，没有发生化学反应。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-196", "q": "日常生活中，我们常听到某些饮料的广告词称自己“富含钙、锌”等等，这里的“钙”“锌”指的是（）", "options": ["夸克", "分子", "单质", "元素"], "a": 3, "e": ".【D】D项正确，饮料的广告词称自己“富含钙、锌”等等，这里的“钙、锌”等一般不能以单质、氧化物、分子、原子等形式存在，这里所指的“钙、锌”是强调存在的元素，且与具体形态无关。A、B项错误，分子和夸克是一种基本粒子，也是构成物质的基本单元，题干强调的不是物质的组成粒子，因此A、B项错误。C项错误，“锌、钙”等单质一般呈固态，是不能直接食用的。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-197", "q": "下列说法错误的是：", "options": ["根据光的偏振原理可以制成看立体电影的立体眼镜", "打枪瞄准时闭上一只眼利用了光沿直线传播的原理", "光在光纤中传播利用的是光的全反射原理", "潜望镜利用了光的折射原理"], "a": 3, "e": ".【D】D项错误，光的折射是指光线从一种介质（如空气）斜射入其传播速度不同的另一种介质（如水、玻璃）时发生的对直线路径的偏离，潜望镜中不存在传播介质的变化，是利用光的反射原理来实现传播路径的弯折。A、B、C三项正确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-198", "q": "为了降低食品袋中食物湿度，防止食品变质腐败，常常会在食品袋中放入干燥剂。下列干燥剂中，其干燥原理与其他不同的是（）。", "options": ["硅胶", "活性炭", "碱石灰", "活性氧化铝"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，硅胶是一种高活性、多孔性物质，其内部表面积很大，有较强的吸附性，吸湿量能达到左右。它的干燥原理是吸附。B项正确，活性炭是一种粉状或粒状的多孔无定形炭，它具有发达的孔隙结构、很大的比表面积(可达1500平方米/克以上)和巨大的吸附力。它的干燥原理是吸附。C项错误，碱石灰是氧化钙与氢氧化钠的混合物，极易吸收水分和二氧化碳而变成碳酸钙和碳酸钠，因而常用作气体的干燥剂和二氧化碳的吸收剂。它的干燥原理是发生化学反应，；；。因此它与其他三项干燥原理不同。D项正确，活性氧化铝是多孔的颗粒状氧化铝，它对气体、水蒸气和某些液体的水分有选择吸附本领。它的干燥原理是吸附。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-199", "q": "与驾驶小汽车相比，驾驶员以同样的速度驾驶公交车时，会感觉公交车移动的速度更快。以下最能解释这一现象的是（）。", "options": ["公交车挡风玻璃比小汽车的挡风玻璃厚，造成司机视线差异", "公交车车头更短，司机可以看到距离车头很近的地面", "公交车体型比小汽车大得多，需要更大的动力和刹车距离", "公交车挡风玻璃面积更大，司机的视线范围更广"], "a": 1, "e": ".【B】本题考查科技常识。人们判断运动知觉的变量不是线速度，而是角速度（视角度/秒）。一个点状物以相同速度运动，若其运动方向恰好与眼睛视线平行，此时的视角为（当然，人有两只眼睛，不可能与两只眼睛都为0，实际上只能是接近0），即角速度为0，你几乎感觉不到它在运动；而当运动方向与眼睛视线垂直时，角速度就最大，就能感觉到很快的运动速度；另外，角速度的大小还与距离相关，距离越远，角速度显然越小，距离越近，角速度越大。由此可见，在不同的位置（不同的角度、不同的距离）观看相同运动速度的物体，会有截然不同的速度感。开不同的车会有不同的视野，也会产生不同的速度感。小汽车与公交车，由于公交车都是平头，前挡玻璃几乎是垂直的，人的座位又高，驾驶员可以看到离车头很近的路面，自然就感觉快。而小车就不一样了，小车车头较长，前挡玻璃都是倾斜安装的，而且斜度还较大，座位比较靠后，这样人离车头的距离就远了；同时小车的座位又很低，这样驾驶员的视线就只能以比较平的角度看车头前的路面，所能看到的路面与驾驶员所坐的位置有了很大的一段水平距离（也就是说车头前方还有一段较长路面被车头挡住看不到），就会感觉速度比公交车慢。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-200", "q": "运送人造地球卫星的火箭开始工作后，火箭做加速运动的原因是：", "options": ["火箭发动机用力将燃料燃烧产生的气体向后推出，气体的反作用力推动火箭", "燃料推动空气，空气的反作用力推动火箭", "火箭燃料燃烧发热，加热周围空气，空气膨胀推动火箭", "火箭吸入空气，然后向后排出，空气对火箭的反作用力推动火箭"], "a": 0, "e": ".【A】本题考查科技常识。运送人造地球卫星的火箭开始工作后，火箭做加速运动主要是运用了“反冲运动”的原理。根据动量守恒定律，如果一个静止的物体在内力的作用下分裂为两个部分，一部分向某个方向运动，另一部分必然向相反的方向运动，这个现象叫做反冲。反冲运动中，火箭发动机用力将燃料燃烧产生的气体向后推出（喷出），喷出的气体对火箭施加反作用力，即反冲力，反冲力推动火箭上升。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-201", "q": "下列谚语及其解释对应正确的是（）。", "options": ["下雪不冷，化雪冷——凝华放热，液化吸热", "雷雨发庄稼——放电环境下会生成氮肥", "真金不怕火炼——金具有硬度大的性质", "酒香不怕巷子深——分子之间存在斥力"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，下雪是水蒸气的凝华过程，凝华放热，人感觉不冷；而化雪是熔化过程，熔化吸热，导致环境温度降低，人感觉冷。选项中“液化”表述有误。B项正确，放电环境下，空气中的氮气与氧气反应生成一氧化氮，一氧化氮又与氧气反应生成二氧化氮。二氧化氮易溶于水生成硝酸随雨水落到土壤中，同土壤中矿物相互作用，生成易被农作物吸收的硝酸盐。硝酸盐属于氮肥，因而有“雷雨发庄稼”的说法。C项错误，“真金不怕火炼”是指金的熔点高于一般炉火火焰的温度，与硬度无关。D项错误，“酒香不怕巷子深”是因为酒香味分子在不停地运动到空气中，所以很远的地方都能闻到酒香，体现了分子的无规则运动。故正确答案为B。", "tag": "科技常识"}
);
